--
-- Name: reject_compact_session_command_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_compact_session_command_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.result_kind <> 'pending' THEN
            RAISE EXCEPTION 'compaction command must begin pending'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'compaction command is not deletable'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        OLD.command_id,
        OLD.command_kind,
        OLD.storage_version,
        OLD.session_id,
        OLD.requested_through_position,
        OLD.automatic_for_turn_id,
        OLD.model_call_id
    ) IS DISTINCT FROM ROW(
        NEW.command_id,
        NEW.command_kind,
        NEW.storage_version,
        NEW.session_id,
        NEW.requested_through_position,
        NEW.automatic_for_turn_id,
        NEW.model_call_id
    ) THEN
        RAISE EXCEPTION 'compaction command request is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.result_kind <> 'pending'
       OR NEW.result_kind NOT IN ('applied', 'failed')
    THEN
        RAISE EXCEPTION 'invalid compaction command result transition'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_content_part_insert_after_parent_transaction(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_content_part_insert_after_parent_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_creation_xid xid8;
BEGIN
    IF TG_TABLE_NAME = 'submit_input_command_content_part' THEN
        SELECT parent.content_parts_creation_xid
          INTO parent_creation_xid
          FROM submit_input_command AS parent
         WHERE parent.command_id = NEW.command_id;
    ELSE
        SELECT parent.content_parts_creation_xid
          INTO parent_creation_xid
          FROM accepted_input AS parent
         WHERE parent.accepted_input_id = NEW.accepted_input_id;
    END IF;

    IF parent_creation_xid IS DISTINCT FROM pg_current_xact_id() THEN
        RAISE EXCEPTION 'content parts are immutable after parent creation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_context_compaction_input_semantics_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_context_compaction_input_semantics_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.usage_input_includes_cache_tokens IS DISTINCT FROM
       NEW.usage_input_includes_cache_tokens
    THEN
        RAISE EXCEPTION 'compaction model call input semantics are immutable'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'context_compaction_input_semantics_immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_context_compaction_model_call_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_context_compaction_model_call_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state_kind <> 'prepared'
            OR NEW.terminal_disposition_kind IS NOT NULL
            OR NEW.input_tokens IS NOT NULL
            OR NEW.output_tokens IS NOT NULL
            OR NEW.cache_read_input_tokens IS NOT NULL
            OR NEW.cache_creation_input_tokens IS NOT NULL
        THEN
            RAISE EXCEPTION 'compaction model call must be inserted as Prepared'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'compaction model call is not deletable'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        OLD.model_call_id,
        OLD.session_id,
        OLD.direct_model_selection_id,
        OLD.resolved_provider_model_identity_id,
        OLD.source_frontier_id,
        OLD.credential_reference
    ) IS DISTINCT FROM ROW(
        NEW.model_call_id,
        NEW.session_id,
        NEW.direct_model_selection_id,
        NEW.resolved_provider_model_identity_id,
        NEW.source_frontier_id,
        NEW.credential_reference
    ) THEN
        RAISE EXCEPTION 'compaction model call authorization facts are immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'terminal' THEN
        RAISE EXCEPTION 'terminal compaction model call is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'prepared'
       AND NEW.state_kind = 'terminal'
       AND NEW.terminal_disposition_kind NOT IN ('known_failed', 'cancelled')
    THEN
        RAISE EXCEPTION 'prepared compaction call cannot record provider outcome'
            USING ERRCODE = '23514';
    END IF;

    IF NOT (
        (OLD.state_kind = 'prepared' AND NEW.state_kind IN ('in_flight', 'terminal'))
        OR (OLD.state_kind = 'in_flight' AND NEW.state_kind = 'terminal')
    ) THEN
        RAISE EXCEPTION 'invalid compaction model call transition'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.state_kind <> 'terminal' AND (
        NEW.input_tokens IS NOT NULL
        OR NEW.output_tokens IS NOT NULL
        OR NEW.cache_read_input_tokens IS NOT NULL
        OR NEW.cache_creation_input_tokens IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'compaction usage is terminal evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_context_frontier_member_out_of_bounds(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_context_frontier_member_out_of_bounds() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_member_count numeric(20, 0);
    prefix_member_count numeric(20, 0) := 0;
BEGIN
    SELECT frontier.member_count,
           COALESCE(prefix.member_count, 0)
      INTO declared_member_count, prefix_member_count
      FROM context_frontier AS frontier
      LEFT JOIN context_frontier AS prefix
        ON prefix.owning_session_id = frontier.owning_session_id
       AND prefix.context_frontier_id =
               frontier.prefix_context_frontier_id
     WHERE frontier.owning_session_id = NEW.owning_session_id
       AND frontier.context_frontier_id = NEW.context_frontier_id;

    -- Deltas may precede their deferred-FK header in one transaction. The
    -- header's deferred completeness check validates that ordering.
    IF FOUND
       AND (
           NEW.member_position <= prefix_member_count
           OR NEW.member_position > declared_member_count
       )
    THEN
        RAISE EXCEPTION
            'context frontier delta position % lies outside (%, %]',
            NEW.member_position,
            prefix_member_count,
            declared_member_count
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'context_frontier_member_within_declared_count';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_eval_call_outside_run_recording(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_eval_call_outside_run_recording() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    run_transaction xid8;
BEGIN
    EXECUTE pg_catalog.format(
        'SELECT recording_transaction_id '
        'FROM %I.approval_judge_eval_run WHERE eval_run_id = $1',
        TG_TABLE_SCHEMA
    )
    INTO run_transaction
    USING NEW.eval_run_id;
    IF run_transaction IS NULL THEN
        RAISE EXCEPTION 'approval_judge_eval_call requires its run row first'
            USING ERRCODE = '23514';
    END IF;
    IF run_transaction <> pg_current_xact_id() THEN
        RAISE EXCEPTION 'approval_judge_eval_call is sealed with its run; '
            'rows admit insertion only in the recording transaction'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$_$;


