--
-- Name: reject_tool_approval_judge_call_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_tool_approval_judge_call_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    active_wait boolean;
    request_posture text;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT approval_posture INTO request_posture
          FROM tool_request
         WHERE request_id = NEW.request_id
           FOR UPDATE;
        SELECT true INTO active_wait
          FROM turn_lifecycle AS lifecycle
         WHERE lifecycle.turn_id = NEW.turn_id
           AND lifecycle.session_id = NEW.session_id
           AND lifecycle.state_kind = 'active'
           AND lifecycle.active_phase_kind = 'awaiting_tool_approval'
           AND lifecycle.approval_tool_request_id = NEW.request_id
           FOR UPDATE;
        IF active_wait IS DISTINCT FROM true OR EXISTS (
            SELECT 1
              FROM tool_approval_decision AS decision
             WHERE decision.request_id = NEW.request_id
        ) THEN
            RAISE EXCEPTION 'approval judge call lacks an active approval wait'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'tool_approval_judge_requires_active_wait';
        END IF;
        IF NEW.usage_provenance_kind <> 'reported' THEN
            RAISE EXCEPTION 'prepared approval judge usage must be reported'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'tool_approval_judge_prepared_usage_is_reported';
        END IF;
        IF NEW.state_kind <> 'prepared'
            OR NEW.terminal_disposition_kind IS NOT NULL
            OR NEW.recommendation_kind IS NOT NULL
            OR NEW.rationale IS NOT NULL
            OR NEW.input_tokens IS NOT NULL
            OR NEW.output_tokens IS NOT NULL
            OR NEW.cache_read_input_tokens IS NOT NULL
            OR NEW.cache_creation_input_tokens IS NOT NULL
        THEN
            RAISE EXCEPTION 'approval judge call must be inserted as Prepared'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'approval judge call is not deletable'
            USING ERRCODE = '23514';
    END IF;
    IF ROW(
        OLD.model_call_id, OLD.request_id, OLD.session_id, OLD.turn_id,
        OLD.direct_model_selection_id,
        OLD.resolved_provider_model_identity_id,
        OLD.credential_reference, OLD.usage_input_includes_cache_tokens
    ) IS DISTINCT FROM ROW(
        NEW.model_call_id, NEW.request_id, NEW.session_id, NEW.turn_id,
        NEW.direct_model_selection_id,
        NEW.resolved_provider_model_identity_id,
        NEW.credential_reference, NEW.usage_input_includes_cache_tokens
    ) OR (
        NEW.usage_provenance_kind IS DISTINCT FROM OLD.usage_provenance_kind
        AND NOT (
            OLD.state_kind <> 'terminal'
            AND NEW.state_kind = 'terminal'
        )
    ) THEN
        RAISE EXCEPTION 'approval judge authorization facts are immutable'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.state_kind = 'terminal' THEN
        RAISE EXCEPTION 'terminal approval judge call is immutable'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.state_kind = 'prepared'
       AND NEW.state_kind = 'terminal'
       AND NEW.terminal_disposition_kind NOT IN ('known_failed', 'cancelled')
    THEN
        RAISE EXCEPTION 'prepared approval judge cannot record provider outcome'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.state_kind = 'prepared'
       AND NEW.state_kind = 'terminal'
       AND (
            NEW.input_tokens IS NOT NULL
            OR NEW.output_tokens IS NOT NULL
            OR NEW.cache_read_input_tokens IS NOT NULL
            OR NEW.cache_creation_input_tokens IS NOT NULL
       )
    THEN
        RAISE EXCEPTION 'unsent approval judge cannot record provider usage'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'tool_approval_judge_unsent_has_no_usage';
    END IF;
    IF NOT (
        (OLD.state_kind = 'prepared' AND NEW.state_kind IN ('in_flight', 'terminal'))
        OR (OLD.state_kind = 'in_flight' AND NEW.state_kind = 'terminal')
    ) THEN
        RAISE EXCEPTION 'invalid approval judge call transition'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.state_kind <> 'terminal' AND (
        NEW.input_tokens IS NOT NULL
        OR NEW.output_tokens IS NOT NULL
        OR NEW.cache_read_input_tokens IS NOT NULL
        OR NEW.cache_creation_input_tokens IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'approval judge usage is terminal evidence'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.state_kind = 'terminal'
       AND NEW.terminal_disposition_kind = 'completed'
    THEN
        SELECT approval_posture INTO request_posture
          FROM tool_request WHERE request_id = NEW.request_id;
        IF request_posture = 'auto'
           OR (request_posture = 'human'
               AND NEW.recommendation_kind <> 'escalate_to_human')
        THEN
            RAISE EXCEPTION 'approval judge recommendation exceeds frozen posture'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'tool_approval_judge_recommendation_within_posture';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_tool_attempt_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_tool_attempt_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state_kind <> 'prepared' THEN
            RAISE EXCEPTION 'tool attempt must be inserted as Prepared'
                USING
                    ERRCODE = '23514',
                    CONSTRAINT = 'tool_attempt_inserted_prepared';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'tool_attempt is not deletable'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        OLD.attempt_id,
        OLD.request_id,
        OLD.session_id,
        OLD.turn_id,
        OLD.issuing_turn_attempt_id,
        OLD.effect_class,
        OLD.dispatch_generation
    ) IS DISTINCT FROM ROW(
        NEW.attempt_id,
        NEW.request_id,
        NEW.session_id,
        NEW.turn_id,
        NEW.issuing_turn_attempt_id,
        NEW.effect_class,
        NEW.dispatch_generation
    ) THEN
        RAISE EXCEPTION 'tool attempt authorization facts are immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'terminal' THEN
        RAISE EXCEPTION 'terminal tool attempt is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF NOT (
        OLD.state_kind = NEW.state_kind
        OR (
            OLD.state_kind = 'prepared'
            AND NEW.state_kind IN ('in_flight', 'terminal')
        )
        OR (
            OLD.state_kind = 'in_flight'
            AND NEW.state_kind = 'terminal'
        )
    ) THEN
        RAISE EXCEPTION 'tool attempt transition is not monotonic'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'prepared'
       AND NEW.state_kind = 'terminal'
       AND (
            NEW.terminal_disposition_kind <> 'known_failed'
            OR NEW.error_kind NOT IN (
                'unknown_tool',
                'invalid_arguments',
                'preauthorization_rejected',
                'crash_lost'
            )
       )
    THEN
        RAISE EXCEPTION 'unsent tool attempt has impossible terminal evidence'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'in_flight'
       AND NEW.state_kind = 'terminal'
       AND (
            NEW.error_kind IN (
                'unknown_tool',
                'invalid_arguments',
                'preauthorization_rejected'
            )
            OR (
                OLD.effect_class = 'external_effect'
                AND NEW.error_kind = 'crash_lost'
                -- Carried unchanged from
                -- 202608080101_runner_recovery_turn_phase.sql: only the exact
                -- current lineage — the active awaiting-recovery phase bound to
                -- this attempt, its bound lease, and that lease's current
                -- lost-unclaimed head — admits crash loss for a dispatched
                -- external effect. An attempt_id match alone would accept a
                -- stale proof from an earlier lease generation.
                AND NOT EXISTS (
                    SELECT 1
                      FROM turn_lifecycle AS lifecycle
                      JOIN runner_physical_attempt_lease_binding AS binding
                        ON binding.attempt_id = OLD.attempt_id
                      JOIN runner_lease_generation AS lease
                        ON lease.lease_id = binding.lease_id
                       AND lease.attempt_id = OLD.attempt_id
                       AND lease.session_id = OLD.session_id
                      JOIN runner_current_lease_event AS lease_head
                        ON lease_head.lease_id = lease.lease_id
                       AND lease_head.generation = lease.generation
                      JOIN runner_lease_event AS lease_event
                        ON lease_event.lease_id = lease_head.lease_id
                       AND lease_event.generation = lease_head.generation
                       AND lease_event.event_ordinal = lease_head.event_ordinal
                     WHERE lifecycle.session_id = OLD.session_id
                       AND lifecycle.turn_id = OLD.turn_id
                       AND lifecycle.state_kind = 'active'
                       AND lifecycle.active_phase_kind =
                            'awaiting_runner_recovery'
                       AND lifecycle.runner_recovery_tool_attempt_id =
                            OLD.attempt_id
                       AND lease_event.state_kind = 'lost_unclaimed'
                )
            )
       )
    THEN
        RAISE EXCEPTION 'dispatched tool attempt has impossible terminal evidence'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_tool_continuation_context_headroom_truncate(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_tool_continuation_context_headroom_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% cannot be truncated', TG_TABLE_NAME
        USING ERRCODE = '23514';
END;
$$;


--
-- Name: reject_turn_attempt_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_turn_attempt_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owning_turn_state text;
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE turn_lifecycle
           SET attempt_history_present = true
         WHERE turn_id = NEW.turn_id
           AND session_id = NEW.session_id
           AND state_kind <> 'terminal'
        RETURNING state_kind
          INTO owning_turn_state;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'a terminal turn cannot acquire another attempt'
                USING ERRCODE = '23514';
        END IF;

        IF NEW.state_kind <> 'prepared' THEN
            RAISE EXCEPTION 'turn attempt must be inserted as prepared'
                USING
                    ERRCODE = '23514',
                    CONSTRAINT = 'turn_attempt_inserted_prepared';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'turn_attempt is not deletable'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        OLD.turn_attempt_id,
        OLD.turn_id,
        OLD.session_id,
        OLD.continued_from_attempt_id
    ) IS DISTINCT FROM ROW(
        NEW.turn_attempt_id,
        NEW.turn_id,
        NEW.session_id,
        NEW.continued_from_attempt_id
    ) THEN
        RAISE EXCEPTION 'turn attempt identity, ownership, and predecessor are immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'ended' THEN
        RAISE EXCEPTION 'ended turn attempt is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.interrupt_command_id IS NOT NULL
       AND ROW(
            OLD.interrupt_command_id,
            OLD.interrupt_predecessor_turn_id
       ) IS DISTINCT FROM ROW(
            NEW.interrupt_command_id,
            NEW.interrupt_predecessor_turn_id
       )
    THEN
        RAISE EXCEPTION 'turn attempt interrupt proof is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF NOT (
        OLD.state_kind = NEW.state_kind
        OR (
            OLD.state_kind = 'prepared'
            AND NEW.state_kind IN ('running', 'ended')
        )
        OR (
            OLD.state_kind = 'running'
            AND NEW.state_kind IN ('stop_requested', 'ended')
        )
        OR (
            OLD.state_kind = 'stop_requested'
            AND NEW.state_kind = 'ended'
        )
    ) THEN
        RAISE EXCEPTION 'turn attempt transition is not monotonic'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_turn_delegation_runtime_terminal_reversal(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_turn_delegation_runtime_terminal_reversal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.delegation_runtime_terminal AND NOT NEW.delegation_runtime_terminal THEN
        RAISE EXCEPTION 'delegation runtime terminalization is monotonic'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_turn_lifecycle_invalid_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_turn_lifecycle_invalid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state_kind <> 'queued' THEN
            RAISE EXCEPTION 'turn lifecycle must be inserted as queued'
                USING
                    ERRCODE = '23514',
                    CONSTRAINT = 'turn_lifecycle_inserted_queued';
        END IF;
        IF NEW.attempt_history_present THEN
            RAISE EXCEPTION 'turn lifecycle must be inserted without attempt history'
                USING ERRCODE = '23514';
        END IF;
        IF NEW.pinned_provider_model_identity_id IS NOT NULL THEN
            RAISE EXCEPTION 'queued turn lifecycle cannot begin with a provider target pin'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'turn_lifecycle is not deletable'
            USING ERRCODE = '23514';
    END IF;

    IF ROW(
        OLD.turn_id,
        OLD.session_id,
        OLD.origin_accepted_input_id,
        OLD.acceptance_position
    ) IS DISTINCT FROM ROW(
        NEW.turn_id,
        NEW.session_id,
        NEW.origin_accepted_input_id,
        NEW.acceptance_position
    ) THEN
        RAISE EXCEPTION 'turn lifecycle identity, ownership, origin, and order are immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.start_lineage_kind IS NOT NULL
       AND ROW(
            OLD.start_lineage_kind,
            OLD.immediate_predecessor_turn_id,
            OLD.starting_frontier_id
       ) IS DISTINCT FROM ROW(
            NEW.start_lineage_kind,
            NEW.immediate_predecessor_turn_id,
            NEW.starting_frontier_id
       )
    THEN
        RAISE EXCEPTION 'turn start is write-once'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.pinned_provider_model_identity_id IS NOT NULL
       AND NEW.pinned_provider_model_identity_id
           IS DISTINCT FROM OLD.pinned_provider_model_identity_id
    THEN
        RAISE EXCEPTION 'turn-level provider target pin is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.pinned_provider_model_identity_id IS NULL
       AND NEW.pinned_provider_model_identity_id IS NOT NULL
       AND (
            OLD.state_kind IS DISTINCT FROM 'active'
            OR NEW.state_kind IS DISTINCT FROM 'active'
            OR OLD.active_phase_kind IS DISTINCT FROM 'running'
            OR NEW.active_phase_kind IS DISTINCT FROM 'running'
            OR OLD.current_attempt_id IS NULL
            OR NEW.current_attempt_id IS DISTINCT FROM OLD.current_attempt_id
       )
    THEN
        RAISE EXCEPTION 'provider target can be pinned only for the current running attempt'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'terminal' THEN
        RAISE EXCEPTION 'terminal turn lifecycle is immutable'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.attempt_history_present AND NOT NEW.attempt_history_present THEN
        RAISE EXCEPTION 'turn attempt history marker is write-once'
            USING ERRCODE = '23514';
    END IF;
    IF NOT (
        OLD.state_kind = NEW.state_kind
        OR (OLD.state_kind = 'queued' AND NEW.state_kind IN ('active', 'terminal'))
        OR (OLD.state_kind = 'active' AND NEW.state_kind = 'terminal')
    ) THEN
        RAISE EXCEPTION 'turn lifecycle transition is not monotonic'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'active'
       AND OLD.active_phase_kind IN (
            'awaiting_model_call_recovery',
            'awaiting_tool_recovery'
       )
       AND NEW.state_kind = 'active'
    THEN
        RAISE EXCEPTION 'recovery wait cannot reopen without a recovery decision'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'active'
       AND OLD.active_phase_kind = 'running'
       AND NEW.state_kind = 'active'
       AND NEW.active_phase_kind = 'running'
       AND OLD.current_attempt_id IS DISTINCT FROM NEW.current_attempt_id
       AND NOT EXISTS (
            SELECT 1
              FROM credential_pool_availability_successor AS successor
              JOIN model_call AS predecessor
                ON predecessor.model_call_id = successor.predecessor_model_call_id
             WHERE successor.successor_turn_attempt_id = NEW.current_attempt_id
               AND predecessor.turn_attempt_id = OLD.current_attempt_id
               AND predecessor.turn_id = OLD.turn_id
               AND predecessor.session_id = OLD.session_id
               AND predecessor.state_kind = 'terminal'
               AND predecessor.terminal_disposition_kind = 'known_failed'
       )
       AND (
            NEW.active_tool_round_call_id IS NULL
            OR NOT EXISTS (
                SELECT 1
                  FROM turn_attempt
                 WHERE turn_attempt_id = OLD.current_attempt_id
                   AND turn_id = OLD.turn_id
                   AND session_id = OLD.session_id
                   AND state_kind = 'ended'
                   AND end_disposition = 'yielded_to_durable_wait'
            )
       )
    THEN
        RAISE EXCEPTION 'running turn cannot replace its current attempt'
            USING ERRCODE = '23514';
    END IF;

    IF OLD.state_kind = 'queued'
       AND NEW.state_kind = 'terminal'
       AND NEW.attempt_history_present
    THEN
        RAISE EXCEPTION 'a queued turn must terminalize without attempt history'
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'turn_lifecycle_queued_failure_without_attempt';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: reject_turn_lifecycle_origin_kind_change(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_turn_lifecycle_origin_kind_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.origin_kind <> NEW.origin_kind THEN
        RAISE EXCEPTION 'turn lifecycle origin kind is immutable'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_turn_restart_recovery_origin_truncate(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_turn_restart_recovery_origin_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% cannot be truncated', TG_TABLE_NAME
        USING ERRCODE = '23514';
END;
$$;


--
-- Name: reject_web_usage_projection_truncate(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reject_web_usage_projection_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'web usage projection cannot be truncated'
        USING ERRCODE = '23514';
