--
-- Name: remember_repo_watch_repository_key(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION remember_repo_watch_repository_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO repo_watch_repository_key (repository)
    VALUES (NEW.repository)
    ON CONFLICT DO NOTHING;
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_branch_is_valid(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_branch_is_valid(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT octet_length(candidate) BETWEEN 1 AND 255
       AND candidate <> '@'
       AND left(candidate, 1) <> '-'
       AND right(candidate, 1) <> '.'
       AND strpos(candidate, '..') = 0
       AND strpos(candidate, '@{') = 0
       AND NOT EXISTS (
            SELECT 1
            FROM generate_series(1, length(candidate)) AS character(position)
            WHERE ascii(substr(candidate, character.position, 1)) <= 32
               OR ascii(substr(candidate, character.position, 1)) = 127
               OR substr(candidate, character.position, 1)
                    = ANY (ARRAY['~', '^', ':', '?', '*', '[', chr(92)])
       )
       AND NOT EXISTS (
            SELECT 1
            FROM unnest(string_to_array(candidate, '/')) AS part(value)
            WHERE part.value = ''
               OR left(part.value, 1) = '.'
               OR right(part.value, 5) = '.lock'
       )
$$;


--
-- Name: repo_watch_convergence_check_names_are_valid(text[]); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_convergence_check_names_are_valid(candidate text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT COALESCE(array_ndims(candidate), 1) = 1
       AND COALESCE(array_lower(candidate, 1), 1) = 1
       AND cardinality(candidate) <= 10000
       AND candidate = ARRAY(
            SELECT value COLLATE "C"
              FROM unnest(candidate) AS item(value)
             ORDER BY value COLLATE "C"
       )
       AND NOT EXISTS (
            SELECT 1 FROM unnest(candidate) AS item(value)
             WHERE value IS NULL OR octet_length(value) NOT BETWEEN 1 AND 256
       )
$$;


--
-- Name: repo_watch_convergence_threads_are_valid(text[]); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_convergence_threads_are_valid(candidate text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT COALESCE(array_ndims(candidate), 1) = 1
       AND COALESCE(array_lower(candidate, 1), 1) = 1
       AND cardinality(candidate) <= 10000
       AND candidate = ARRAY(
            SELECT DISTINCT value COLLATE "C"
              FROM unnest(candidate) AS item(value)
             ORDER BY value COLLATE "C"
       )
       AND NOT EXISTS (
            SELECT 1 FROM unnest(candidate) AS item(value)
             WHERE value IS NULL OR octet_length(value) NOT BETWEEN 1 AND 256
       )
$$;


--
-- Name: repo_watch_dispatch_attempt_budget(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_dispatch_attempt_budget() RETURNS bigint
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT 6::bigint;
$$;


--
-- Name: repo_watch_dispatch_batch_has_complete_actions(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_dispatch_batch_has_complete_actions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_dispatch_id uuid;
    expected_count integer;
    actual_count bigint;
    first_ordinal integer;
    last_ordinal integer;
BEGIN
    candidate_dispatch_id := COALESCE(NEW.dispatch_id, OLD.dispatch_id);
    SELECT batch.action_count
      INTO expected_count
      FROM repo_watch_dispatch_batch AS batch
     WHERE batch.dispatch_id = candidate_dispatch_id;
    IF expected_count IS NULL THEN
        RETURN NULL;
    END IF;
    SELECT count(*), min(action.action_ordinal), max(action.action_ordinal)
      INTO actual_count, first_ordinal, last_ordinal
      FROM repo_watch_dispatch_action AS action
     WHERE action.dispatch_id = candidate_dispatch_id;
    IF actual_count <> expected_count
       OR first_ordinal <> 1
       OR last_ordinal <> expected_count THEN
        RAISE EXCEPTION 'repository-watch dispatch action inventory is incomplete'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_dispatch_singleton_lock_key(text, bigint, text, text, numeric, numeric); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_dispatch_singleton_lock_key(rule_id text, rule_version bigint, singleton_scope text, singleton_repository text, singleton_pull_request_number numeric, singleton_stack_root_pull_request_number numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT concat_ws(
        E'\x1f',
        'repo-watch',
        rule_id,
        rule_version::text,
        singleton_scope,
        coalesce(singleton_repository, ''),
        coalesce(singleton_pull_request_number::text, ''),
        coalesce(singleton_stack_root_pull_request_number::text, '')
    );
$$;


--
-- Name: repo_watch_labels_are_valid(text[]); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_labels_are_valid(candidate text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT COALESCE(array_ndims(candidate), 1) = 1
       AND COALESCE(array_lower(candidate, 1), 1) = 1
       AND candidate = ARRAY(
            SELECT DISTINCT label.value COLLATE "C"
            FROM unnest(candidate) AS label(value)
            ORDER BY label.value COLLATE "C"
       )
       AND NOT EXISTS (
            SELECT 1
            FROM unnest(candidate) AS label(value)
            WHERE value IS NULL
               OR octet_length(value) NOT BETWEEN 1 AND 200
               OR char_length(value) > 50
       )
$$;


--
-- Name: repo_watch_login_is_valid(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_login_is_valid(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
    SELECT candidate = lower(candidate)
       AND octet_length(candidate) BETWEEN 1 AND 44
       AND octet_length(normalized.base) BETWEEN 1 AND 39
       AND normalized.base COLLATE "C" ~ '^[a-z0-9_-]+$'
       AND left(normalized.base, 1) <> '-'
       AND right(normalized.base, 1) <> '-'
       AND strpos(normalized.base, '--') = 0
    FROM (
        SELECT CASE
            WHEN right(candidate, 5) = '[bot]'
                THEN left(candidate, length(candidate) - 5)
            ELSE candidate
        END AS base
    ) AS normalized
$_$;


--
-- Name: repo_watch_owe_dispatch_requeue(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_owe_dispatch_requeue(candidate_dispatch_id uuid, completed_session_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_repository text;
    candidate_rule_id text;
    candidate_rule_version bigint;
    candidate_singleton_key text;
    terminal_goal_kind text;
    owed_obligation_id uuid;
BEGIN
    -- The terminal event that matters is the one ending the generation this
    -- dispatch commissioned, not whatever the session is doing now. A session
    -- whose sibling action still holds the batch unreleased may legally accept
    -- an unrelated successor goal, and reading that successor's termination
    -- would owe a requeue for work the dispatched generation already converged.
    SELECT current_goal.event_kind
      INTO terminal_goal_kind
      FROM goal_event AS current_goal
     WHERE current_goal.session_id = completed_session_id
       AND current_goal.generation = (
            SELECT dispatched_turn.goal_generation
              FROM repo_watch_dispatch_action AS action
              JOIN repo_watch_dispatch_delivery AS delivery
                ON delivery.dispatch_id = action.dispatch_id
               AND delivery.action_ordinal = action.action_ordinal
              JOIN goal_turn AS dispatched_turn
                ON dispatched_turn.session_id = action.session_id
               AND dispatched_turn.turn_id = delivery.turn_id
             WHERE action.dispatch_id = candidate_dispatch_id
               AND action.session_id = completed_session_id
       )
     ORDER BY current_goal.event_ordinal DESC
     LIMIT 1;

    SELECT origin.repository, batch.rule_id, batch.rule_version,
           repo_watch_dispatch_singleton_lock_key(
                batch.rule_id,
                batch.rule_version,
                batch.singleton_scope,
                batch.singleton_repository,
                batch.singleton_pull_request_number,
                batch.singleton_stack_root_pull_request_number
           )
      INTO candidate_repository, candidate_rule_id, candidate_rule_version,
           candidate_singleton_key
      FROM repo_watch_dispatch_batch AS batch
      JOIN repo_watch_event AS origin ON origin.event_id = batch.event_id
     WHERE batch.dispatch_id = candidate_dispatch_id;

    -- Termination runs inside the transaction that ends the goal, which
    -- already holds that session's row. Lifecycle-cutoff processing takes
    -- the repository advisory key and then waits for the same session row,
    -- so taking the repository key here would invert that order and deadlock
    -- a goal pass against a cutoff attempt. Termination therefore takes only
    -- keys no repository-key holder waits behind a session row for.
    --
    -- Fresh evaluation and obligation admission take the singleton key, so a
    -- match racing this termination waits and then joins the obligation
    -- through its settle-guarded update, rather than aborting on the
    -- active-singleton index. Deactivation is serialized by row: inserting
    -- into repo_watch_rule_deactivation takes a key-share lock on the
    -- activation row this locks exclusively, so the two cannot both pass
    -- their checks against a snapshot predating the other's row.
    PERFORM pg_advisory_xact_lock(hashtextextended(candidate_singleton_key, 0));

    PERFORM 1
      FROM repo_watch_rule_activation AS activation
     WHERE activation.repository = candidate_repository
       AND activation.rule_id = candidate_rule_id
       AND activation.rule_version = candidate_rule_version
       FOR UPDATE;

    -- A terminal session leaves the current dispatch state owed unless it
    -- achieved against state that is still current. The active-singleton
    -- index collapses sibling terminations and preserves any later matching
    -- event already recorded by ordinary evaluation.
    WITH owed AS (
    INSERT INTO repo_watch_dispatch_obligation
        (obligation_id, repository, rule_id, rule_version,
         singleton_scope, singleton_repository, singleton_pull_request_number,
         singleton_stack_root_pull_request_number, first_repository,
         first_event_id, latest_event_id, matched_event_count,
         blocking_dispatch_id, failed_attempts, last_failed_attempt_at,
         counted_dispatch_id)
    SELECT gen_random_uuid(), origin.repository, batch.rule_id,
           batch.rule_version, batch.singleton_scope,
           batch.singleton_repository, batch.singleton_pull_request_number,
           batch.singleton_stack_root_pull_request_number, origin.repository,
           origin.event_id, origin.event_id, 1, batch.dispatch_id,
           -- The settled predecessor carries the lineage count; a dispatch
           -- admitted from a fresh match settled none and starts the lineage.
           coalesce(settled.failed_attempts, 0) + 1,
           clock_timestamp(),
           batch.dispatch_id
      FROM repo_watch_dispatch_batch AS batch
      JOIN repo_watch_event AS origin ON origin.event_id = batch.event_id
      LEFT JOIN repo_watch_event AS delivered
        ON delivered.event_id = batch.delivered_state_event_id
      LEFT JOIN repo_watch_dispatch_obligation AS settled
        ON settled.settled_dispatch_id = batch.dispatch_id
     WHERE batch.dispatch_id = candidate_dispatch_id
       AND EXISTS (
            SELECT 1
              FROM repo_watch_dispatch_action AS action
             WHERE action.dispatch_id = batch.dispatch_id
               AND action.session_id = completed_session_id
       )
       AND terminal_goal_kind IN ('blocked', 'achieved', 'user_stopped')
       -- A branch target carries no durable revision at all: its only event
       -- kind records a workflow conclusion, so achievement is its own seal.
       -- A pull-request target seals only when the state this batch delivered is
       -- known and is still the pull request's latest durable head.
       AND NOT (
            terminal_goal_kind = 'achieved'
            AND (
                origin.target_kind <> 'pull_request'
                OR (
                    batch.delivered_state_event_id IS NOT NULL
                    AND delivered.head_sha = (
                        SELECT current_state.head_sha
                          FROM repo_watch_event AS current_state
                         WHERE current_state.repository = origin.repository
                           AND current_state.pull_request_number
                                = origin.pull_request_number
                         ORDER BY current_state.cursor_generation DESC,
                                  current_state.event_ordinal DESC
                         LIMIT 1
                    )
                )
            )
       )
       AND NOT EXISTS (
            SELECT 1
              FROM repo_watch_rule_deactivation AS deactivation
             WHERE deactivation.repository = origin.repository
               AND deactivation.rule_id = batch.rule_id
               AND deactivation.rule_version = batch.rule_version
       )
       -- A later close or merge makes outstanding work stale. The cutoff event
       -- itself is the fact a rule may match, not work invalidated by that
       -- fact, so a dispatch of the latest cutoff keeps its requeue -- but only
       -- while that cutoff is still latest. A reopen makes the close obsolete,
       -- and requeueing it would run close automation against an open pull
       -- request, so the opened arm admits nonterminal origins only.
       AND (
            origin.target_kind <> 'pull_request'
            OR EXISTS (
                SELECT 1
                  FROM (
                        SELECT lifecycle.event_id, lifecycle.event_kind
                          FROM repo_watch_event AS lifecycle
                         WHERE lifecycle.repository = origin.repository
                           AND lifecycle.pull_request_number
                                = origin.pull_request_number
                           AND lifecycle.event_kind IN (
                                'pull_request_opened',
                                'pull_request_closed',
                                'pull_request_merged'
                           )
                         ORDER BY lifecycle.cursor_generation DESC,
                                  lifecycle.event_ordinal DESC
                         LIMIT 1
                  ) AS latest_lifecycle
                 WHERE (
                        latest_lifecycle.event_kind = 'pull_request_opened'
                        AND origin.event_kind NOT IN (
                            'pull_request_closed',
                            'pull_request_merged'
                        )
                 )
                    OR latest_lifecycle.event_id = origin.event_id
            )
       )
    -- Only an active obligation on this singleton may absorb a termination.
    -- A bare conflict clause would also swallow an identifier collision with
    -- an already settled obligation and silently drop the requeue.
    ON CONFLICT (rule_id, rule_version, singleton_scope, singleton_repository,
                 singleton_pull_request_number,
                 singleton_stack_root_pull_request_number)
        WHERE settled_kind IS NULL
    -- The absorbing obligation carries the lineage count forward. GREATEST
    -- rather than addition because a match that opened the row while the batch
    -- ran contributes a count of zero that must not erase the lineage. The
    -- WHERE is what makes one batch one attempt: the second and later siblings
    -- of the same batch find their own identifier already recorded and change
    -- nothing, so neither the count nor a park release taken since the first
    -- sibling terminated is disturbed.
    DO UPDATE SET
        failed_attempts = GREATEST(
            repo_watch_dispatch_obligation.failed_attempts,
            EXCLUDED.failed_attempts
        ),
        last_failed_attempt_at = clock_timestamp(),
        counted_dispatch_id = EXCLUDED.counted_dispatch_id
    WHERE repo_watch_dispatch_obligation.counted_dispatch_id
           IS DISTINCT FROM EXCLUDED.counted_dispatch_id
    RETURNING obligation_id
    )
    SELECT owed.obligation_id INTO owed_obligation_id FROM owed;

    -- Same transaction as the count that exhausted the budget, so an
    -- obligation is never readable with its budget spent and its parked state
    -- still unwritten.
    IF owed_obligation_id IS NOT NULL THEN
        PERFORM repo_watch_park_exhausted_dispatch_obligation(owed_obligation_id);
    END IF;
END;
$$;


--
-- Name: repo_watch_park_exhausted_dispatch_obligation(uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_park_exhausted_dispatch_obligation(subject_obligation_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    parked_attempts bigint;
    progress_event_id uuid;
BEGIN
    -- The state the exhausting attempt was actually given, not the obligation's
    -- latest-event projection: a fresh match arriving while that attempt ran
    -- coalesces into the same row and advances the projection, so parking
    -- against it would park state no attempt has been spent on and would hide
    -- that state from the progress test below. Only a batch admitted before the
    -- delivered state was recorded has none, and there the projection is all
    -- there is.
    UPDATE repo_watch_dispatch_obligation
       SET parked_at = clock_timestamp(),
           parked_state_event_id = coalesce(
                (
                    SELECT batch.delivered_state_event_id
                      FROM repo_watch_dispatch_batch AS batch
                     WHERE batch.dispatch_id = counted_dispatch_id
                ),
                latest_event_id
           )
     WHERE obligation_id = subject_obligation_id
       AND settled_kind IS NULL
       AND parked_at IS NULL
       AND failed_attempts >= repo_watch_dispatch_attempt_budget()
    RETURNING failed_attempts INTO parked_attempts;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    PERFORM repo_watch_record_dispatch_obligation_park_transition(
        subject_obligation_id,
        'parked',
        parked_attempts,
        NULL::text,
        NULL::uuid,
        NULL::text
    );

    -- The pull request may have moved while the exhausting attempt ran, under
    -- an event that reached its evaluation before there was a park to release.
    -- Nothing restates that fact afterwards, so it is read from the durable
    -- record here. Parking first and releasing from that fact, rather than
    -- refusing to park, is what spends it: the lineage keeps its budget, and
    -- the same fact cannot buy a second one at the next exhaustion.
    SELECT later.event_id
      INTO progress_event_id
      FROM repo_watch_dispatch_obligation AS obligation
      JOIN repo_watch_event AS parked_state
        ON parked_state.event_id = obligation.parked_state_event_id
      JOIN repo_watch_event AS later
        ON later.repository = parked_state.repository
       AND later.pull_request_number = parked_state.pull_request_number
     WHERE obligation.obligation_id = subject_obligation_id
       AND parked_state.target_kind = 'pull_request'
       AND later.target_kind = 'pull_request'
       AND (later.cursor_generation, later.event_ordinal)
            > (parked_state.cursor_generation, parked_state.event_ordinal)
       AND (
            later.head_sha IS DISTINCT FROM parked_state.head_sha
            OR later.event_kind IN (
                'review_submitted', 'thread_opened', 'thread_resolved'
            )
       )
       -- Already spent by this lineage, by identity anywhere in it, or by
       -- order within the pull request this fact is about. Several facts can
       -- follow one stalled state, this selection takes the newest, and the
       -- older ones stay unevaluated by rules that lag; without the ordering
       -- arm one of those could release a later park after a newer fact had
       -- already been spent on it.
       --
       -- The ordering arm is confined to one pull request because
       -- (cursor_generation, event_ordinal) numbers a single repository's
       -- stream: repo_watch_cursor is keyed by (repository, generation), so
       -- tuples from two repositories are incomparable, and a rule-scoped
       -- lineage spans them. Comparing across would let a repository that had
       -- reached a high generation hold a lineage parked on a repository whose
       -- own numbering is lower. Identity still spans the whole lineage, since
       -- an event identifier means the same thing everywhere.
       AND NOT EXISTS (
            SELECT 1
              FROM repo_watch_dispatch_obligation_park AS spent
              JOIN repo_watch_dispatch_obligation AS spent_on
                ON spent_on.obligation_id = spent.obligation_id
              JOIN repo_watch_event AS spent_event
                ON spent_event.event_id = spent.release_event_id
             WHERE (
                    spent_event.event_id = later.event_id
                    OR (
                        spent_event.repository = later.repository
                        AND spent_event.pull_request_number
                             = later.pull_request_number
                        AND (
                            spent_event.cursor_generation,
                            spent_event.event_ordinal
                        ) >= (later.cursor_generation, later.event_ordinal)
                    )
               )
               AND spent_on.rule_id = obligation.rule_id
               AND spent_on.rule_version = obligation.rule_version
               AND spent_on.singleton_scope = obligation.singleton_scope
               AND spent_on.singleton_repository
                    IS NOT DISTINCT FROM obligation.singleton_repository
               AND spent_on.singleton_pull_request_number
                    IS NOT DISTINCT FROM obligation.singleton_pull_request_number
               AND spent_on.singleton_stack_root_pull_request_number
                    IS NOT DISTINCT FROM
                        obligation.singleton_stack_root_pull_request_number
       )
     ORDER BY later.cursor_generation DESC, later.event_ordinal DESC
     LIMIT 1;

    IF progress_event_id IS NOT NULL THEN
        PERFORM repo_watch_release_dispatch_obligation_park_for_progress(
            subject_obligation_id,
            progress_event_id
        );
    END IF;
END;
$$;


--
-- Name: repo_watch_record_dispatch_obligation_park_transition(uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_record_dispatch_obligation_park_transition(subject_obligation_id uuid, kind text, attempts bigint, reason text, progress_event_id uuid, actor text) RETURNS void
    LANGUAGE sql
    AS $$
    INSERT INTO repo_watch_dispatch_obligation_park
        (obligation_id, transition_ordinal, transition_kind, failed_attempts,
         release_reason, release_event_id, release_actor)
    SELECT subject_obligation_id,
           coalesce(
               (SELECT max(park.transition_ordinal)
                  FROM repo_watch_dispatch_obligation_park AS park
                 WHERE park.obligation_id = subject_obligation_id),
               0
           ) + 1,
           kind,
           attempts,
           reason,
           progress_event_id,
           actor;
$$;


--
-- Name: repo_watch_release_completed_dispatch_batches(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_completed_dispatch_batches() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.state_kind <> 'terminal' OR OLD.state_kind = 'terminal' THEN
        RETURN NULL;
    END IF;
    PERFORM repo_watch_release_completed_dispatch_batches_for_turn(
        NEW.turn_id,
        NEW.session_id
    );
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_release_completed_dispatch_batches_for_goal(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_completed_dispatch_batches_for_goal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.event_kind NOT IN ('blocked', 'achieved', 'user_stopped') THEN
        RETURN NULL;
    END IF;
    PERFORM repo_watch_release_completed_dispatch_batches_for_turn(
        NULL::uuid,
        NEW.session_id
    );
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_release_completed_dispatch_batches_for_turn(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_completed_dispatch_batches_for_turn(completed_turn_id uuid, completed_session_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate_dispatch_id uuid;
BEGIN
    FOR candidate_dispatch_id IN
        SELECT DISTINCT action.dispatch_id
          FROM repo_watch_dispatch_action AS action
         WHERE action.session_id = completed_session_id
         ORDER BY action.dispatch_id
    LOOP
        -- A released batch has already accounted for its dispatched work. The
        -- session may afterwards accept an unrelated successor goal, whose own
        -- termination reaches this trigger through the same action link; owing a
        -- requeue for it would redispatch a repository-watch event that already
        -- converged. The release below is written after this call, so a batch
        -- releasing now is still unreleased here.
        IF NOT EXISTS (
            SELECT 1
              FROM repo_watch_dispatch_release AS released
             WHERE released.dispatch_id = candidate_dispatch_id
        ) THEN
            PERFORM repo_watch_owe_dispatch_requeue(
                candidate_dispatch_id,
                completed_session_id
            );
        END IF;

        PERFORM 1
          FROM repo_watch_dispatch_batch AS locked_batch
         WHERE locked_batch.dispatch_id = candidate_dispatch_id
           FOR UPDATE;

        INSERT INTO repo_watch_dispatch_release (dispatch_id, released_at)
        SELECT batch.dispatch_id, clock_timestamp()
          FROM repo_watch_dispatch_batch AS batch
         WHERE batch.dispatch_id = candidate_dispatch_id
           AND NOT EXISTS (
                SELECT 1
                  FROM repo_watch_dispatch_release AS released
                 WHERE released.dispatch_id = batch.dispatch_id
           )
           AND batch.action_count = (
                SELECT count(*)
                  FROM repo_watch_dispatch_action AS action
                  JOIN repo_watch_dispatch_delivery AS delivery
                    ON delivery.dispatch_id = action.dispatch_id
                   AND delivery.action_ordinal = action.action_ordinal
                  JOIN turn_lifecycle AS turn
                    ON turn.turn_id = delivery.turn_id
                   AND (
                        turn.state_kind = 'terminal'
                        OR turn.turn_id = completed_turn_id
                        OR NOT goal_turn_is_runtime_relevant(
                            turn.session_id,
                            turn.turn_id
                        )
                   )
                 WHERE action.dispatch_id = batch.dispatch_id
                   AND NOT EXISTS (
                        SELECT 1
                          FROM turn_lifecycle AS live_turn
                         WHERE live_turn.session_id = action.session_id
                           AND live_turn.state_kind <> 'terminal'
                           AND goal_turn_is_runtime_relevant(
                                live_turn.session_id,
                                live_turn.turn_id
                           )
                           AND (
                                completed_turn_id IS NULL
                                OR live_turn.turn_id <> completed_turn_id
                           )
                   )
                   AND NOT EXISTS (
                        SELECT 1
                          FROM goal_event AS current_goal
                         WHERE current_goal.session_id = action.session_id
                           AND current_goal.event_ordinal = (
                                SELECT max(candidate.event_ordinal)
                                  FROM goal_event AS candidate
                                 WHERE candidate.session_id = action.session_id
                           )
                           AND current_goal.event_kind IN (
                                'commissioned', 'resumed', 'superseded'
                           )
                   )
           )
        ON CONFLICT DO NOTHING;
    END LOOP;
END;
$$;


--
-- Name: repo_watch_release_dispatch_obligation_park_for_progress(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_dispatch_obligation_park_for_progress(parked_obligation_id uuid, progress_event_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    parked_attempts bigint;
BEGIN
    SELECT obligation.failed_attempts
      INTO parked_attempts
      FROM repo_watch_dispatch_obligation AS obligation
     WHERE obligation.obligation_id = parked_obligation_id
       AND obligation.settled_kind IS NULL
       AND obligation.parked_at IS NOT NULL
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN false;
    END IF;

    PERFORM repo_watch_record_dispatch_obligation_park_transition(
        parked_obligation_id,
        'released',
        parked_attempts,
        'pull_request_progress',
        progress_event_id,
        NULL::text
    );

    UPDATE repo_watch_dispatch_obligation
       SET parked_at = NULL,
           parked_state_event_id = NULL,
           failed_attempts = 0,
           last_failed_attempt_at = NULL
     WHERE obligation_id = parked_obligation_id;

    RETURN true;
END;
$$;


--
-- Name: repo_watch_release_dispatch_obligation_parks_for_event(uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_dispatch_obligation_parks_for_event(progress_event_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    released_count bigint := 0;
    parked_obligation_id uuid;
BEGIN
    FOR parked_obligation_id IN
        SELECT obligation.obligation_id
          FROM repo_watch_dispatch_obligation AS obligation
          JOIN repo_watch_event AS parked_state
            ON parked_state.event_id = obligation.parked_state_event_id
          JOIN repo_watch_event AS incoming
            ON incoming.event_id = progress_event_id
         WHERE obligation.settled_kind IS NULL
           AND obligation.parked_at IS NOT NULL
           AND parked_state.target_kind = 'pull_request'
           AND incoming.target_kind = 'pull_request'
           AND incoming.repository = parked_state.repository
           AND incoming.pull_request_number = parked_state.pull_request_number
           AND (
                parked_state.head_sha IS DISTINCT FROM incoming.head_sha
                OR incoming.event_kind IN (
                    'review_submitted', 'thread_opened', 'thread_resolved'
                )
           )
           -- Progress is what follows the stalled state. One repository event
           -- is evaluated once per active rule, so without this a rule lagging
           -- behind its siblings would eventually replay an older event against
           -- a newer park and hand back a budget the pull request never earned.
           AND (incoming.cursor_generation, incoming.event_ordinal)
                > (parked_state.cursor_generation, parked_state.event_ordinal)
           -- And one event buys one release per lineage. The evaluations of a
           -- single event are spread across rules, so a lineage that parks
           -- again between two of them would otherwise be released twice by the
           -- same fact. The spend is read across the whole lineage rather than
           -- the row holding it, because settlement retires that row and the
           -- requeue opens a successor: a lineage that parked, dispatched, and
           -- exhausted itself again would otherwise take a second full budget
           -- from a fact it had already spent.
           -- Already spent by this lineage: by identity anywhere in it, or by
           -- order within the pull request this fact is about. Identity alone
           -- would let a rule lagging behind its siblings release a later park
           -- with a fact older than one already spent; ordering across
           -- repositories would be meaningless, because
           -- (cursor_generation, event_ordinal) numbers one repository's
           -- stream and a rule-scoped lineage spans several.
           AND NOT EXISTS (
                SELECT 1
                  FROM repo_watch_dispatch_obligation_park AS spent
                  JOIN repo_watch_dispatch_obligation AS spent_on
                    ON spent_on.obligation_id = spent.obligation_id
                  JOIN repo_watch_event AS spent_event
                    ON spent_event.event_id = spent.release_event_id
                 WHERE (
                        spent_event.event_id = incoming.event_id
                        OR (
                            spent_event.repository = incoming.repository
                            AND spent_event.pull_request_number
                                 = incoming.pull_request_number
                            AND (
                                spent_event.cursor_generation,
                                spent_event.event_ordinal
                            ) >= (
                                incoming.cursor_generation,
                                incoming.event_ordinal
                            )
                        )
                   )
                   AND spent_on.rule_id = obligation.rule_id
                   AND spent_on.rule_version = obligation.rule_version
                   AND spent_on.singleton_scope = obligation.singleton_scope
                   AND spent_on.singleton_repository
                        IS NOT DISTINCT FROM obligation.singleton_repository
                   AND spent_on.singleton_pull_request_number
                        IS NOT DISTINCT FROM obligation.singleton_pull_request_number
                   AND spent_on.singleton_stack_root_pull_request_number
                        IS NOT DISTINCT FROM
                            obligation.singleton_stack_root_pull_request_number
           )
         ORDER BY obligation.obligation_id
    LOOP
        IF repo_watch_release_dispatch_obligation_park_for_progress(
               parked_obligation_id,
               progress_event_id
           ) THEN
            released_count := released_count + 1;
        END IF;
    END LOOP;
    RETURN released_count;
END;
$$;


--
-- Name: repo_watch_release_parked_dispatch_obligation(uuid, text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_release_parked_dispatch_obligation(parked_obligation_id uuid, releasing_actor text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    parked_attempts bigint;
BEGIN
    SELECT obligation.failed_attempts
      INTO parked_attempts
      FROM repo_watch_dispatch_obligation AS obligation
     WHERE obligation.obligation_id = parked_obligation_id
       AND obligation.settled_kind IS NULL
       AND obligation.parked_at IS NOT NULL
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN false;
    END IF;

    PERFORM repo_watch_record_dispatch_obligation_park_transition(
        parked_obligation_id,
        'released',
        parked_attempts,
        'operator',
        NULL,
        releasing_actor
    );

    UPDATE repo_watch_dispatch_obligation
       SET parked_at = NULL,
           parked_state_event_id = NULL,
           failed_attempts = 0,
           last_failed_attempt_at = NULL
     WHERE obligation_id = parked_obligation_id;

    RETURN true;
END;
$$;


--
-- Name: repo_watch_repository_is_valid(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_repository_is_valid(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
    SELECT octet_length(candidate) BETWEEN 1 AND 201
       AND candidate = lower(candidate)
       AND candidate COLLATE "C" ~ '^[a-z0-9_.-]+/[a-z0-9_.-]+$'
       AND split_part(candidate, '/', 1) NOT IN ('.', '..')
       AND split_part(candidate, '/', 2) NOT IN ('.', '..')
$_$;


--
-- Name: repo_watch_restart_dispatch_obligation_backoff(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_restart_dispatch_obligation_backoff() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE repo_watch_dispatch_obligation AS obligation
       SET last_failed_attempt_at = clock_timestamp()
      FROM repo_watch_dispatch_batch AS batch
     WHERE batch.dispatch_id = NEW.dispatch_id
       AND obligation.rule_id = batch.rule_id
       AND obligation.rule_version = batch.rule_version
       AND obligation.singleton_scope = batch.singleton_scope
       AND obligation.singleton_repository
            IS NOT DISTINCT FROM batch.singleton_repository
       AND obligation.singleton_pull_request_number
            IS NOT DISTINCT FROM batch.singleton_pull_request_number
       AND obligation.singleton_stack_root_pull_request_number
            IS NOT DISTINCT FROM batch.singleton_stack_root_pull_request_number
       AND obligation.settled_kind IS NULL
       AND obligation.failed_attempts > 0;
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_rule_id_is_valid(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_rule_id_is_valid(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
    SELECT octet_length(candidate) BETWEEN 1 AND 128
       AND candidate COLLATE "C" ~ '^[A-Za-z0-9._-]+$'
$_$;


--
-- Name: repo_watch_settle_deactivated_dispatch_obligations(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_settle_deactivated_dispatch_obligations() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE repo_watch_dispatch_obligation
       SET settled_kind = 'deactivated',
           settled_at = clock_timestamp()
     WHERE repository = NEW.repository
       AND rule_id = NEW.rule_id
       AND rule_version = NEW.rule_version
       AND settled_kind IS NULL;
    RETURN NULL;
END;
$$;


--
-- Name: repo_watch_stamp_dispatch_batch_delivered_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION repo_watch_stamp_dispatch_batch_delivered_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Admission coalesces a fresh match into an outstanding obligation instead
    -- of dispatching it, and settles an obligation only after inserting its
    -- successor batch. An unsettled obligation on this singleton therefore
    -- identifies the successor exactly. The batch table is append-only, so the
    -- delivered state is recorded here rather than stamped after settlement.
    IF NOT EXISTS (
        SELECT 1
          FROM repo_watch_dispatch_obligation AS obligation
         WHERE obligation.rule_id = NEW.rule_id
           AND obligation.rule_version = NEW.rule_version
           AND obligation.singleton_scope = NEW.singleton_scope
           AND obligation.singleton_repository
                IS NOT DISTINCT FROM NEW.singleton_repository
           AND obligation.singleton_pull_request_number
                IS NOT DISTINCT FROM NEW.singleton_pull_request_number
           AND obligation.singleton_stack_root_pull_request_number
                IS NOT DISTINCT FROM NEW.singleton_stack_root_pull_request_number
           AND obligation.settled_kind IS NULL
    ) THEN
        NEW.delivered_state_event_id := NEW.event_id;
        RETURN NEW;
    END IF;
    SELECT (
            SELECT state.event_id
              FROM repo_watch_event AS state
             WHERE state.repository = origin.repository
               AND state.pull_request_number = origin.pull_request_number
             ORDER BY state.cursor_generation DESC,
                      state.event_ordinal DESC
             LIMIT 1
    )
      INTO NEW.delivered_state_event_id
      FROM repo_watch_event AS origin
     WHERE origin.event_id = NEW.event_id;
    RETURN NEW;
END;
$$;


--
-- Name: require_accepted_input_parts(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_accepted_input_parts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE checked_input uuid;
BEGIN
    checked_input := CASE WHEN TG_TABLE_NAME = 'accepted_input'
        THEN NEW.accepted_input_id
        ELSE COALESCE(NEW.accepted_input_id, OLD.accepted_input_id) END;
    IF NOT accepted_input_parts_are_valid(checked_input)
       OR NOT accepted_input_parts_match_command(checked_input)
    THEN
        RAISE EXCEPTION 'accepted input has invalid ordered content parts'
            USING ERRCODE = '23514',
                CONSTRAINT = 'accepted_input_content_parts_valid';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_accepted_input_source(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_accepted_input_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE goal_sources bigint;
BEGIN
    SELECT count(*) INTO goal_sources FROM goal_turn
     WHERE accepted_input_id = NEW.accepted_input_id;
    IF NEW.accepting_command_id IS NULL AND goal_sources <> 1 THEN
        RAISE EXCEPTION 'accepted input without a command requires exactly one goal source'
            USING ERRCODE = '23514', CONSTRAINT = 'accepted_input_source_closed';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_accepted_input_steering_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_accepted_input_steering_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_steering_accepted_input_final_state(
        CASE
            WHEN TG_OP = 'DELETE' THEN OLD.accepted_input_id
            ELSE NEW.accepted_input_id
        END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_applied_goal_command_delegation_cascade(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_applied_goal_command_delegation_cascade() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    applied_generation numeric(20, 0);
BEGIN
    IF NEW.operation_kind <> 'stop'
       OR NEW.result_kind <> 'applied'
       OR NEW.descendant_scope <> 'parent_and_descendants' THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM session_delegation AS relation
         WHERE relation.parent_session_id = NEW.session_id
    ) THEN
        RETURN NULL;
    END IF;
    SELECT event.generation INTO applied_generation
      FROM goal_event AS event
     WHERE event.session_id = NEW.session_id
       AND event.event_ordinal = NEW.result_event_ordinal
       AND event.event_kind = 'user_stopped';
    IF applied_generation IS NULL OR NOT EXISTS (
        SELECT 1 FROM session_delegation_termination_cascade AS cascade
         WHERE cascade.root_command_id = NEW.command_id
           AND cascade.root_session_id = NEW.session_id
           AND cascade.root_source_kind = 'goal_command'
           AND cascade.root_turn_id IS NULL
           AND cascade.root_goal_generation = applied_generation
           AND cascade.termination_kind = 'stopped'
           AND cascade.descendant_scope = NEW.descendant_scope
    ) THEN
        RAISE EXCEPTION 'applied descendant-scoped goal command lacks its cascade proof'
            USING ERRCODE = '23514',
                CONSTRAINT = 'goal_command_delegation_cascade';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_applied_turn_command_delegation_cascade(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_applied_turn_command_delegation_cascade() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.delivery_kind <> 'interrupt'
       OR NEW.result_kind <> 'applied'
       OR NEW.descendant_scope <> 'parent_and_descendants' THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM session_delegation AS relation
         WHERE relation.parent_session_id = NEW.session_id
    ) THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM session_delegation_termination_cascade AS cascade
         WHERE cascade.root_command_id = NEW.command_id
           AND cascade.root_session_id = NEW.session_id
           AND cascade.root_source_kind = 'turn_command'
           AND cascade.root_turn_id = NEW.expected_active_turn_id
           AND cascade.root_goal_generation IS NULL
           AND cascade.termination_kind = 'cancelled'
           AND cascade.descendant_scope = NEW.descendant_scope
    ) THEN
        RAISE EXCEPTION 'applied descendant-scoped turn command lacks its cascade proof'
            USING ERRCODE = '23514',
                CONSTRAINT = 'submit_input_command_delegation_cascade';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_blob_replica(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_blob_replica() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM blob_replica
         WHERE digest = NEW.digest
    ) THEN
        RAISE EXCEPTION
            'blob identity requires at least one verified replica'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_completed_tool_approval_judge_decision(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_completed_tool_approval_judge_decision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_decisions bigint;
BEGIN
    IF NEW.state_kind <> 'terminal'
       OR NEW.terminal_disposition_kind <> 'completed'
       OR NEW.recommendation_kind = 'escalate_to_human'
    THEN
        RETURN NULL;
    END IF;

    SELECT count(*)
      INTO matching_decisions
      FROM tool_approval_decision AS decision
     WHERE decision.request_id = NEW.request_id
       AND decision.decision_source = 'delegate'
       AND decision.decision_kind = NEW.recommendation_kind
       AND decision.delegate_model_selection_id =
           NEW.direct_model_selection_id
       AND decision.delegate_model_call_id = NEW.model_call_id
       AND decision.rationale = NEW.rationale;
    IF matching_decisions <> 1 THEN
        RAISE EXCEPTION
            'completed approval judge lacks its exact decision'
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'tool_approval_judge_completed_requires_decision_effect';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_context_compaction_exact_evidence(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_context_compaction_exact_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_count numeric(20, 0);
    result_count numeric(20, 0);
    through_position numeric(20, 0);
    predecessor_result uuid;
    predecessor_summary_entry uuid;
    consumed_through_source_session uuid;
    consumed_through_entry uuid;
    predecessor_consumed_position numeric(20, 0);
    mismatch_count bigint;
    visible_entries text[];
    visible_first integer;
    visible_through integer;
    visible_summary integer;
    summary_record record;
    summary_reference text;
    visible_suffix text[];
BEGIN
    SELECT count(*)
      INTO mismatch_count
      FROM context_compaction_model_call AS call
     WHERE call.model_call_id = NEW.producing_call_id
       AND call.session_id = NEW.session_id
       AND call.source_frontier_id = NEW.source_frontier_id
       AND call.state_kind = 'terminal'
       AND call.terminal_disposition_kind = 'completed';
    IF mismatch_count <> 1 THEN
        RAISE EXCEPTION 'compaction requires its exact completed dedicated call'
            USING ERRCODE = '23514';
    END IF;

    SELECT count(*)
      INTO mismatch_count
      FROM semantic_transcript_entry AS summary
     WHERE summary.source_session_id = NEW.session_id
       AND summary.semantic_entry_id = NEW.summary_entry_id
       AND summary.payload_kind = 'context_summary'
       AND summary.context_summary_producing_call_id = NEW.producing_call_id
       AND summary.context_summary_first_source_session_id = NEW.first_source_session_id
       AND summary.context_summary_first_entry_id = NEW.first_entry_id
       AND summary.context_summary_through_source_session_id = NEW.through_source_session_id
       AND summary.context_summary_through_entry_id = NEW.through_entry_id;
    IF mismatch_count <> 1 THEN
        RAISE EXCEPTION 'compaction requires its exact summary provenance'
            USING ERRCODE = '23514';
    END IF;

    SELECT member_count INTO source_count
      FROM context_frontier
     WHERE owning_session_id = NEW.session_id
       AND context_frontier_id = NEW.source_frontier_id;
    SELECT member_count INTO result_count
      FROM context_frontier
     WHERE owning_session_id = NEW.session_id
       AND context_frontier_id = NEW.result_frontier_id;
    through_position := context_frontier_member_position(
        NEW.session_id,
        NEW.source_frontier_id,
        NEW.through_source_session_id,
        NEW.through_entry_id
    );
    IF source_count IS NULL
       OR result_count IS NULL
       OR through_position IS NULL
       OR result_count <> source_count + 1
    THEN
        RAISE EXCEPTION 'compaction range or frontier cardinality is invalid'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.predecessor_compaction_id IS NULL THEN
        SELECT array_agg(
                   member.source_session_id::text || '/' ||
                   member.semantic_entry_id::text
                   ORDER BY member.member_position
               )
          INTO visible_entries
          FROM context_frontier_member AS member
         WHERE member.owning_session_id = NEW.session_id
           AND member.context_frontier_id = NEW.source_frontier_id;

        FOR summary_record IN
            SELECT
                member.source_session_id,
                member.semantic_entry_id,
                entry.context_summary_first_source_session_id AS first_session,
                entry.context_summary_first_entry_id AS first_entry,
                entry.context_summary_through_source_session_id AS through_session,
                entry.context_summary_through_entry_id AS through_entry
              FROM context_frontier_member AS member
              JOIN semantic_transcript_entry AS entry
                ON entry.source_session_id = member.source_session_id
               AND entry.semantic_entry_id = member.semantic_entry_id
             WHERE member.owning_session_id = NEW.session_id
               AND member.context_frontier_id = NEW.source_frontier_id
               AND entry.payload_kind = 'context_summary'
             ORDER BY member.member_position
        LOOP
            summary_reference := summary_record.source_session_id::text || '/' ||
                summary_record.semantic_entry_id::text;
            visible_first := array_position(
                visible_entries,
                summary_record.first_session::text || '/' || summary_record.first_entry::text
            );
            visible_through := array_position(
                visible_entries,
                summary_record.through_session::text || '/' || summary_record.through_entry::text
            );
            visible_summary := array_position(visible_entries, summary_reference);
            IF visible_first IS NULL
               OR visible_first <> 1
               OR visible_through IS NULL
               OR visible_summary IS NULL
               OR visible_summary <= visible_through
            THEN
                RAISE EXCEPTION 'stored compaction summary has an invalid visible range'
                    USING ERRCODE = '23514';
            END IF;

            SELECT array_agg(visible.reference ORDER BY visible.ordinal)
              INTO visible_suffix
              FROM unnest(
                       visible_entries[
                           visible_through + 1:array_length(visible_entries, 1)
                       ]
                   ) WITH ORDINALITY AS visible(reference, ordinal)
             WHERE visible.reference <> summary_reference;
            visible_entries := ARRAY[summary_reference] ||
                COALESCE(visible_suffix, ARRAY[]::text[]);
        END LOOP;

        visible_first := array_position(
            visible_entries,
            NEW.first_source_session_id::text || '/' || NEW.first_entry_id::text
        );
        visible_through := array_position(
            visible_entries,
            NEW.through_source_session_id::text || '/' || NEW.through_entry_id::text
        );
        IF visible_first IS NULL OR visible_first <> 1 OR visible_through IS NULL THEN
            RAISE EXCEPTION 'compaction range must start at the visible frontier start'
                USING ERRCODE = '23514';
        END IF;

        SELECT
            count(*) FILTER (WHERE entry.payload_kind = 'assistant_tool_use')
            - count(*) FILTER (
                WHERE entry.payload_kind IN (
                    'tool_execution_result', 'tool_denied', 'tool_closed_by_turn_end'
                )
                   OR (
                        entry.payload_kind = 'delegation_result'
                        AND entry.tool_result_request_id IS NOT NULL
                   )
            )
          INTO mismatch_count
          FROM unnest(visible_entries[visible_first:visible_through])
                   WITH ORDINALITY AS visible(reference, ordinal)
          JOIN semantic_transcript_entry AS entry
            ON entry.source_session_id = split_part(visible.reference, '/', 1)::uuid
           AND entry.semantic_entry_id = split_part(visible.reference, '/', 2)::uuid;
    ELSE
        SELECT
            predecessor.result_frontier_id,
            predecessor.summary_entry_id
          INTO
            predecessor_result,
            predecessor_summary_entry
          FROM context_compaction AS predecessor
         WHERE predecessor.context_compaction_id = NEW.predecessor_compaction_id
           AND predecessor.session_id = NEW.session_id;
        WITH RECURSIVE predecessor_chain AS MATERIALIZED (
            SELECT
                predecessor.context_compaction_id,
                predecessor.predecessor_compaction_id,
                predecessor.through_source_session_id,
                predecessor.through_entry_id,
                0 AS depth
              FROM context_compaction AS predecessor
             WHERE predecessor.context_compaction_id =
                       NEW.predecessor_compaction_id
               AND predecessor.session_id = NEW.session_id
            UNION ALL
            SELECT
                ancestor.context_compaction_id,
                ancestor.predecessor_compaction_id,
                ancestor.through_source_session_id,
                ancestor.through_entry_id,
                chain.depth + 1
              FROM predecessor_chain AS chain
              JOIN context_compaction AS ancestor
                ON ancestor.context_compaction_id =
                       chain.predecessor_compaction_id
               AND ancestor.session_id = NEW.session_id
        )
        SELECT
            chain.through_source_session_id,
            chain.through_entry_id
          INTO consumed_through_source_session, consumed_through_entry
          FROM predecessor_chain AS chain
         WHERE NOT EXISTS (
                SELECT 1
                  FROM context_compaction AS consumed_summary
                 WHERE consumed_summary.session_id = NEW.session_id
                   AND consumed_summary.summary_entry_id =
                           chain.through_entry_id
                   AND chain.through_source_session_id = NEW.session_id
         )
         ORDER BY chain.depth
         LIMIT 1;
        predecessor_consumed_position := context_frontier_member_position(
            NEW.session_id,
            NEW.source_frontier_id,
            consumed_through_source_session,
            consumed_through_entry
        );
        IF predecessor_result IS NULL
           OR predecessor_consumed_position IS NULL
           OR NOT context_frontier_preserves_prefix(
                NEW.session_id,
                predecessor_result,
                NEW.source_frontier_id
           )
           OR NEW.first_source_session_id <> NEW.session_id
           OR NEW.first_entry_id <> predecessor_summary_entry
        THEN
            RAISE EXCEPTION 'compaction predecessor result and visible start must match'
                USING ERRCODE = '23514';
        END IF;
        IF ROW(NEW.through_source_session_id, NEW.through_entry_id) <>
               ROW(NEW.session_id, predecessor_summary_entry)
           AND (
                through_position <= predecessor_consumed_position
                OR EXISTS (
                    SELECT 1
                      FROM context_compaction AS consumed_summary
                     WHERE consumed_summary.session_id = NEW.session_id
                       AND consumed_summary.summary_entry_id = NEW.through_entry_id
                       AND NEW.through_source_session_id = NEW.session_id
                )
           )
        THEN
            RAISE EXCEPTION 'compaction range must start at the visible frontier start'
                USING ERRCODE = '23514';
        END IF;

        WITH RECURSIVE visible_chain AS MATERIALIZED (
            SELECT
                frontier.context_frontier_id,
                frontier.prefix_context_frontier_id,
                frontier.member_count
              FROM context_frontier AS frontier
             WHERE frontier.owning_session_id = NEW.session_id
               AND frontier.context_frontier_id = NEW.source_frontier_id
            UNION ALL
            SELECT
                prefix.context_frontier_id,
                prefix.prefix_context_frontier_id,
                prefix.member_count
              FROM visible_chain AS chain
              JOIN context_frontier AS prefix
                ON prefix.owning_session_id = NEW.session_id
               AND prefix.context_frontier_id = chain.prefix_context_frontier_id
             WHERE chain.member_count > predecessor_consumed_position
        ),
        current_boundary_entries AS MATERIALIZED (
            SELECT member.source_session_id, member.semantic_entry_id
              FROM visible_chain AS chain
             JOIN context_frontier_delta AS member
                ON member.owning_session_id = NEW.session_id
               AND member.context_frontier_id = chain.context_frontier_id
             WHERE ROW(NEW.through_source_session_id, NEW.through_entry_id) <>
                       ROW(NEW.session_id, predecessor_summary_entry)
               AND member.member_position > predecessor_consumed_position
               AND member.member_position <= through_position
               AND NOT EXISTS (
                    SELECT 1
                      FROM context_compaction AS consumed_summary
                     WHERE consumed_summary.session_id = NEW.session_id
                       AND consumed_summary.summary_entry_id = member.semantic_entry_id
                       AND member.source_session_id = NEW.session_id
               )
            UNION ALL
            SELECT NEW.session_id, predecessor_summary_entry
        )
        SELECT
            count(*) FILTER (WHERE entry.payload_kind = 'assistant_tool_use')
            - count(*) FILTER (
                WHERE entry.payload_kind IN (
                    'tool_execution_result', 'tool_denied', 'tool_closed_by_turn_end'
                )
                   OR (
                        entry.payload_kind = 'delegation_result'
                        AND entry.tool_result_request_id IS NOT NULL
                   )
            )
          INTO mismatch_count
          FROM current_boundary_entries AS visible
          JOIN semantic_transcript_entry AS entry
            ON entry.source_session_id = visible.source_session_id
           AND entry.semantic_entry_id = visible.semantic_entry_id;
    END IF;

    IF mismatch_count <> 0 THEN
        RAISE EXCEPTION 'compaction boundary leaves a tool exchange open'
            USING ERRCODE = '23514';
    END IF;

    IF NOT context_frontier_preserves_prefix(
            NEW.session_id,
            NEW.source_frontier_id,
            NEW.result_frontier_id
       )
       OR context_frontier_member_position(
            NEW.session_id,
            NEW.result_frontier_id,
            NEW.session_id,
            NEW.summary_entry_id
       ) <> result_count
    THEN
        RAISE EXCEPTION 'compaction result must be the source plus its summary'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_context_frontier_complete_membership(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_context_frontier_complete_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_context_frontier_complete_membership(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.owning_session_id ELSE NEW.owning_session_id END,
        CASE WHEN TG_OP = 'DELETE' THEN OLD.context_frontier_id ELSE NEW.context_frontier_id END
    );

    RETURN NULL;
END;
$$;


--
-- Name: require_context_frontier_member_within_declared_count(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_context_frontier_member_within_declared_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_member_count numeric(20, 0);
    prefix_member_count numeric(20, 0) := 0;
BEGIN
    SELECT frontier.member_count,
           COALESCE(prefix.member_count, 0)
      INTO declared_member_count, prefix_member_count
      FROM context_frontier AS frontier
      LEFT JOIN context_frontier AS prefix
        ON prefix.owning_session_id = frontier.owning_session_id
       AND prefix.context_frontier_id =
               frontier.prefix_context_frontier_id
     WHERE frontier.owning_session_id = NEW.owning_session_id
       AND frontier.context_frontier_id = NEW.context_frontier_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'context frontier header is unavailable for deferred delta validation'
            USING
                ERRCODE = '23503',
                CONSTRAINT = 'context_frontier_member_requires_visible_header';
    END IF;

    IF NEW.member_position <= prefix_member_count
       OR NEW.member_position > declared_member_count
    THEN
        RAISE EXCEPTION
            'context frontier delta position % lies outside (%, %]',
            NEW.member_position,
            prefix_member_count,
            declared_member_count
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'context_frontier_member_within_declared_count';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_context_summary_exact_compaction(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_context_summary_exact_compaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_compactions bigint;
BEGIN
    IF NEW.payload_kind <> 'context_summary' THEN
        RETURN NULL;
    END IF;

    SELECT count(*)
      INTO matching_compactions
      FROM context_compaction AS compaction
     WHERE compaction.session_id = NEW.source_session_id
       AND compaction.summary_entry_id = NEW.semantic_entry_id
       AND compaction.producing_call_id =
           NEW.context_summary_producing_call_id
       AND compaction.first_source_session_id =
           NEW.context_summary_first_source_session_id
       AND compaction.first_entry_id = NEW.context_summary_first_entry_id
       AND compaction.through_source_session_id =
           NEW.context_summary_through_source_session_id
       AND compaction.through_entry_id =
           NEW.context_summary_through_entry_id;
    IF matching_compactions <> 1 THEN
        RAISE EXCEPTION 'context summary requires its exact compaction record'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_contiguous_assistant_response_text_positions(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_contiguous_assistant_response_text_positions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    previous_end numeric;
    next_start numeric;
BEGIN
    SELECT entry.assistant_response_text_start_bytes
               + octet_length(entry.assistant_text_value)::numeric
      INTO previous_end
      FROM semantic_transcript_entry AS entry
     WHERE entry.producing_model_call_id = NEW.producing_model_call_id
       AND entry.payload_kind = 'assistant_text'
       AND entry.assistant_response_part_ordinal
           < NEW.assistant_response_part_ordinal
     ORDER BY entry.assistant_response_part_ordinal DESC
     LIMIT 1;

    IF coalesce(previous_end, 0)
        <> NEW.assistant_response_text_start_bytes THEN
        RAISE EXCEPTION
            'assistant response text positions are not contiguous for model call %',
            NEW.producing_model_call_id
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'semantic_transcript_response_text_positions_contiguous';
    END IF;

    SELECT entry.assistant_response_text_start_bytes
      INTO next_start
      FROM semantic_transcript_entry AS entry
     WHERE entry.producing_model_call_id = NEW.producing_model_call_id
       AND entry.payload_kind = 'assistant_text'
       AND entry.assistant_response_part_ordinal
           > NEW.assistant_response_part_ordinal
     ORDER BY entry.assistant_response_part_ordinal ASC
     LIMIT 1;

    IF next_start IS NOT NULL
       AND NEW.assistant_response_text_start_bytes
               + octet_length(NEW.assistant_text_value)::numeric
           <> next_start THEN
        RAISE EXCEPTION
            'assistant response text positions are not contiguous for model call %',
            NEW.producing_model_call_id
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'semantic_transcript_response_text_positions_contiguous';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_delegated_session_credential_purpose(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegated_session_credential_purpose() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.provenance_kind = 'delegated_session' AND NOT EXISTS (
        SELECT 1 FROM tool_request
         WHERE request_id = NEW.provenance_tool_request_id
           AND tool_name = 'spawn_session'
    ) THEN
        RAISE EXCEPTION 'delegated credentials require their exact spawn request'
            USING ERRCODE = '23514',
                CONSTRAINT = 'delegated_session_credential_purpose';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_cascade_disposition_count(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_cascade_disposition_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_command uuid := COALESCE(NEW.root_command_id, OLD.root_command_id);
    cascade session_delegation_termination_cascade%ROWTYPE;
    expected_count bigint;
    authority_count bigint;
    outcome_count bigint;
BEGIN
    SELECT * INTO cascade
      FROM session_delegation_termination_cascade
     WHERE root_command_id = checked_command;
    IF cascade.root_command_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- Spawn admission locks the same parent session row. Lock the complete
    -- currently reachable set in stable order so no descendant can appear
    -- between frontier derivation and commit.
    PERFORM 1
      FROM session
     WHERE session_id IN (
        SELECT cascade.root_session_id
        UNION
        SELECT frontier.parent_session_id
          FROM delegation_cascade_expected_frontier(
                cascade.root_session_id, cascade.termination_kind
          ) AS frontier
        UNION
        SELECT frontier.child_session_id
          FROM delegation_cascade_expected_frontier(
                cascade.root_session_id, cascade.termination_kind
          ) AS frontier
     )
     ORDER BY session_id
     FOR NO KEY UPDATE;
    PERFORM 1
      FROM session_delegation
     WHERE spawning_tool_request_id IN (
        SELECT frontier.spawning_tool_request_id
          FROM delegation_cascade_expected_frontier(
                cascade.root_session_id, cascade.termination_kind
          ) AS frontier
     )
     ORDER BY spawning_tool_request_id
     FOR UPDATE;

    SELECT count(*) INTO expected_count
      FROM delegation_cascade_expected_frontier(
            cascade.root_session_id, cascade.termination_kind
      );
    SELECT count(*) INTO authority_count
      FROM delegation_cascade_expected_frontier(
            cascade.root_session_id, cascade.termination_kind
      ) AS frontier
      JOIN session_delegation_parent_termination AS authority
        ON authority.root_command_id = checked_command
       AND authority.spawning_tool_request_id =
            frontier.spawning_tool_request_id
       AND authority.parent_session_id = frontier.parent_session_id
       AND authority.termination_kind = frontier.effective_parent_kind
       AND authority.source_kind = frontier.source_kind
       AND authority.source_spawning_tool_request_id IS NOT DISTINCT FROM
            frontier.source_spawning_tool_request_id;
    SELECT count(*) INTO outcome_count
      FROM delegation_cascade_expected_frontier(
            cascade.root_session_id, cascade.termination_kind
      ) AS frontier
      JOIN session_delegation_parent_termination AS authority
        ON authority.root_command_id = checked_command
       AND authority.spawning_tool_request_id =
            frontier.spawning_tool_request_id
      JOIN session_delegation_event AS outcome
        ON outcome.spawning_tool_request_id = authority.spawning_tool_request_id
       AND outcome.event_kind = 'outcome_recorded'
       AND outcome.provenance_command_id = authority.root_command_id
       AND outcome.provenance_session_id = authority.parent_session_id
       AND outcome.provenance_turn_id IS NOT DISTINCT FROM authority.parent_turn_id
       AND outcome.provenance_goal_generation IS NOT DISTINCT FROM
            authority.parent_goal_generation
       AND outcome.reason_kind = CASE authority.termination_kind
            WHEN 'stopped' THEN 'parent_stopped_parent_and_descendants'
            WHEN 'cancelled' THEN 'parent_cancelled_parent_and_descendants'
       END
       AND (
            outcome.outcome_kind = 'already_terminal'
            OR outcome.outcome_kind = CASE frontier.expected_action
                WHEN 'keep_running' THEN 'continue_running'
                WHEN 'stop' THEN 'child_stopped'
                WHEN 'cancel' THEN 'child_cancelled'
            END
       );

    IF cascade.disposition_count <> expected_count
        OR authority_count <> expected_count
        OR outcome_count <> expected_count THEN
        RAISE EXCEPTION 'delegation cascade disposition count is incomplete'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_cascade_disposition_count';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_cascade_parent_termination_chains(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_cascade_parent_termination_chains() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    authority session_delegation_parent_termination%ROWTYPE;
BEGIN
    FOR authority IN
        SELECT stored.*
          FROM session_delegation_parent_termination AS stored
         WHERE stored.root_command_id = NEW.root_command_id
    LOOP
        PERFORM assert_delegation_parent_termination_chain(
            authority,
            NEW
        );
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_initial_task_origin(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_initial_task_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    delegation_origin_count bigint;
BEGIN
    SELECT
        (SELECT count(*) FROM session_delegation_initial_task AS task
          WHERE task.turn_id = NEW.turn_id
            AND task.child_session_id = NEW.session_id
            AND task.admission_position = NEW.acceptance_position)
        +
        (SELECT count(*) FROM session_delegation_wake_turn_origin AS wake
          WHERE wake.turn_id = NEW.turn_id
            AND wake.recipient_session_id = NEW.session_id
            AND wake.admission_position = NEW.acceptance_position)
      INTO delegation_origin_count;
    IF (NEW.origin_kind = 'delegation') IS DISTINCT FROM
            (delegation_origin_count = 1)
       OR delegation_origin_count > 1 THEN
        RAISE EXCEPTION 'turn lifecycle requires exactly its typed origin'
            USING ERRCODE = '23514',
                CONSTRAINT = 'turn_lifecycle_typed_origin';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_initial_task_purpose(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_initial_task_purpose() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_delegation AS relation
          JOIN tool_request AS request
            ON request.request_id = relation.spawning_tool_request_id
           AND request.turn_id = relation.parent_turn_id
           AND request.session_id = relation.parent_session_id
          JOIN tool_attempt AS attempt
            ON attempt.request_id = request.request_id
           AND attempt.turn_id = request.turn_id
           AND attempt.session_id = request.session_id
          JOIN LATERAL turn_origin_exact_model_configuration(
                relation.parent_turn_id, relation.parent_session_id
          ) AS frozen ON true
          JOIN session_defaults_version AS parent_defaults
            ON parent_defaults.session_id = relation.parent_session_id
           AND parent_defaults.version = frozen.defaults_version
          JOIN session_defaults_version AS child_defaults
            ON child_defaults.session_id = NEW.child_session_id
           AND child_defaults.version = NEW.defaults_version
          JOIN session_current_defaults AS child_current
            ON child_current.session_id = NEW.child_session_id
           AND child_current.current_version = NEW.defaults_version
         WHERE relation.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND relation.child_session_id = NEW.child_session_id
           AND request.tool_name = 'spawn_session'
           AND request.arguments_kind = 'json'
           AND request.arguments_text::jsonb = jsonb_build_object(
                'relationship', CASE relation.policy_kind
                    WHEN 'background' THEN jsonb_build_object('kind', 'background')
                    WHEN 'bound' THEN jsonb_build_object(
                        'kind', 'bound',
                        'on_parent_stopped', relation.on_parent_stopped,
                        'on_parent_cancelled', relation.on_parent_cancelled
                    )
                END,
                'task', NEW.task_content
           )
           AND attempt.state_kind = 'terminal'
           AND attempt.terminal_disposition_kind = 'completed'
           AND attempt.effect_class = 'external_effect'
           AND attempt.result_content_kind = 'text'
           AND attempt.result_text::jsonb = jsonb_build_object(
                'result', 'session_spawned',
                'tool_request_id', relation.spawning_tool_request_id::text,
                'child_session_id', relation.child_session_id::text,
                'relationship', CASE relation.policy_kind
                    WHEN 'background' THEN jsonb_build_object('kind', 'background')
                    WHEN 'bound' THEN jsonb_build_object(
                        'kind', 'bound',
                        'on_parent_stopped', relation.on_parent_stopped,
                        'on_parent_cancelled', relation.on_parent_cancelled
                    )
                END
           )
           AND frozen.requested_model_kind = NEW.requested_model_kind
           AND frozen.requested_direct_model_selection_id IS NOT DISTINCT FROM
                NEW.requested_direct_model_selection_id
           AND frozen.requested_model_alias_id IS NOT DISTINCT FROM
                NEW.requested_model_alias_id
           AND frozen.frozen_model_kind = NEW.frozen_model_kind
           AND frozen.frozen_direct_model_selection_id IS NOT DISTINCT FROM
                NEW.frozen_direct_model_selection_id
           AND frozen.frozen_model_alias_id IS NOT DISTINCT FROM
                NEW.frozen_model_alias_id
           AND frozen.frozen_alias_selected_direct_id IS NOT DISTINCT FROM
                NEW.frozen_alias_selected_direct_id
           AND child_defaults.model_selection_kind =
                parent_defaults.model_selection_kind
           AND child_defaults.model_selection_reference =
                parent_defaults.model_selection_reference
           AND child_defaults.dangerous_tool_auto_approval =
                parent_defaults.dangerous_tool_auto_approval
           AND child_defaults.system_prompt_digest =
                parent_defaults.system_prompt_digest
    ) THEN
        RAISE EXCEPTION 'delegation initial task contradicts its spawn request'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_initial_task_purpose';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_lifecycle_update(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_lifecycle_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.event_kind <> 'outcome_recorded'
        OR NEW.provenance_kind NOT IN (
            'parent_turn_command', 'parent_goal_command'
        ) THEN
        RETURN NULL;
    END IF;
    IF (
        SELECT count(*) FROM delegation_update_outbox_event AS emitted
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE emitted.update_kind = 'child_lifecycle_disposition'
           AND emitted.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND emitted.delegation_event_ordinal = NEW.event_ordinal
           AND emitted.session_id = relation.parent_session_id
    ) <> 1 THEN
        RAISE EXCEPTION 'delegation outcome requires exactly one lifecycle update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_lifecycle_update_required';
    END IF;
    IF NEW.outcome_kind IN ('child_stopped', 'child_cancelled') AND (
        SELECT count(*) FROM delegation_update_outbox_event AS emitted
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE emitted.update_kind = 'child_lifecycle_disposition'
           AND emitted.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND emitted.delegation_event_ordinal = NEW.event_ordinal
           AND emitted.session_id = relation.child_session_id
    ) <> 1 THEN
        RAISE EXCEPTION
            'terminalized delegated child requires exactly one lifecycle update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_child_lifecycle_update_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_logical_terminal_outcome(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_logical_terminal_outcome() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_delegation_event AS event
          JOIN session_child_result AS result
            ON result.spawning_tool_request_id = event.spawning_tool_request_id
           AND result.event_ordinal = event.event_ordinal
           AND result.event_kind = event.event_kind
           AND result.outcome_kind = event.outcome_kind
         WHERE event.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND event.event_kind = 'outcome_recorded'
           AND event.provenance_command_id = NEW.root_command_id
           AND event.outcome_kind = CASE NEW.disposition_kind
                WHEN 'stopped' THEN 'child_stopped'
                WHEN 'cancelled' THEN 'child_cancelled'
           END
    ) THEN
        RAISE EXCEPTION 'logical delegation terminal lacks its exact delivered outcome'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_logical_terminal_outcome';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM turn_lifecycle AS lifecycle
         WHERE lifecycle.session_id = NEW.child_session_id
           AND lifecycle.turn_id = NEW.child_turn_id
           AND lifecycle.delegation_runtime_terminal
    ) THEN
        RAISE EXCEPTION 'logical delegation terminal did not release its runtime slot'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_logical_terminal_runtime_slot';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_message_rejection_attempt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_message_rejection_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM tool_attempt
         WHERE request_id = NEW.tool_request_id
           AND state_kind = 'terminal'
           AND terminal_disposition_kind = 'known_failed'
           AND error_kind = 'execution_failed') <> 1 THEN
        RAISE EXCEPTION 'delegation message rejection lacks its terminal attempt'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_message_rejection_attempt';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_message_update(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_message_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM delegation_update_outbox_event AS emitted
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE emitted.update_kind = 'session_message'
           AND emitted.message_id = NEW.message_id
           AND emitted.session_id = CASE NEW.direction
                WHEN 'parent_to_child' THEN relation.child_session_id
                WHEN 'child_to_parent' THEN relation.parent_session_id
           END) <> 1 THEN
        RAISE EXCEPTION 'delegation message requires exactly one message update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_session_message_update_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_message_wake(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_message_wake() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM delegation_wake_outbox_event AS wake
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE wake.subject_kind = 'message'
           AND wake.message_id = NEW.message_id
           AND wake.session_id = CASE NEW.direction
                WHEN 'parent_to_child' THEN relation.child_session_id
                WHEN 'child_to_parent' THEN relation.parent_session_id
           END) <> 1 THEN
        RAISE EXCEPTION 'delegation message requires exactly one recipient wake'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_message_wake_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_outbox_event_typed_record(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_outbox_event_typed_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE matching_records bigint;
BEGIN
    CASE NEW.event_kind
        WHEN 'delegation_update' THEN SELECT count(*) INTO matching_records FROM delegation_update_outbox_event WHERE event_sequence = NEW.event_sequence;
        WHEN 'delegation_wake' THEN SELECT count(*) INTO matching_records FROM delegation_wake_outbox_event WHERE event_sequence = NEW.event_sequence;
        ELSE RAISE EXCEPTION 'unsupported outbox event kind %', NEW.event_kind USING ERRCODE = '23514';
    END CASE;
    IF matching_records <> 1 THEN
        RAISE EXCEPTION 'outbox event % requires exactly one % typed record', NEW.event_sequence, NEW.event_kind USING ERRCODE = '23503';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_parent_termination_chain(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_parent_termination_chain() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cascade session_delegation_termination_cascade%ROWTYPE;
BEGIN
    SELECT * INTO cascade FROM session_delegation_termination_cascade
     WHERE root_command_id = NEW.root_command_id;
    IF cascade.root_command_id IS NULL THEN
        RETURN NULL;
    END IF;
    PERFORM assert_delegation_parent_termination_chain(NEW, cascade);
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_result_update(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_result_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM delegation_update_outbox_event AS emitted
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE emitted.update_kind = 'child_result'
           AND emitted.result_spawning_request_id = NEW.spawning_tool_request_id
           AND emitted.session_id = relation.parent_session_id) <> 1 THEN
        RAISE EXCEPTION 'delegation result requires exactly one child-result update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_child_result_update_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_result_wake(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_result_wake() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM delegation_wake_outbox_event AS wake
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = NEW.spawning_tool_request_id
         WHERE wake.subject_kind = 'result'
           AND wake.result_spawning_request_id = NEW.spawning_tool_request_id
           AND wake.awaiting_tool_request_id IS NULL
           AND wake.session_id = relation.parent_session_id) <> 1 THEN
        RAISE EXCEPTION 'delegation result requires exactly one parent wake'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_result_wake_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_spawn_history(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_spawn_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM session_delegation_event
         WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
           AND event_ordinal = 1 AND event_kind = 'spawned') <> 1 THEN
        RAISE EXCEPTION 'delegation requires exactly one ordinal-one spawn event'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_spawn_history';
    END IF;
    IF (SELECT count(*)
          FROM session_delegation_initial_task AS task
          JOIN turn_lifecycle AS lifecycle
            ON lifecycle.turn_id = task.turn_id
           AND lifecycle.session_id = task.child_session_id
           AND lifecycle.acceptance_position = task.admission_position
         WHERE task.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND task.child_session_id = NEW.child_session_id
           AND task.admission_position = 1
           AND lifecycle.origin_kind = 'delegation'
           AND lifecycle.origin_accepted_input_id IS NULL) <> 1 THEN
        RAISE EXCEPTION 'delegation requires exactly one typed initial task turn'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_initial_task_history';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_spawn_update(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_spawn_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM delegation_update_outbox_event
         WHERE update_kind = 'child_spawned'
           AND spawning_tool_request_id = NEW.spawning_tool_request_id
           AND session_id = NEW.parent_session_id) <> 1 THEN
        RAISE EXCEPTION 'delegation relation requires exactly one child-spawned update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_child_spawned_update_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_termination_cascade_command(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_termination_cascade_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.root_source_kind = 'goal_command' AND NOT EXISTS (
            SELECT 1
              FROM goal_command AS command
              JOIN goal_event AS event
                ON event.session_id = command.session_id
               AND event.event_ordinal = command.result_event_ordinal
             WHERE command.command_id = NEW.root_command_id
               AND command.session_id = NEW.root_session_id
               AND command.operation_kind = 'stop'
               AND command.result_kind = 'applied'
               AND command.descendant_scope = NEW.descendant_scope
               AND event.event_kind = 'user_stopped'
               AND event.generation = NEW.root_goal_generation))
        OR (NEW.root_source_kind = 'turn_command' AND NOT EXISTS (
            SELECT 1 FROM submit_input_command
             WHERE command_id = NEW.root_command_id
               AND session_id = NEW.root_session_id
               AND delivery_kind = 'interrupt'
               AND expected_active_turn_id = NEW.root_turn_id
               AND result_kind = 'applied' AND rejection_kind IS NULL
               AND descendant_scope = NEW.descendant_scope)) THEN
        RAISE EXCEPTION 'delegation cascade lacks its exact applied root command'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_termination_cascade_command';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_update_subject(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_update_subject() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM session_delegation AS relation
         WHERE relation.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND CASE NEW.update_kind
                WHEN 'child_spawned' THEN
                    NEW.session_id = relation.parent_session_id
                    AND NEW.child_session_id = relation.child_session_id
                    AND NEW.policy_kind = relation.policy_kind
                    AND NEW.on_parent_stopped IS NOT DISTINCT FROM relation.on_parent_stopped
                    AND NEW.on_parent_cancelled IS NOT DISTINCT FROM relation.on_parent_cancelled
                WHEN 'child_waiting' THEN EXISTS (
                    SELECT 1 FROM session_delegation_wait AS wait
                     WHERE wait.awaiting_tool_request_id = NEW.awaiting_tool_request_id
                       AND wait.spawning_tool_request_id = NEW.spawning_tool_request_id
                       AND wait.child_session_id = NEW.child_session_id
                       AND wait.wait_mode = NEW.wait_mode
                       AND NEW.session_id = relation.parent_session_id
                )
                WHEN 'child_lifecycle_disposition' THEN EXISTS (
                    SELECT 1 FROM session_delegation_event AS event
                     WHERE event.spawning_tool_request_id = NEW.spawning_tool_request_id
                       AND event.event_ordinal = NEW.delegation_event_ordinal
                       AND event.event_kind = 'outcome_recorded'
                       AND event.outcome_kind = NEW.outcome_kind
                       AND event.reason_kind = NEW.reason_kind
                       AND event.provenance_kind = NEW.provenance_kind
                       AND event.provenance_session_id = NEW.provenance_session_id
                       AND event.provenance_turn_id IS NOT DISTINCT FROM
                            NEW.provenance_turn_id
                       AND event.provenance_goal_generation IS NOT DISTINCT FROM
                            NEW.provenance_goal_generation
                       AND event.provenance_command_id IS NOT DISTINCT FROM
                            NEW.provenance_command_id
                       AND event.outcome_kind IN (
                            'child_stopped', 'child_cancelled',
                            'already_terminal', 'continue_running'
                       )
                       AND event.reason_kind IN (
                            'parent_stopped_parent_and_descendants',
                            'parent_cancelled_parent_and_descendants'
                       )
                       AND event.provenance_kind IN (
                            'parent_turn_command', 'parent_goal_command'
                       )
                       AND relation.child_session_id = NEW.child_session_id
                       AND (
                            NEW.session_id = relation.parent_session_id
                            OR (
                                NEW.session_id = relation.child_session_id
                                AND event.outcome_kind IN (
                                    'child_stopped', 'child_cancelled'
                                )
                            )
                       )
                )
                WHEN 'child_result' THEN EXISTS (
                    SELECT 1
                      FROM session_child_result AS result
                      JOIN session_delegation_event AS event
                        ON event.spawning_tool_request_id =
                            result.spawning_tool_request_id
                       AND event.event_ordinal = result.event_ordinal
                     WHERE result.spawning_tool_request_id =
                            NEW.result_spawning_request_id
                       AND result.outcome_kind = NEW.outcome_kind
                       AND result.content_text IS NOT DISTINCT FROM NEW.content_text
                       AND event.reason_kind = NEW.reason_kind
                       AND event.provenance_kind = NEW.provenance_kind
                       AND event.provenance_session_id = NEW.provenance_session_id
                       AND event.provenance_turn_id IS NOT DISTINCT FROM
                            NEW.provenance_turn_id
                       AND event.provenance_goal_generation IS NOT DISTINCT FROM
                            NEW.provenance_goal_generation
                       AND event.provenance_command_id IS NOT DISTINCT FROM
                            NEW.provenance_command_id
                       AND relation.child_session_id = NEW.child_session_id
                       AND NEW.session_id = relation.parent_session_id
                )
                WHEN 'session_message' THEN EXISTS (
                    SELECT 1 FROM session_message AS message
                     WHERE message.message_id = NEW.message_id
                       AND message.spawning_tool_request_id =
                            NEW.spawning_tool_request_id
                       AND message.event_ordinal = NEW.message_ordinal
                       AND message.content_text = NEW.content_text
                       AND NEW.sender_session_id = CASE message.direction
                            WHEN 'parent_to_child' THEN relation.parent_session_id
                            WHEN 'child_to_parent' THEN relation.child_session_id
                       END
                       AND NEW.recipient_session_id = CASE message.direction
                            WHEN 'parent_to_child' THEN relation.child_session_id
                            WHEN 'child_to_parent' THEN relation.parent_session_id
                       END
                       AND NEW.session_id = NEW.recipient_session_id
                )
           END
    ) THEN
        RAISE EXCEPTION 'delegation update payload does not match its typed state'
            USING ERRCODE = '23514',
                CONSTRAINT = 'delegation_update_subject';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wait_purpose(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wait_purpose() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM tool_request
        WHERE request_id = NEW.awaiting_tool_request_id
          AND session_id = NEW.parent_session_id
          AND turn_id = NEW.parent_turn_id
          AND tool_name = 'await_session'
          AND arguments_kind = 'json'
          AND arguments_text::jsonb = jsonb_build_object(
              'child_session_id', NEW.child_session_id::text,
              'mode', NEW.wait_mode
          )) THEN
        RAISE EXCEPTION 'delegation wait requires exact normalized await_session purpose'
            USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_wait_purpose';
    END IF;
    IF NEW.wait_mode = 'background' AND NOT EXISTS (
        SELECT 1 FROM tool_attempt
         WHERE request_id = NEW.awaiting_tool_request_id
           AND session_id = NEW.parent_session_id
           AND turn_id = NEW.parent_turn_id
           AND state_kind = 'terminal'
           AND terminal_disposition_kind = 'completed'
           AND effect_class = 'effect_free'
           AND result_content_kind = 'text'
           AND result_text::jsonb = jsonb_build_object(
                'result', 'session_await_registered',
                'tool_request_id', NEW.awaiting_tool_request_id::text,
                'child_session_id', NEW.child_session_id::text,
                'mode', 'background'
           )
    ) THEN
        RAISE EXCEPTION 'background delegation wait requires exact completed registration receipt'
            USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_wait_purpose';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wait_rejection_attempt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wait_rejection_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM tool_attempt
         WHERE request_id = NEW.tool_request_id
           AND state_kind = 'terminal'
           AND terminal_disposition_kind = 'known_failed'
           AND error_kind = 'execution_failed') <> 1 THEN
        RAISE EXCEPTION 'delegation wait rejection lacks its terminal attempt'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_wait_rejection_attempt';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wait_turn_phase(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wait_turn_phase() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_phase_count bigint;
BEGIN
    SELECT count(*) INTO matching_phase_count
      FROM turn_lifecycle
     WHERE turn_id = NEW.parent_turn_id
       AND session_id = NEW.parent_session_id
       AND state_kind = 'active'
       AND active_phase_kind = 'awaiting_child'
       AND child_wait_request_id = NEW.awaiting_tool_request_id;
    IF (NEW.wait_mode = 'foreground' AND matching_phase_count <> 1)
        OR (NEW.wait_mode = 'background' AND matching_phase_count <> 0) THEN
        RAISE EXCEPTION 'delegation wait mode contradicts its parent turn phase'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wait_turn_phase';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wait_update(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wait_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    waiting_update_sequence numeric(20, 0);
    waiting_update_count bigint;
BEGIN
    SELECT count(*), min(event_sequence)
      INTO waiting_update_count, waiting_update_sequence
      FROM delegation_update_outbox_event
     WHERE update_kind = 'child_waiting'
       AND awaiting_tool_request_id = NEW.awaiting_tool_request_id
       AND session_id = NEW.parent_session_id;
    IF waiting_update_count <> 1 THEN
        RAISE EXCEPTION 'delegation wait requires exactly one child-waiting update'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_child_waiting_update_required';
    END IF;
    IF NEW.wait_mode = 'foreground'
        AND EXISTS (
            SELECT 1 FROM session_child_result
             WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
        )
        AND NOT EXISTS (
            SELECT 1 FROM delegation_wake_outbox_event AS wake
             WHERE wake.subject_kind = 'result'
               AND wake.result_spawning_request_id =
                    NEW.spawning_tool_request_id
               AND wake.session_id = NEW.parent_session_id
               AND wake.event_sequence > waiting_update_sequence
               AND (
                    wake.awaiting_tool_request_id IS NULL
                    OR wake.awaiting_tool_request_id =
                        NEW.awaiting_tool_request_id
               )
        )
    THEN
        RAISE EXCEPTION 'late foreground wait requires a fresh durable result wake'
            USING ERRCODE = '23503',
                CONSTRAINT = 'delegation_late_wait_wake_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wake_recipient(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wake_recipient() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (NEW.subject_kind = 'result' AND (
            NOT EXISTS (
                SELECT 1 FROM session_delegation
                 WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
                   AND parent_session_id = NEW.session_id
            )
            OR (NEW.awaiting_tool_request_id IS NOT NULL AND NOT EXISTS (
                SELECT 1 FROM session_delegation_wait
                 WHERE awaiting_tool_request_id = NEW.awaiting_tool_request_id
                   AND spawning_tool_request_id = NEW.spawning_tool_request_id
                   AND parent_session_id = NEW.session_id
            ))))
        OR (NEW.subject_kind = 'message' AND NOT EXISTS (
            SELECT 1 FROM session_message AS message JOIN session_delegation AS relation
              ON relation.spawning_tool_request_id = message.spawning_tool_request_id
            WHERE message.message_id = NEW.message_id
              AND ((message.direction = 'parent_to_child' AND relation.child_session_id = NEW.session_id)
                OR (message.direction = 'child_to_parent' AND relation.parent_session_id = NEW.session_id)))) THEN
        RAISE EXCEPTION 'delegation wake recipient does not match its subject'
            USING ERRCODE = '23514', CONSTRAINT = 'delegation_wake_recipient';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_delegation_wake_turn_origin(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_delegation_wake_turn_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    stored session_delegation_wake_turn_origin%ROWTYPE;
    lifecycle turn_lifecycle%ROWTYPE;
    predecessor_turn uuid;
    predecessor_frontier uuid;
    predecessor_member_count numeric(20, 0);
    predecessor_defaults_version numeric(20, 0);
    predecessor_requested_kind text;
    predecessor_requested_direct uuid;
    predecessor_requested_alias uuid;
    predecessor_frozen_kind text;
    predecessor_frozen_direct uuid;
    predecessor_frozen_alias uuid;
    predecessor_frozen_alias_selected uuid;
    delivery_count bigint;
    incorrect_member_count bigint;
    skipped_earlier_count bigint;
BEGIN
    SELECT * INTO stored FROM session_delegation_wake_turn_origin
     WHERE turn_id = NEW.turn_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT * INTO lifecycle FROM turn_lifecycle
     WHERE turn_id = stored.turn_id
       AND session_id = stored.recipient_session_id
       AND acceptance_position = stored.admission_position
       AND origin_kind = 'delegation';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'delegation wake lacks its exact typed turn lifecycle'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;

    SELECT count(*) INTO delivery_count
      FROM generate_series(
            stored.first_delivery_sequence,
            stored.through_delivery_sequence
      ) AS sequence(value)
     WHERE delegation_delivery_semantic_entry(
            stored.recipient_session_id,
            sequence.value
     ) IS NOT NULL;
    IF delivery_count <> stored.through_delivery_sequence
            - stored.first_delivery_sequence + 1 THEN
        RAISE EXCEPTION 'delegation wake range lacks typed delivered content'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;
    predecessor_turn := accepted_input_turn_queue_predecessor(
        stored.recipient_session_id,
        stored.turn_id
    );
    SELECT turn_lifecycle_effective_terminal_frontier(
                stored.recipient_session_id, predecessor_turn
           )
      INTO predecessor_frontier;
    SELECT member_count INTO predecessor_member_count
      FROM context_frontier
     WHERE owning_session_id = stored.recipient_session_id
       AND context_frontier_id = predecessor_frontier;
    SELECT
        exact.defaults_version,
        exact.requested_model_kind,
        exact.requested_direct_model_selection_id,
        exact.requested_model_alias_id,
        exact.frozen_model_kind,
        exact.frozen_direct_model_selection_id,
        exact.frozen_model_alias_id,
        exact.frozen_alias_selected_direct_id
      INTO
        predecessor_defaults_version,
        predecessor_requested_kind,
        predecessor_requested_direct,
        predecessor_requested_alias,
        predecessor_frozen_kind,
        predecessor_frozen_direct,
        predecessor_frozen_alias,
        predecessor_frozen_alias_selected
      FROM turn_origin_exact_model_configuration(
            predecessor_turn,
            stored.recipient_session_id
      ) AS exact;
    IF predecessor_member_count IS NULL
       OR stored.defaults_version IS DISTINCT FROM predecessor_defaults_version
       OR stored.requested_model_kind IS DISTINCT FROM predecessor_requested_kind
       OR stored.requested_direct_model_selection_id IS DISTINCT FROM
            predecessor_requested_direct
       OR stored.requested_model_alias_id IS DISTINCT FROM
            predecessor_requested_alias
       OR stored.frozen_model_kind IS DISTINCT FROM predecessor_frozen_kind
       OR stored.frozen_direct_model_selection_id IS DISTINCT FROM
            predecessor_frozen_direct
       OR stored.frozen_model_alias_id IS DISTINCT FROM predecessor_frozen_alias
       OR stored.frozen_alias_selected_direct_id IS DISTINCT FROM
            predecessor_frozen_alias_selected THEN
        RAISE EXCEPTION 'delegation wake lacks its exact terminal predecessor configuration'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;
    SELECT count(*) INTO skipped_earlier_count
      FROM session_pending_delivery AS pending
     WHERE pending.recipient_session_id = stored.recipient_session_id
       AND pending.delivery_sequence < stored.first_delivery_sequence
       AND NOT EXISTS (
            SELECT 1 FROM context_frontier_member AS member
             WHERE member.owning_session_id = stored.recipient_session_id
               AND member.context_frontier_id = predecessor_frontier
               AND member.source_session_id = stored.recipient_session_id
               AND member.semantic_entry_id = delegation_delivery_semantic_entry(
                    stored.recipient_session_id,
                    pending.delivery_sequence
               )
       );
    IF skipped_earlier_count <> 0 THEN
        RAISE EXCEPTION 'delegation wake starting frontier skips earlier delivery content'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;
    IF lifecycle.state_kind = 'queued' THEN
        RETURN NULL;
    END IF;

    IF lifecycle.start_lineage_kind <> 'after'
       OR lifecycle.immediate_predecessor_turn_id IS DISTINCT FROM predecessor_turn
    THEN
        RAISE EXCEPTION 'delegation wake lacks its exact terminal predecessor'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;

    SELECT count(*) INTO incorrect_member_count
      FROM generate_series(
            stored.first_delivery_sequence,
            stored.through_delivery_sequence
      ) AS sequence(value)
      LEFT JOIN context_frontier_member AS member
        ON member.owning_session_id = stored.recipient_session_id
       AND member.context_frontier_id = lifecycle.starting_frontier_id
       AND member.member_position = predecessor_member_count
            + sequence.value - stored.first_delivery_sequence + 1
            + CASE
                WHEN sequence.value = stored.through_delivery_sequence THEN
                    turn_start_model_identity_entry_count(
                        stored.turn_id,
                        lifecycle.starting_frontier_id
                    )
                ELSE 0
              END
       AND member.source_session_id = stored.recipient_session_id
       AND member.semantic_entry_id = delegation_delivery_semantic_entry(
            stored.recipient_session_id,
            sequence.value
       )
     WHERE member.semantic_entry_id IS NULL;
    IF incorrect_member_count <> 0 THEN
        RAISE EXCEPTION 'delegation wake starting frontier skips or reorders delivery content'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_delegation_wake_turn_origin';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_denied_tool_without_attempt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_denied_tool_without_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.decision_kind = 'deny'
       AND EXISTS (
            SELECT 1
              FROM tool_attempt
             WHERE request_id = NEW.request_id
       )
    THEN
        RAISE EXCEPTION 'denied tool request cannot have an attempt'
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'denied_tool_request_has_no_attempt';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_durable_command_typed_record(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_durable_command_typed_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE matching_records bigint;
BEGIN
    IF NEW.command_kind <> 'review_orchestration' AND EXISTS (
        SELECT 1 FROM review_orchestration_command_recovery
         WHERE command_id = NEW.command_id
    ) THEN
        RAISE EXCEPTION 'durable command % is reserved by review orchestration recovery', NEW.command_id
            USING ERRCODE = '23505';
    END IF;
    CASE NEW.command_kind
        WHEN 'create_session' THEN SELECT count(*) INTO matching_records FROM create_session_command WHERE command_id = NEW.command_id;
        WHEN 'create_session_from_imported_frontier' THEN SELECT count(*) INTO matching_records FROM create_session_from_imported_frontier_command WHERE command_id = NEW.command_id;
        WHEN 'replace_session_defaults' THEN SELECT count(*) INTO matching_records FROM replace_session_defaults_command WHERE command_id = NEW.command_id;
        WHEN 'replace_session_metadata' THEN SELECT count(*) INTO matching_records FROM replace_session_metadata_command WHERE command_id = NEW.command_id;
        WHEN 'submit_input' THEN SELECT count(*) INTO matching_records FROM submit_input_command WHERE command_id = NEW.command_id;
        WHEN 'decide_tool_request' THEN SELECT count(*) INTO matching_records FROM decide_tool_request_command WHERE command_id = NEW.command_id;
        WHEN 'override_denied_tool_request' THEN SELECT count(*) INTO matching_records FROM override_denied_tool_request_command WHERE command_id = NEW.command_id;
        WHEN 'review_workflow' THEN SELECT count(*) INTO matching_records FROM review_workflow_command WHERE command_id = NEW.command_id;
        WHEN 'review_orchestration' THEN SELECT (SELECT count(*) FROM review_orchestration_command WHERE command_id = NEW.command_id) + (SELECT count(*) FROM review_orchestration_command_intent WHERE command_id = NEW.command_id) INTO matching_records;
        WHEN 'compact_session' THEN SELECT count(*) INTO matching_records FROM compact_session_command WHERE command_id = NEW.command_id;
        WHEN 'goal' THEN SELECT count(*) INTO matching_records FROM goal_command WHERE command_id = NEW.command_id;
        WHEN 'update_session_placement' THEN SELECT count(*) INTO matching_records FROM update_session_placement_command WHERE command_id = NEW.command_id;
        WHEN 'register_workspace' THEN SELECT count(*) INTO matching_records FROM workspace WHERE command_id = NEW.command_id;
        WHEN 'mint_git_remote' THEN SELECT count(*) INTO matching_records FROM configured_git_remote_mint WHERE command_id = NEW.command_id;
        WHEN 'withdraw_git_remote' THEN SELECT count(*) INTO matching_records FROM configured_git_remote_withdrawal WHERE command_id = NEW.command_id;
        ELSE RAISE EXCEPTION 'unsupported durable command kind %', NEW.command_kind USING ERRCODE = '23514';
    END CASE;
    IF matching_records <> 1 THEN
        RAISE EXCEPTION 'durable command % requires exactly one % typed record', NEW.command_id, NEW.command_kind USING ERRCODE = '23503';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_explicit_tool_approval_decided_outbox(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_explicit_tool_approval_decided_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.recording_transaction_id <> pg_current_xact_id() THEN
        RAISE EXCEPTION 'tool approval decided event transaction is not current'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'tool_approval_decided_transaction_current';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM tool_approval_decision
         WHERE request_id = NEW.request_id
           AND decision_source NOT IN ('policy_auto', 'session_blanket')
    ) THEN
        RAISE EXCEPTION 'tool approval decided event requires explicit provenance'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'tool_approval_decided_requires_explicit_source';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_explicit_tool_approval_effect(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_explicit_tool_approval_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_effects bigint;
BEGIN
    IF NEW.decision_source IN (
        'policy_auto', 'session_blanket', 'runtime_safety'
    ) THEN
        RETURN NULL;
    END IF;

    IF NEW.decision_source = 'user_override' THEN
        SELECT count(*)
          INTO matching_effects
          FROM tool_approval_decided_outbox_event AS dispatched
          JOIN tool_request AS request
            ON request.request_id = dispatched.request_id
          JOIN turn_lifecycle AS lifecycle
            ON lifecycle.turn_id = request.turn_id
           AND lifecycle.session_id = request.session_id
         WHERE dispatched.request_id = NEW.request_id
           AND dispatched.recording_transaction_id = pg_current_xact_id()
           AND lifecycle.active_tool_round_call_id =
               request.producing_model_call_id
           AND (
                (
                    lifecycle.state_kind = 'active'
                    AND lifecycle.active_phase_kind = 'awaiting_tool_approval'
                    AND lifecycle.approval_tool_request_id = (
                        SELECT later.request_id
                          FROM tool_request AS later
                          LEFT JOIN tool_approval_decision AS later_decision
                            ON later_decision.request_id = later.request_id
                         WHERE later.producing_model_call_id =
                               request.producing_model_call_id
                           AND later_decision.request_id IS NULL
                         ORDER BY later.request_ordinal
                         LIMIT 1
                    )
                )
                OR
                (
                    lifecycle.state_kind = 'active'
                    AND lifecycle.active_phase_kind = 'running'
                    AND lifecycle.approval_tool_request_id IS NULL
                    AND lifecycle.recovery_tool_attempt_id IS NULL
                    AND NOT EXISTS (
                        SELECT 1
                          FROM tool_request AS undecided
                          LEFT JOIN tool_approval_decision AS undecided_decision
                            ON undecided_decision.request_id =
                               undecided.request_id
                         WHERE undecided.producing_model_call_id =
                               request.producing_model_call_id
                           AND undecided_decision.request_id IS NULL
                    )
                    AND EXISTS (
                        SELECT 1
                          FROM turn_attempt AS successor
                          JOIN model_call AS producing_call
                            ON producing_call.model_call_id =
                               request.producing_model_call_id
                           AND producing_call.turn_id = request.turn_id
                           AND producing_call.session_id = request.session_id
                         WHERE successor.turn_attempt_id =
                               lifecycle.current_attempt_id
                           AND successor.turn_id = request.turn_id
                           AND successor.session_id = request.session_id
                           AND successor.continued_from_attempt_id =
                               producing_call.turn_attempt_id
                           AND successor.state_kind = 'prepared'
                    )
                )
           );
        IF matching_effects <> 1 THEN
            RAISE EXCEPTION
                'user override consumption lacks its atomic proposal effect'
                USING
                    ERRCODE = '23514',
                    CONSTRAINT =
                        'tool_approval_user_override_requires_atomic_effect';
        END IF;
        RETURN NULL;
    END IF;

    SELECT count(*)
      INTO matching_effects
      FROM tool_approval_decided_outbox_event AS dispatched
      JOIN tool_request AS request
        ON request.request_id = dispatched.request_id
      JOIN turn_lifecycle AS lifecycle
        ON lifecycle.turn_id = request.turn_id
       AND lifecycle.session_id = request.session_id
     WHERE dispatched.request_id = NEW.request_id
       AND lifecycle.active_tool_round_call_id =
           request.producing_model_call_id
       AND (
            SELECT count(*)
              FROM tool_approval_decided_outbox_event AS transaction_event
              JOIN tool_approval_decision AS transaction_decision
                ON transaction_decision.request_id =
                   transaction_event.request_id
              JOIN tool_request AS transaction_request
                ON transaction_request.request_id =
                   transaction_decision.request_id
             WHERE transaction_request.producing_model_call_id =
                   request.producing_model_call_id
               AND transaction_decision.decision_source NOT IN (
                    'policy_auto', 'session_blanket', 'runtime_safety'
               )
               AND transaction_event.recording_transaction_id =
                   dispatched.recording_transaction_id
       ) = 1
       AND NOT EXISTS (
            SELECT 1
              FROM tool_request AS earlier
              LEFT JOIN tool_approval_decision AS earlier_decision
                ON earlier_decision.request_id = earlier.request_id
             WHERE earlier.producing_model_call_id =
                   request.producing_model_call_id
               AND earlier.request_ordinal < request.request_ordinal
               AND earlier_decision.request_id IS NULL
       )
       AND (
            (
                lifecycle.state_kind = 'active'
                AND lifecycle.active_phase_kind = 'awaiting_tool_approval'
                AND lifecycle.approval_tool_request_id = (
                    SELECT later.request_id
                      FROM tool_request AS later
                      LEFT JOIN tool_approval_decision AS later_decision
                        ON later_decision.request_id = later.request_id
                     WHERE later.producing_model_call_id =
                           request.producing_model_call_id
                       AND later_decision.request_id IS NULL
                     ORDER BY later.request_ordinal
                     LIMIT 1
                )
            )
            OR
            (
                lifecycle.state_kind = 'active'
                AND lifecycle.active_phase_kind = 'running'
                AND lifecycle.approval_tool_request_id IS NULL
                AND lifecycle.recovery_tool_attempt_id IS NULL
                AND NOT EXISTS (
                    SELECT 1
                      FROM tool_request AS undecided
                      LEFT JOIN tool_approval_decision AS undecided_decision
                        ON undecided_decision.request_id = undecided.request_id
                     WHERE undecided.producing_model_call_id =
                           request.producing_model_call_id
                       AND undecided_decision.request_id IS NULL
                )
                AND EXISTS (
                    SELECT 1
                      FROM turn_attempt AS successor
                      JOIN model_call AS producing_call
                        ON producing_call.model_call_id =
                           request.producing_model_call_id
                       AND producing_call.turn_id = request.turn_id
                       AND producing_call.session_id = request.session_id
                     WHERE successor.turn_attempt_id =
                           lifecycle.current_attempt_id
                       AND successor.turn_id = request.turn_id
                       AND successor.session_id = request.session_id
                       AND successor.continued_from_attempt_id =
                           producing_call.turn_attempt_id
                       AND successor.state_kind = 'prepared'
                )
            )
       );
    IF matching_effects <> 1 THEN
        RAISE EXCEPTION
            'explicit decision lacks its outbox and lifecycle effect'
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'tool_approval_explicit_requires_atomic_effect';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_failed_terminal_execution_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_failed_terminal_execution_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_turn_id uuid;
BEGIN
    checked_turn_id := CASE
        WHEN TG_OP = 'DELETE' THEN OLD.turn_id
        ELSE NEW.turn_id
    END;
    PERFORM assert_failed_terminal_execution_final_state(checked_turn_id);
    RETURN NULL;
END;
$$;


--
-- Name: require_goal_command_applied_event_kind(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_command_applied_event_kind() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE applied_event goal_event%ROWTYPE;
BEGIN
    IF NEW.result_kind <> 'applied' THEN
        RETURN NULL;
    END IF;
    SELECT * INTO applied_event
      FROM goal_event
     WHERE session_id = NEW.session_id
       AND event_ordinal = NEW.result_event_ordinal;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF NOT (
        (NEW.operation_kind = 'attach'
            AND applied_event.event_kind = 'commissioned'
            AND applied_event.statement = NEW.statement)
        OR (NEW.operation_kind = 'resume'
            AND applied_event.event_kind = 'resumed'
            AND applied_event.guidance IS NOT DISTINCT FROM NEW.guidance)
        OR (NEW.operation_kind = 'stop'
            AND applied_event.event_kind = 'user_stopped')
        OR (NEW.operation_kind = 'supersede'
            AND applied_event.event_kind = 'superseded'
            AND applied_event.statement = NEW.statement)
    ) THEN
        RAISE EXCEPTION 'goal command operation disagrees with applied event kind'
            USING ERRCODE = '23514',
                CONSTRAINT = 'goal_command_applied_event_kind';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_goal_event_continuity(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_event_continuity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    prior_ordinal numeric(20, 0);
    prior_generation numeric(20, 0);
    prior_kind text;
    current_generation numeric(20, 0);
BEGIN
    PERFORM 1 FROM session WHERE session_id = NEW.session_id FOR NO KEY UPDATE;
    SELECT event_ordinal, generation, event_kind
      INTO prior_ordinal, prior_generation, prior_kind
      FROM goal_event
     WHERE session_id = NEW.session_id
     ORDER BY event_ordinal DESC
     LIMIT 1;

    IF NOT FOUND THEN
        IF NEW.event_ordinal <> 1 OR NEW.generation <> 1
            OR NEW.event_kind <> 'commissioned' THEN
            RAISE EXCEPTION 'first goal event must commission generation one at ordinal one'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.event_ordinal <> prior_ordinal + 1 THEN
        RAISE EXCEPTION 'goal event ordinal must be contiguous'
            USING ERRCODE = '23514';
    END IF;
    current_generation := prior_generation
        + CASE
            WHEN prior_kind = 'superseded' THEN 1
            WHEN prior_kind IN ('achieved', 'user_stopped')
                AND NEW.event_kind = 'commissioned' THEN 1
            ELSE 0
          END;
    IF NEW.generation <> current_generation THEN
        RAISE EXCEPTION 'goal event generation does not name the current statement'
            USING ERRCODE = '23514';
    END IF;
    IF prior_kind IN ('achieved', 'user_stopped') AND NEW.event_kind <> 'commissioned' THEN
        RAISE EXCEPTION 'terminal goal generation admits only a later commission'
            USING ERRCODE = '23514';
    END IF;
    IF prior_kind = 'blocked' AND NEW.event_kind NOT IN ('resumed', 'user_stopped', 'superseded') THEN
        RAISE EXCEPTION 'blocked goal admits only resume, stop, or supersede'
            USING ERRCODE = '23514';
    END IF;
    IF prior_kind IN ('commissioned', 'resumed', 'superseded')
        AND NEW.event_kind NOT IN ('blocked', 'achieved', 'user_stopped', 'superseded') THEN
        RAISE EXCEPTION 'pursuing goal transition is invalid'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.event_kind = 'superseded'
        AND NEW.generation = 18446744073709551615 THEN
        RAISE EXCEPTION 'goal generation exhausted'
            USING ERRCODE = '22003';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_goal_event_user_command_receipt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_event_user_command_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE receipt goal_command%ROWTYPE;
BEGIN
    IF NEW.user_command_id IS NULL THEN
        RETURN NULL;
    END IF;
    SELECT * INTO receipt FROM goal_command
     WHERE command_id = NEW.user_command_id
       AND session_id = NEW.session_id;
    IF receipt.command_id IS NULL
        OR receipt.result_kind <> 'applied'
        OR receipt.result_event_ordinal <> NEW.event_ordinal THEN
        RAISE EXCEPTION 'goal user event lacks its exact applied command receipt'
            USING ERRCODE = '23514',
                CONSTRAINT = 'goal_event_applied_command_receipt';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_goal_execution_failure_recovery_terminal(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_execution_failure_recovery_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM turn_lifecycle AS lifecycle
         WHERE lifecycle.turn_id = NEW.turn_id
           AND lifecycle.session_id = NEW.session_id
           AND lifecycle.state_kind = 'terminal'
           AND lifecycle.terminal_disposition_kind = 'failed'
           AND lifecycle.terminal_model_call_id IS NULL
    ) THEN
        RAISE EXCEPTION 'goal execution-failure recovery requires its exact call-free failed turn'
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'goal_execution_failure_recovery_exact_terminal';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_goal_turn_retired_outbox_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_turn_retired_outbox_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM goal_turn AS goal
          JOIN turn_lifecycle AS lifecycle
            ON lifecycle.session_id = goal.session_id
           AND lifecycle.turn_id = goal.turn_id
         WHERE goal.session_id = NEW.session_id
           AND goal.turn_id = NEW.turn_id
           AND lifecycle.state_kind = 'queued'
           AND NOT goal_turn_is_runtime_relevant(
               goal.session_id,
               goal.turn_id
           )
    ) THEN
        RAISE EXCEPTION 'goal turn retirement must name queued ineligible work'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'goal_turn_retired_outbox_state';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_goal_turn_shape(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_goal_turn_shape() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    accepted accepted_input%ROWTYPE;
    queued queued_input_origin%ROWTYPE;
    defaults session_defaults_version%ROWTYPE;
    lifecycle turn_lifecycle%ROWTYPE;
    latest_event goal_event%ROWTYPE;
    source_event goal_event%ROWTYPE;
    predecessor turn_lifecycle%ROWTYPE;
    expected_content text;
BEGIN
    SELECT * INTO accepted FROM accepted_input
     WHERE accepted_input_id = NEW.accepted_input_id;
    SELECT * INTO queued FROM queued_input_origin
     WHERE turn_id = NEW.turn_id;
    SELECT * INTO defaults FROM session_defaults_version
     WHERE session_id = NEW.session_id
       AND version = queued.defaults_version;
    SELECT * INTO lifecycle FROM turn_lifecycle
     WHERE turn_id = NEW.turn_id;
    SELECT * INTO latest_event FROM goal_event
     WHERE session_id = NEW.session_id
     ORDER BY event_ordinal DESC LIMIT 1;

    IF accepted.accepted_input_id IS NULL
        OR accepted.session_id <> NEW.session_id
        OR accepted.delivery_kind <> 'start_when_no_active_turn'
        OR accepted.expected_active_turn_id IS NOT NULL
        OR accepted.expected_defaults_version IS NULL
        OR accepted.model_override_kind <> 'use_session_default'
        OR accepted.replacement_model_kind IS NOT NULL
        OR accepted.replacement_direct_model_selection_id IS NOT NULL
        OR accepted.replacement_model_alias_id IS NOT NULL
        OR accepted.disposition_kind <> 'origin_of'
        OR accepted.origin_turn_id <> NEW.turn_id
        OR queued.turn_id IS NULL
        OR queued.accepted_input_id <> NEW.accepted_input_id
        OR queued.session_id <> NEW.session_id
        OR queued.acceptance_position <> accepted.acceptance_position
        OR queued.priority_kind <> 'ordinary'
        OR queued.interrupt_predecessor_turn_id IS NOT NULL
        OR queued.source_configuration_turn_id IS NOT NULL
        OR defaults.session_id IS NULL
        OR accepted.expected_defaults_version <> queued.defaults_version
        OR queued.requested_model_kind <> defaults.model_selection_kind
        OR queued.requested_direct_model_selection_id
            IS DISTINCT FROM defaults.direct_model_selection_id
        OR queued.requested_model_alias_id
            IS DISTINCT FROM defaults.model_alias_id
        OR NOT (
            (queued.requested_model_kind = 'direct'
                AND queued.frozen_model_kind = 'direct'
                AND queued.frozen_direct_model_selection_id =
                    queued.requested_direct_model_selection_id)
            OR (queued.requested_model_kind = 'alias'
                AND queued.frozen_model_kind = 'frozen_alias'
                AND queued.frozen_model_alias_id = queued.requested_model_alias_id)
        )
        OR queued.model_parameters <> 'provider_defaults'
        OR queued.known_provider_failure_retry <> 'disabled'
        OR queued.model_fallback <> 'disabled'
        OR queued.dangerous_tool_auto_approval <>
            defaults.dangerous_tool_auto_approval
        OR lifecycle.turn_id IS NULL
        OR lifecycle.session_id <> NEW.session_id
        OR lifecycle.origin_accepted_input_id <> NEW.accepted_input_id
        OR lifecycle.acceptance_position <> accepted.acceptance_position
        OR lifecycle.state_kind <> 'queued'
    THEN
        RAISE EXCEPTION 'goal turn lacks its exact queued accepted-input shape'
            USING ERRCODE = '23514', CONSTRAINT = 'goal_turn_runtime_shape';
    END IF;

    IF latest_event.event_ordinal IS NULL
        OR (
            latest_event.event_kind = 'superseded'
            AND latest_event.generation + 1 <> NEW.goal_generation
        )
        OR (
            latest_event.event_kind <> 'superseded'
            AND latest_event.generation <> NEW.goal_generation
        )
        OR latest_event.event_kind NOT IN ('commissioned', 'resumed', 'superseded')
    THEN
        RAISE EXCEPTION 'goal turn requires the current pursuing generation'
            USING ERRCODE = '23514', CONSTRAINT = 'goal_turn_current_pursuit';
    END IF;

    IF NEW.source_event_ordinal IS NOT NULL THEN
        SELECT * INTO source_event FROM goal_event
         WHERE session_id = NEW.session_id
           AND event_ordinal = NEW.source_event_ordinal;
        IF source_event.event_kind NOT IN ('commissioned', 'resumed', 'superseded') THEN
            RAISE EXCEPTION 'first goal turn requires a pursuing user event'
                USING ERRCODE = '23514', CONSTRAINT = 'goal_turn_source_event';
        END IF;
        IF (
            source_event.event_kind = 'superseded'
            AND source_event.generation + 1 <> NEW.goal_generation
        ) OR (
            source_event.event_kind <> 'superseded'
            AND source_event.generation <> NEW.goal_generation
        ) THEN
            RAISE EXCEPTION
                'first goal turn generation disagrees with its user event'
                USING ERRCODE = '23514',
                    CONSTRAINT = 'goal_turn_source_generation';
        END IF;
        IF source_event.event_kind = 'resumed' THEN
            IF source_event.guidance IS NOT NULL THEN
                expected_content := source_event.guidance;
            ELSE
                SELECT statement INTO expected_content FROM goal_event
                 WHERE session_id = NEW.session_id
                   AND event_ordinal <= NEW.source_event_ordinal
                   AND event_kind IN ('commissioned', 'superseded')
                 ORDER BY event_ordinal DESC LIMIT 1;
            END IF;
        ELSE
            expected_content := source_event.statement;
        END IF;
    ELSE
        SELECT * INTO predecessor FROM turn_lifecycle
         WHERE session_id = NEW.session_id
           AND turn_id = NEW.predecessor_turn_id;
        IF predecessor.state_kind <> 'terminal'
            OR predecessor.terminal_disposition_kind <> 'completed' THEN
            RAISE EXCEPTION
                'goal continuation requires a successfully completed predecessor'
                USING ERRCODE = '23514',
                    CONSTRAINT = 'goal_turn_completed_predecessor';
        END IF;
        IF EXISTS (
            SELECT 1
              FROM goal_turn AS later_goal
              JOIN turn_lifecycle AS later
                ON later.session_id = later_goal.session_id
               AND later.turn_id = later_goal.turn_id
             WHERE later_goal.session_id = NEW.session_id
               AND later_goal.goal_generation = NEW.goal_generation
               AND later_goal.turn_id <> NEW.turn_id
               AND later.acceptance_position > predecessor.acceptance_position
        ) THEN
            RAISE EXCEPTION
                'goal continuation requires the latest accepted goal turn'
                USING ERRCODE = '23514',
                    CONSTRAINT = 'goal_turn_latest_predecessor';
        END IF;
        SELECT statement INTO expected_content FROM goal_event
         WHERE session_id = NEW.session_id
           AND event_kind IN ('commissioned', 'superseded')
         ORDER BY event_ordinal DESC LIMIT 1;
    END IF;

    IF expected_content IS NULL
        OR (
            accepted.accepting_command_id IS NULL
            AND NOT EXISTS (
                SELECT 1
                  FROM accepted_input_content_part AS part
                 WHERE part.accepted_input_id = accepted.accepted_input_id
                   AND part.position = 0
                   AND part.part_kind = 'text'
                   AND part.text_value = expected_content
                   AND NOT EXISTS (
                        SELECT 1
                          FROM accepted_input_content_part AS extra
                         WHERE extra.accepted_input_id = accepted.accepted_input_id
                           AND extra.position <> 0
                   )
            )
        )
    THEN
        RAISE EXCEPTION 'goal turn input does not match its immutable source'
            USING ERRCODE = '23514', CONSTRAINT = 'goal_turn_input_content';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_imported_ancestry_for_seed(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_ancestry_for_seed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_ancestry_kind text;
BEGIN
    SELECT ancestry_kind
      INTO checked_ancestry_kind
      FROM session
     WHERE session_id = NEW.session_id;

    IF NOT FOUND OR checked_ancestry_kind <> 'imported_conversation' THEN
        RAISE EXCEPTION
            'imported seed requires imported session ancestry'
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'imported_session_seed_requires_imported_ancestry';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_imported_conversation_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_conversation_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_imported_conversation_complete(
        CASE
            WHEN TG_OP = 'DELETE' THEN OLD.imported_conversation_id
            ELSE NEW.imported_conversation_id
        END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_imported_entry_within_declared_counts(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_entry_within_declared_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    conversation_count numeric(20, 0);
    raw_entry_count numeric(20, 0);
BEGIN
    SELECT declared_entry_count
      INTO conversation_count
      FROM imported_conversation
     WHERE imported_conversation_id = NEW.imported_conversation_id;

    SELECT declared_entry_count
      INTO raw_entry_count
      FROM imported_conversation_raw_record
     WHERE imported_conversation_id = NEW.imported_conversation_id
       AND raw_record_position = NEW.raw_record_position;

    IF conversation_count IS NULL
       OR raw_entry_count IS NULL
       OR NEW.imported_entry_position > conversation_count
       OR NEW.record_entry_position > raw_entry_count
    THEN
        RAISE EXCEPTION
            'imported entry position is outside its declared conversation or raw record'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_imported_raw_record_within_declared_count(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_raw_record_within_declared_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    declared_count numeric(20, 0);
BEGIN
    SELECT declared_raw_record_count
      INTO declared_count
      FROM imported_conversation
     WHERE imported_conversation_id = NEW.imported_conversation_id;

    IF NOT FOUND OR NEW.raw_record_position > declared_count THEN
        RAISE EXCEPTION
            'imported raw-record position is outside its declared conversation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_imported_raw_source_record_owned(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_raw_source_record_owned() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM imported_conversation_raw_record
         WHERE content_hash = NEW.content_hash
    )
    THEN
        RAISE EXCEPTION
            'imported raw-source record has no conversation occurrence'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_imported_seed_for_session(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_imported_seed_for_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_imported_session_seed_complete(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.session_id ELSE NEW.session_id END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_initial_task_relation_history(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_initial_task_relation_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_request uuid := COALESCE(NEW.spawning_tool_request_id, OLD.spawning_tool_request_id);
    relation session_delegation%ROWTYPE;
BEGIN
    SELECT * INTO relation FROM session_delegation
     WHERE spawning_tool_request_id = checked_request;
    IF relation.spawning_tool_request_id IS NOT NULL
        AND (SELECT count(*)
              FROM session_delegation_initial_task AS task
              JOIN turn_lifecycle AS lifecycle
                ON lifecycle.turn_id = task.turn_id
               AND lifecycle.session_id = task.child_session_id
               AND lifecycle.acceptance_position = task.admission_position
             WHERE task.spawning_tool_request_id = checked_request
               AND task.child_session_id = relation.child_session_id
               AND task.admission_position = 1
               AND lifecycle.origin_kind = 'delegation'
               AND lifecycle.origin_accepted_input_id IS NULL) <> 1 THEN
        RAISE EXCEPTION 'delegation relation lost its typed initial task turn'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_delegation_initial_task_history';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_interrupt_attempt_proof(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_interrupt_attempt_proof() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_interrupt_attempt_proof(
        CASE
            WHEN TG_OP = 'DELETE' THEN OLD.turn_attempt_id
            ELSE NEW.turn_attempt_id
        END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_interrupt_submit_input_effect_correlation(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_interrupt_submit_input_effect_correlation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_records bigint;
BEGIN
    IF NEW.result_kind = 'applied'
       AND EXISTS (
            SELECT 1
              FROM turn_runner_recovery_interrupt_effect
             WHERE command_id = NEW.command_id
       )
    THEN
        SELECT count(*)
          INTO matching_records
          FROM turn_runner_recovery_interrupt_effect AS effect
          JOIN accepted_input AS accepted
            ON accepted.accepting_command_id = effect.command_id
           AND accepted.session_id = effect.session_id
          JOIN queued_input_origin AS successor
            ON successor.accepted_input_id = accepted.accepted_input_id
           AND successor.turn_id = accepted.origin_turn_id
           AND successor.session_id = accepted.session_id
           AND successor.acceptance_position = accepted.acceptance_position
          JOIN turn_lifecycle AS cancelled
            ON cancelled.session_id = effect.session_id
           AND cancelled.turn_id = effect.turn_id
          JOIN turn_attempt AS yielded_attempt
            ON yielded_attempt.turn_attempt_id = effect.yielded_turn_attempt_id
           AND yielded_attempt.turn_id = effect.turn_id
           AND yielded_attempt.session_id = effect.session_id
         WHERE effect.command_id = NEW.command_id
           AND effect.session_id = NEW.session_id
           AND effect.turn_id = NEW.expected_active_turn_id
           AND accepted.accepted_input_id = NEW.result_accepted_input_id
           AND accepted.session_id = NEW.result_session_id
           AND accepted_input_parts_match_command(accepted.accepted_input_id)
           AND accepted.delivery_kind = 'interrupt'
           AND accepted.expected_active_turn_id = NEW.expected_active_turn_id
           AND accepted.expected_defaults_version = NEW.expected_defaults_version
           AND accepted.model_override_kind = NEW.model_override_kind
           AND accepted.replacement_model_kind
               IS NOT DISTINCT FROM NEW.replacement_model_kind
           AND accepted.replacement_direct_model_selection_id
               IS NOT DISTINCT FROM NEW.replacement_direct_model_selection_id
           AND accepted.replacement_model_alias_id
               IS NOT DISTINCT FROM NEW.replacement_model_alias_id
           AND accepted.disposition_kind = 'origin_of'
           AND accepted.origin_turn_id = NEW.result_turn_id
           AND successor.priority_kind = 'interrupt_immediately_after'
           AND successor.interrupt_predecessor_turn_id = effect.turn_id
           AND successor.defaults_version = NEW.expected_defaults_version
           AND cancelled.state_kind = 'terminal'
           AND cancelled.terminal_attempt_id = effect.yielded_turn_attempt_id
           AND cancelled.terminal_model_call_id IS NULL
           AND (
                (
                    effect.interrupted_tool_attempt_id IS NULL
                    AND cancelled.terminal_disposition_kind = 'cancelled'
                    AND cancelled.terminal_tool_attempt_id IS NULL
                )
                OR (
                    effect.interrupted_tool_attempt_id IS NOT NULL
                    AND cancelled.terminal_disposition_kind =
                        'reconciliation_required'
                    AND cancelled.terminal_tool_attempt_id =
                        effect.interrupted_tool_attempt_id
                    AND EXISTS (
                        SELECT 1
                          FROM tool_attempt AS stopped_tool
                          JOIN runner_physical_attempt_lease_binding AS binding
                            ON binding.attempt_id = stopped_tool.attempt_id
                          JOIN runner_lease_generation AS lease
                            ON lease.lease_id = binding.lease_id
                           AND lease.attempt_id = stopped_tool.attempt_id
                           AND lease.session_id = stopped_tool.session_id
                          JOIN runner_current_lease_event AS lease_head
                            ON lease_head.lease_id = lease.lease_id
                           AND lease_head.generation = lease.generation
                          JOIN runner_lease_event AS lease_event
                            ON lease_event.lease_id = lease_head.lease_id
                           AND lease_event.generation = lease_head.generation
                           AND lease_event.event_ordinal = lease_head.event_ordinal
                          JOIN runner_session_placement_record AS leased_placement
                            ON leased_placement.session_id = lease.session_id
                           AND leased_placement.event_ordinal =
                                lease.placement_event_ordinal
                         WHERE stopped_tool.attempt_id =
                                effect.interrupted_tool_attempt_id
                           AND stopped_tool.session_id = effect.session_id
                           AND stopped_tool.turn_id = effect.turn_id
                           AND stopped_tool.state_kind = 'terminal'
                           AND stopped_tool.terminal_disposition_kind = 'ambiguous'
                           AND lease.runner_id = effect.runner_id
                           AND lease_event.state_kind IN (
                                'lost_execution_possible', 'lost_claimed'
                           )
                           AND lease.effect_class IN ('idempotent', 'side_effecting')
                           AND leased_placement.placement_revision =
                                effect.placement_revision
                           AND leased_placement.state_kind = 'pinned'
                           AND leased_placement.pinned_runner_id = effect.runner_id
                    )
                )
                OR (
                    effect.interrupted_tool_attempt_id IS NOT NULL
                    AND cancelled.terminal_disposition_kind = 'cancelled'
                    AND cancelled.terminal_tool_attempt_id IS NULL
                    AND EXISTS (
                        SELECT 1
                          FROM tool_attempt AS stopped_tool
                         WHERE stopped_tool.attempt_id =
                                effect.interrupted_tool_attempt_id
                           AND stopped_tool.session_id = effect.session_id
                           AND stopped_tool.turn_id = effect.turn_id
                           AND stopped_tool.state_kind = 'terminal'
                           AND stopped_tool.terminal_disposition_kind = 'known_failed'
                           AND stopped_tool.error_kind = 'crash_lost'
                           AND stopped_tool.error_detail IS NULL
                    )
                )
           )
           AND yielded_attempt.state_kind = 'ended'
           AND yielded_attempt.end_variant = 'without_stop'
           AND yielded_attempt.end_disposition = 'yielded_to_durable_wait'
           AND yielded_attempt.interrupt_command_id IS NULL
           AND yielded_attempt.interrupt_predecessor_turn_id IS NULL;
    ELSIF NEW.result_kind = 'applied' THEN
        SELECT count(*)
          INTO matching_records
          FROM accepted_input AS accepted
          JOIN queued_input_origin AS successor
            ON successor.accepted_input_id = accepted.accepted_input_id
           AND successor.turn_id = accepted.origin_turn_id
           AND successor.session_id = accepted.session_id
           AND successor.acceptance_position = accepted.acceptance_position
          JOIN turn_attempt AS stopped_attempt
            ON stopped_attempt.turn_id = NEW.expected_active_turn_id
           AND stopped_attempt.session_id = NEW.session_id
           AND (
                (
                    stopped_attempt.interrupt_command_id = NEW.command_id
                    AND stopped_attempt.interrupt_predecessor_turn_id =
                        NEW.expected_active_turn_id
                    AND (
                        stopped_attempt.state_kind = 'stop_requested'
                        OR (
                            stopped_attempt.state_kind = 'ended'
                            AND stopped_attempt.end_variant = 'after_cancellation'
                        )
                    )
                )
                OR (
                    stopped_attempt.state_kind = 'ended'
                    AND stopped_attempt.end_variant = 'without_stop'
                    AND stopped_attempt.end_disposition IN ('ambiguous', 'lost')
                    AND stopped_attempt.interrupt_command_id IS NULL
                    AND stopped_attempt.interrupt_predecessor_turn_id IS NULL
                    AND EXISTS (
                        SELECT 1
                          FROM turn_lifecycle AS reconciled
                         WHERE reconciled.turn_id = stopped_attempt.turn_id
                           AND reconciled.session_id = stopped_attempt.session_id
                           AND reconciled.state_kind = 'terminal'
                           AND reconciled.terminal_disposition_kind =
                                'reconciliation_required'
                           AND reconciled.terminal_attempt_id =
                                stopped_attempt.turn_attempt_id
                    )
                )
                OR (
                    stopped_attempt.state_kind = 'ended'
                    AND stopped_attempt.end_variant = 'without_stop'
                    AND stopped_attempt.end_disposition = 'yielded_to_durable_wait'
                    AND stopped_attempt.interrupt_command_id IS NULL
                    AND stopped_attempt.interrupt_predecessor_turn_id IS NULL
                    AND EXISTS (
                        SELECT 1
                          FROM session_delegation_wait AS waiting
                          JOIN tool_request AS awaiting
                            ON awaiting.request_id = waiting.awaiting_tool_request_id
                           AND awaiting.turn_id = waiting.parent_turn_id
                           AND awaiting.session_id = waiting.parent_session_id
                          JOIN model_call AS producing_call
                            ON producing_call.model_call_id =
                                awaiting.producing_model_call_id
                           AND producing_call.turn_id = awaiting.turn_id
                           AND producing_call.session_id = awaiting.session_id
                          JOIN turn_lifecycle AS cancelled
                            ON cancelled.turn_id = waiting.parent_turn_id
                           AND cancelled.session_id = waiting.parent_session_id
                         WHERE waiting.parent_turn_id = NEW.expected_active_turn_id
                           AND waiting.parent_session_id = NEW.session_id
                           AND waiting.wait_mode = 'foreground'
                           AND producing_call.turn_attempt_id =
                                stopped_attempt.turn_attempt_id
                           AND cancelled.state_kind = 'terminal'
                           AND cancelled.terminal_disposition_kind = 'cancelled'
                           AND cancelled.terminal_attempt_id IS NULL
                           AND cancelled.terminal_model_call_id IS NULL
                    )
                )
           )
         WHERE accepted.accepting_command_id = NEW.command_id
           AND accepted.accepted_input_id = NEW.result_accepted_input_id
           AND accepted.session_id = NEW.result_session_id
           AND accepted_input_parts_match_command(accepted.accepted_input_id)
           AND accepted.delivery_kind = 'interrupt'
           AND accepted.expected_active_turn_id = NEW.expected_active_turn_id
           AND accepted.expected_defaults_version = NEW.expected_defaults_version
           AND accepted.model_override_kind = NEW.model_override_kind
           AND accepted.replacement_model_kind
               IS NOT DISTINCT FROM NEW.replacement_model_kind
           AND accepted.replacement_direct_model_selection_id
               IS NOT DISTINCT FROM NEW.replacement_direct_model_selection_id
           AND accepted.replacement_model_alias_id
               IS NOT DISTINCT FROM NEW.replacement_model_alias_id
           AND accepted.disposition_kind = 'origin_of'
           AND accepted.origin_turn_id = NEW.result_turn_id
           AND successor.priority_kind = 'interrupt_immediately_after'
           AND successor.interrupt_predecessor_turn_id = NEW.expected_active_turn_id
           AND successor.defaults_version = NEW.expected_defaults_version;
    ELSIF NEW.rejection_kind = 'interrupt_unavailable_while_awaiting_approval'
    THEN
        SELECT count(*)
          INTO matching_records
          FROM turn_lifecycle AS parked
         WHERE parked.turn_id = NEW.result_actual_active_turn_id
           AND parked.session_id = NEW.result_session_id
           AND parked.state_kind = 'active'
           AND parked.active_phase_kind = 'awaiting_tool_approval'
           AND NOT EXISTS (
                SELECT 1
                  FROM accepted_input
                 WHERE accepting_command_id = NEW.command_id
           );
    ELSE
        SELECT count(*)
          INTO matching_records
          FROM submit_input_command AS existing
          JOIN accepted_input AS accepted
            ON accepted.accepting_command_id = existing.command_id
           AND accepted.accepted_input_id = existing.result_accepted_input_id
           AND accepted.session_id = existing.result_session_id
           AND accepted.origin_turn_id = existing.result_turn_id
          JOIN queued_input_origin AS successor
            ON successor.accepted_input_id = accepted.accepted_input_id
           AND successor.turn_id = accepted.origin_turn_id
           AND successor.session_id = accepted.session_id
           AND successor.priority_kind = 'interrupt_immediately_after'
           AND successor.interrupt_predecessor_turn_id = NEW.result_actual_active_turn_id
          JOIN turn_lifecycle AS active
            ON active.turn_id = NEW.result_actual_active_turn_id
           AND active.session_id = NEW.result_session_id
           AND active.state_kind = 'active'
          JOIN turn_attempt AS stopped_attempt
            ON stopped_attempt.turn_attempt_id = active.current_attempt_id
           AND stopped_attempt.turn_id = active.turn_id
           AND stopped_attempt.session_id = active.session_id
           AND stopped_attempt.interrupt_command_id = existing.command_id
           AND stopped_attempt.interrupt_predecessor_turn_id = active.turn_id
           AND (
                (
                    active.active_phase_kind = 'running'
                    AND stopped_attempt.state_kind = 'stop_requested'
                )
                OR (
                    active.active_phase_kind = 'awaiting_model_call_recovery'
                    AND stopped_attempt.state_kind = 'ended'
                    AND stopped_attempt.end_variant = 'after_cancellation'
                    AND stopped_attempt.end_disposition IN ('ambiguous', 'lost')
                )
           )
         WHERE existing.command_id = NEW.result_existing_interrupt_command_id
           AND existing.result_kind = 'applied'
           AND existing.rejection_kind IS NULL
           AND existing.delivery_kind = 'interrupt'
           AND existing.expected_active_turn_id = NEW.result_actual_active_turn_id
           AND NOT EXISTS (
                SELECT 1
                  FROM accepted_input
                 WHERE accepting_command_id = NEW.command_id
           );
    END IF;

    IF matching_records <> 1 THEN
        RAISE EXCEPTION
            'interrupt submit-input command % has an incomplete or cross-wired effect',
            NEW.command_id
            USING ERRCODE = '23503';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_model_call_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_model_call_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_model_call_final_state(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.model_call_id ELSE NEW.model_call_id END
    );
    PERFORM assert_turn_lifecycle_final_state(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.turn_id ELSE NEW.turn_id END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_next_outbox_delivery(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_next_outbox_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.singleton <> OLD.singleton
        OR NEW.delivered_through <> OLD.delivered_through + 1 THEN
        RAISE EXCEPTION 'outbox delivery must advance by exactly one sequence'
            USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT 1 FROM outbox_sequence_state
         WHERE singleton AND last_allocation_xid = pg_current_xact_id()
    ) THEN
        RAISE EXCEPTION
            'outbox delivery cannot advance in an event-producing transaction'
            USING ERRCODE = '23514';
    END IF;
    NEW.last_delivery_xid := pg_current_xact_id();
    IF NOT EXISTS (
        SELECT 1 FROM outbox_event
         WHERE event_sequence = NEW.delivered_through
    ) AND NOT EXISTS (
        SELECT 1 FROM delegation_outbox_event
         WHERE event_sequence = NEW.delivered_through
    ) THEN
        RAISE EXCEPTION 'outbox delivery sequence % requires a committed event',
            NEW.delivered_through USING ERRCODE = '23503';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_outbox_event_typed_record(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_outbox_event_typed_record() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_records bigint;
BEGIN
    CASE NEW.event_kind
        WHEN 'session_created' THEN
            SELECT count(*) INTO matching_records
              FROM session_created_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'session_model_settings_changed' THEN
            SELECT count(*) INTO matching_records
              FROM session_model_settings_changed_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_model_settings_resolved' THEN
            SELECT count(*) INTO matching_records
              FROM turn_model_settings_resolved_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'input_accepted' THEN
            SELECT count(*) INTO matching_records
              FROM input_accepted_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'goal_turn_retired' THEN
            SELECT count(*) INTO matching_records
              FROM goal_turn_retired_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_activated' THEN
            SELECT count(*) INTO matching_records
              FROM turn_activated_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_failed' THEN
            SELECT count(*) INTO matching_records
              FROM turn_failed_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'model_call_transition' THEN
            SELECT count(*) INTO matching_records
              FROM model_call_transition_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'tool_batch_transition' THEN
            SELECT count(*) INTO matching_records
              FROM tool_batch_transition_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'tool_approval_decided' THEN
            SELECT count(*) INTO matching_records
              FROM tool_approval_decided_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'context_compacted' THEN
            SELECT count(*) INTO matching_records
              FROM context_compacted_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_completed' THEN
            SELECT count(*) INTO matching_records
              FROM turn_completed_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_refused' THEN
            SELECT count(*) INTO matching_records
              FROM turn_refused_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_cancelled' THEN
            SELECT count(*) INTO matching_records
              FROM turn_cancelled_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'turn_reconciliation_required' THEN
            SELECT count(*) INTO matching_records
              FROM turn_reconciliation_required_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        WHEN 'runner_state_transition' THEN
            SELECT count(*) INTO matching_records
              FROM runner_state_transition_outbox_event
             WHERE event_sequence = NEW.event_sequence;
        ELSE
            RAISE EXCEPTION 'unsupported outbox event kind %', NEW.event_kind
                USING ERRCODE = '23514';
    END CASE;

    IF matching_records <> 1 THEN
        RAISE EXCEPTION 'outbox event % requires exactly one % typed record',
            NEW.event_sequence,
            NEW.event_kind
            USING ERRCODE = '23503';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_outbox_sequence_event(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_outbox_sequence_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.last_sequence <> OLD.last_sequence + 1 THEN
        RAISE EXCEPTION 'outbox sequence must advance exactly once per event'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.last_allocation_xid IS DISTINCT FROM pg_current_xact_id() THEN
        RAISE EXCEPTION 'outbox allocator transaction must accompany its sequence'
            USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM outbox_event
         WHERE event_sequence = NEW.last_sequence
    ) AND NOT EXISTS (
        SELECT 1 FROM delegation_outbox_event
         WHERE event_sequence = NEW.last_sequence
    ) THEN
        RAISE EXCEPTION 'outbox sequence % requires its event row', NEW.last_sequence
            USING ERRCODE = '23503';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_override_command_effect(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_override_command_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    override_count bigint;
BEGIN
    SELECT count(*) INTO override_count
      FROM tool_approval_user_override
     WHERE command_id = NEW.command_id;
    IF (NEW.result_kind = 'applied' AND override_count <> 1)
       OR (NEW.result_kind = 'rejected' AND override_count <> 0)
    THEN
        RAISE EXCEPTION 'override command lacks its exact recorded effect'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'override_denied_tool_request_command_requires_effect';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_pending_steering_active_source(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_pending_steering_active_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_state text;
BEGIN
    IF TG_TABLE_NAME = 'accepted_input' THEN
        IF NEW.disposition_kind = 'pending_steering' THEN
            SELECT state_kind
              INTO checked_state
              FROM turn_lifecycle
             WHERE turn_id = NEW.expected_active_turn_id
               AND session_id = NEW.session_id
               FOR UPDATE;

            IF checked_state IS DISTINCT FROM 'active' THEN
                RAISE EXCEPTION
                    'pending steering % does not name an active source turn',
                    NEW.accepted_input_id
                    USING
                        ERRCODE = '23514',
                        CONSTRAINT = 'accepted_input_pending_source_active';
            END IF;
        END IF;
    ELSIF NEW.state_kind = 'terminal'
          AND EXISTS (
              SELECT 1
                FROM accepted_input
               WHERE session_id = NEW.session_id
                 AND expected_active_turn_id = NEW.turn_id
                 AND disposition_kind = 'pending_steering'
          )
    THEN
        RAISE EXCEPTION
            'turn % cannot become terminal while pending steering remains',
            NEW.turn_id
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'turn_lifecycle_pending_steering_closed';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_program_journal_append_sequence(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_program_journal_append_sequence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    sequence program_run_journal_sequence_state%ROWTYPE;
BEGIN
    SELECT *
      INTO sequence
      FROM program_run_journal_sequence_state
     WHERE run_id = NEW.run_id
     FOR UPDATE;

    IF NOT FOUND
       OR NEW.journal_position <> sequence.last_position + 1
       OR (
           NEW.frame_direction = 'request'
           AND NEW.request_ordinal <> sequence.last_request_ordinal + 1
       )
       OR (
           NEW.frame_direction = 'delivery'
           AND NEW.delivery_ordinal <> sequence.last_delivery_ordinal + 1
       ) THEN
        RAISE EXCEPTION
            'program journal frame does not extend every applicable sequence by one'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_program_journal_nondeterminism_evidence(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_program_journal_nondeterminism_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    cause text;
    evidence_count bigint;
BEGIN
    SELECT fault_cause
      INTO cause
      FROM program_run_journal_entry
     WHERE run_id = NEW.run_id
       AND journal_position = NEW.journal_position;

    SELECT count(*)
      INTO evidence_count
      FROM program_run_journal_nondeterminism
     WHERE run_id = NEW.run_id
       AND journal_position = NEW.journal_position;

    IF (cause IS NOT DISTINCT FROM 'nondeterminism') <> (evidence_count = 1) THEN
        RAISE EXCEPTION
            'nondeterminism fault and its complete twin frames must commit together'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_program_journal_sequence_matches_entries(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_program_journal_sequence_matches_entries() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    sequence program_run_journal_sequence_state%ROWTYPE;
    maximum_position numeric(20, 0);
    maximum_request numeric(20, 0);
    maximum_delivery numeric(20, 0);
    position_count bigint;
    request_count bigint;
    delivery_count bigint;
BEGIN
    SELECT *
      INTO sequence
      FROM program_run_journal_sequence_state
     WHERE run_id = NEW.run_id;
    SELECT COALESCE(max(journal_position), 0),
           COALESCE(max(request_ordinal), 0),
           COALESCE(max(delivery_ordinal), 0),
           count(*),
           count(request_ordinal),
           count(delivery_ordinal)
      INTO maximum_position, maximum_request, maximum_delivery,
           position_count, request_count, delivery_count
      FROM program_run_journal_entry
     WHERE run_id = NEW.run_id;

    IF sequence.run_id IS NULL
       OR sequence.last_position <> maximum_position
       OR sequence.last_request_ordinal <> maximum_request
       OR sequence.last_delivery_ordinal <> maximum_delivery
       OR position_count <> maximum_position
       OR request_count <> maximum_request
       OR delivery_count <> maximum_delivery THEN
        RAISE EXCEPTION
            'program journal sequence state disagrees with committed frames'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_program_journal_stream_sequence_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_program_journal_stream_sequence_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM program_run_journal_sequence_state
         WHERE run_id = NEW.run_id
    ) THEN
        RAISE EXCEPTION
            'program journal stream requires one sequence state row'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_pursuing_goal_event_turn(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_pursuing_goal_event_turn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE matching_turns bigint;
BEGIN
    IF NEW.event_kind NOT IN ('commissioned', 'resumed', 'superseded') THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO matching_turns FROM goal_turn
     WHERE session_id = NEW.session_id
       AND source_event_ordinal = NEW.event_ordinal;
    IF matching_turns <> 1 THEN
        RAISE EXCEPTION 'pursuing goal event requires exactly one source turn'
            USING ERRCODE = '23514',
                CONSTRAINT = 'goal_event_pursuing_turn';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_repo_watch_event_cursor_commit(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_repo_watch_event_cursor_commit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM repo_watch_cursor
         WHERE repository = NEW.repository
           AND generation = NEW.cursor_generation
           AND recording_transaction_id = pg_current_xact_id()
    ) THEN
        RAISE EXCEPTION
            'repository-watch event requires its cursor commit transaction'
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'repo_watch_event_requires_current_cursor_transaction';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_review_attachment_posted_event(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_attachment_posted_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    canonical_event_kind text;
    canonical_finding uuid;
    canonical_ordinal bigint;
BEGIN
    SELECT result_event_kind, result_finding_id, result_event_ordinal
      INTO canonical_event_kind, canonical_finding, canonical_ordinal
      FROM review_pass
     WHERE pass_id = NEW.pass_id
       AND run_id = NEW.pass_run_id
       AND target_id = NEW.target_id;
    IF canonical_event_kind = 'posted'
       AND NOT EXISTS (
           SELECT 1
             FROM review_finding_event
            WHERE finding_id = canonical_finding
              AND event_ordinal = canonical_ordinal
              AND target_id = NEW.target_id
              AND event_pass_id = NEW.pass_id
              AND event_pass_run_id = NEW.pass_run_id
              AND event_kind = 'posted'
              AND external_link_id = NEW.external_link_id
       )
    THEN
        RAISE EXCEPTION
            'external attachment omitted its exact posted finding event'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_review_external_identity_attachment(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_external_identity_attachment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM review_external_link_attachment AS attachment
          JOIN review_target AS attached_target
            ON attached_target.target_id = attachment.target_id
         JOIN review_target AS logical_target
            ON logical_target.target_id = NEW.logical_target_id
         WHERE attachment.identity_digest = NEW.identity_digest
           AND attachment.provider_key = NEW.provider_key
           AND attachment.object_kind = NEW.object_kind
           AND attachment.external_object_key = NEW.external_object_key
           AND (
               attachment.target_id = NEW.logical_target_id
               OR (
                   attached_target.subject_kind = 'change_request'
                   AND logical_target.subject_kind = 'change_request'
                   AND attached_target.provider_key =
                       logical_target.provider_key
                   AND attached_target.repository_key =
                       logical_target.repository_key
                   AND attached_target.change_request_number =
                       logical_target.change_request_number
               )
           )
    )
    THEN
        RAISE EXCEPTION
            'external object identity lacks an establishing attachment'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_review_external_observation_sequence(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_external_observation_sequence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_ordinal bigint;
    latest_state text;
    canonical_pass_kind text;
    canonical_pass_state text;
    canonical_result_kind text;
    canonical_result_link uuid;
    canonical_result_ordinal bigint;
    canonical_result_state text;
BEGIN
    PERFORM 1
      FROM review_external_link
     WHERE external_link_id = NEW.external_link_id
     FOR NO KEY UPDATE;

    SELECT pass_kind, state_kind, result_kind,
           result_external_link_id, result_event_ordinal,
           result_observation_state
      INTO canonical_pass_kind, canonical_pass_state,
           canonical_result_kind, canonical_result_link,
           canonical_result_ordinal, canonical_result_state
      FROM review_pass
     WHERE pass_id = NEW.pass_id
       AND run_id = NEW.pass_run_id
       AND target_id = NEW.target_id;
    IF canonical_pass_kind IS DISTINCT FROM 'import_external_context'
       OR canonical_pass_state IS DISTINCT FROM 'succeeded'
       OR canonical_result_kind
            IS DISTINCT FROM 'external_link_observation'
       OR canonical_result_link
            IS DISTINCT FROM NEW.external_link_id
       OR canonical_result_ordinal
            IS DISTINCT FROM NEW.observation_ordinal
       OR canonical_result_state
            IS DISTINCT FROM NEW.object_state
    THEN
        RAISE EXCEPTION
            'external observation requires a succeeded import pass'
            USING ERRCODE = '23514';
    END IF;

    SELECT observation_ordinal + 1, object_state
      INTO expected_ordinal, latest_state
      FROM review_external_link_observation
     WHERE external_link_id = NEW.external_link_id
     ORDER BY observation_ordinal DESC
     LIMIT 1;
    expected_ordinal := COALESCE(expected_ordinal, 1);

    IF latest_state IS NOT NULL
       AND latest_state IS NOT DISTINCT FROM NEW.object_state
    THEN
        RAISE EXCEPTION
            'unchanged external observation is not durable evidence'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.observation_ordinal <> expected_ordinal THEN
        RAISE EXCEPTION
            'external observation ordinal %, expected %',
            NEW.observation_ordinal,
            expected_ordinal
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_review_finding_event_head_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_finding_event_head_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_review_finding_event_head_complete(
        COALESCE(NEW.finding_id, OLD.finding_id)
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_review_finding_event_sequence(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_finding_event_sequence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_pass_kind text;
    event_pass_state text;
    event_pass_result_kind text;
    event_pass_result_finding uuid;
    event_pass_result_run uuid;
    event_pass_result_pass uuid;
    event_pass_result_ordinal bigint;
    event_pass_result_event_kind text;
    event_pass_result_reason text;
    event_pass_result_referenced_finding uuid;
    event_pass_result_referenced_run uuid;
    event_pass_result_referenced_target uuid;
    event_pass_result_referenced_pass uuid;
    event_pass_result_referenced_status text;
    event_pass_result_external_link uuid;
    event_policy_version bigint;
    event_judge_confidence integer;
    event_publication_confidence integer;
    finding_policy_version bigint;
    finding_judge_confidence integer;
    finding_publication_confidence integer;
    finding_is_real_confidence integer;
    finding_producing_pass uuid;
    referenced_pass_kind text;
    referenced_pass_state text;
    referenced_pass_result_kind text;
    referenced_run_state text;
    referenced_run_state_pass uuid;
    referenced_policy_version bigint;
    referenced_judge_confidence integer;
    referenced_publication_confidence integer;
    referenced_seal_count integer;
BEGIN
    PERFORM finding_id
      FROM review_finding
     WHERE finding_id IN (
         NEW.finding_id,
         NEW.referenced_finding_id
     )
     ORDER BY finding_id
     FOR NO KEY UPDATE;

    SELECT finding.is_real_confidence,
           finding.producing_pass_id,
           producing_run.policy_version,
           producing_run.minimum_judge_confidence,
           producing_run.minimum_publication_confidence
      INTO finding_is_real_confidence,
           finding_producing_pass,
           finding_policy_version,
           finding_judge_confidence,
           finding_publication_confidence
      FROM review_finding AS finding
      JOIN review_run AS producing_run
        ON producing_run.run_id = finding.run_id
       AND producing_run.target_id = finding.target_id
     WHERE finding.finding_id = NEW.finding_id
       AND finding.run_id = NEW.finding_run_id
       AND finding.target_id = NEW.target_id;

    SELECT pass.pass_kind, pass.state_kind,
           pass.result_kind,
           pass.result_finding_id,
           pass.result_finding_run_id,
           pass.result_finding_pass_id,
           pass.result_event_ordinal,
           pass.result_event_kind,
           pass.result_reason,
           pass.result_referenced_finding_id,
           pass.result_referenced_finding_run_id,
           pass.result_referenced_finding_target_id,
           pass.result_referenced_finding_pass_id,
           pass.result_referenced_finding_status,
           pass.result_external_link_id,
           event_run.policy_version,
           event_run.minimum_judge_confidence,
           event_run.minimum_publication_confidence
      INTO event_pass_kind, event_pass_state,
           event_pass_result_kind,
           event_pass_result_finding,
           event_pass_result_run,
           event_pass_result_pass,
           event_pass_result_ordinal,
           event_pass_result_event_kind,
           event_pass_result_reason,
           event_pass_result_referenced_finding,
           event_pass_result_referenced_run,
           event_pass_result_referenced_target,
           event_pass_result_referenced_pass,
           event_pass_result_referenced_status,
           event_pass_result_external_link,
           event_policy_version,
           event_judge_confidence,
           event_publication_confidence
      FROM review_pass AS pass
      JOIN review_run AS event_run
        ON event_run.run_id = pass.run_id
       AND event_run.target_id = pass.target_id
     WHERE pass.pass_id = NEW.event_pass_id
       AND pass.run_id = NEW.event_pass_run_id
       AND pass.target_id = NEW.target_id;

    IF event_policy_version IS DISTINCT FROM finding_policy_version
       OR event_judge_confidence IS DISTINCT FROM finding_judge_confidence
       OR event_publication_confidence
            IS DISTINCT FROM finding_publication_confidence
    THEN
        RAISE EXCEPTION
            'finding event pass policy differs from finding policy'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.referenced_finding_id IS NOT NULL THEN
        SELECT referenced_pass.pass_kind,
               referenced_pass.state_kind,
               referenced_pass.result_kind,
               referenced_run.state_kind,
               referenced_run.state_pass_id,
               referenced_run.policy_version,
               referenced_run.minimum_judge_confidence,
               referenced_run.minimum_publication_confidence,
               seal.finding_count
          INTO referenced_pass_kind,
               referenced_pass_state,
               referenced_pass_result_kind,
               referenced_run_state,
               referenced_run_state_pass,
               referenced_policy_version,
               referenced_judge_confidence,
               referenced_publication_confidence,
               referenced_seal_count
          FROM review_finding AS referenced
          JOIN review_pass AS referenced_pass
            ON referenced_pass.pass_id =
                referenced.producing_pass_id
           AND referenced_pass.run_id = referenced.run_id
           AND referenced_pass.target_id = referenced.target_id
          JOIN review_run AS referenced_run
            ON referenced_run.run_id = referenced.run_id
           AND referenced_run.target_id = referenced.target_id
          LEFT JOIN review_pass_finding_inventory_seal AS seal
            ON seal.pass_id = referenced.producing_pass_id
         WHERE referenced.finding_id = NEW.referenced_finding_id
           AND referenced.run_id = NEW.referenced_finding_run_id
           AND referenced.target_id = NEW.referenced_finding_target_id
           AND referenced.producing_pass_id =
                NEW.referenced_finding_pass_id;

        IF NEW.referenced_finding_target_id
                IS DISTINCT FROM NEW.target_id
           OR referenced_pass_kind
                IS DISTINCT FROM 'read_only_review'
           OR referenced_pass_state IS DISTINCT FROM 'succeeded'
           OR referenced_pass_result_kind
                IS DISTINCT FROM 'produced_findings'
           OR referenced_run_state IS DISTINCT FROM 'succeeded'
           OR referenced_run_state_pass
                IS DISTINCT FROM NEW.referenced_finding_pass_id
           OR referenced_seal_count IS NULL
           OR NOT EXISTS (
               SELECT 1
                 FROM review_pass_produced_finding
                WHERE finding_id = NEW.referenced_finding_id
                  AND finding_run_id =
                        NEW.referenced_finding_run_id
                  AND target_id =
                        NEW.referenced_finding_target_id
                  AND finding_pass_id =
                        NEW.referenced_finding_pass_id
                  AND pass_id =
                        NEW.referenced_finding_pass_id
           )
        THEN
            RAISE EXCEPTION
                'referenced finding producer or sealed inventory is invalid'
                USING ERRCODE = '23514';
        END IF;

        IF referenced_policy_version
                IS DISTINCT FROM finding_policy_version
           OR referenced_judge_confidence
                IS DISTINCT FROM finding_judge_confidence
           OR referenced_publication_confidence
                IS DISTINCT FROM finding_publication_confidence
        THEN
            RAISE EXCEPTION
                'referenced finding policy differs from finding policy'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.event_kind = 'accepted'
       AND finding_is_real_confidence < finding_judge_confidence
    THEN
        RAISE EXCEPTION
            'finding is-real confidence is below the judge threshold'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.event_kind = 'posted'
       AND finding_is_real_confidence < finding_publication_confidence
    THEN
        RAISE EXCEPTION
            'finding is-real confidence is below the publication threshold'
            USING ERRCODE = '23514';
    END IF;

    IF event_pass_kind IS NULL
       OR NOT (
           (
               NEW.event_kind IN ('accepted', 'rejected', 'stale')
               AND event_pass_kind = 'judge'
           )
           OR (
               NEW.event_kind IN ('duplicate', 'superseded')
               AND event_pass_kind = 'dedupe'
           )
           OR (
               NEW.event_kind = 'posted'
               AND event_pass_kind IN (
                   'publish',
                   'import_external_context'
               )
           )
           OR (
               NEW.event_kind = 'fixed'
               AND event_pass_kind = 'fix'
           )
           OR (
               NEW.event_kind = 'blocked_with_reason'
               AND (
                   (
                       event_pass_kind = 'publish'
                       AND NEW.external_link_id IS NOT NULL
                   )
                   OR (
                       event_pass_kind = 'fix'
                       AND NEW.external_link_id IS NULL
                   )
               )
           )
       )
    THEN
        RAISE EXCEPTION
            'finding event % is incompatible with pass kind %',
            NEW.event_kind,
            event_pass_kind
            USING ERRCODE = '23514';
    END IF;

    IF (
        NEW.event_kind = 'blocked_with_reason'
        AND event_pass_state IS DISTINCT FROM 'blocked'
    ) OR (
        NEW.event_kind <> 'blocked_with_reason'
        AND event_pass_state IS DISTINCT FROM 'succeeded'
    )
    THEN
        RAISE EXCEPTION
            'finding event % is incompatible with pass state %',
            NEW.event_kind,
            event_pass_state
            USING ERRCODE = '23514';
    END IF;

    IF event_pass_result_kind IS DISTINCT FROM (
           CASE NEW.event_kind
               WHEN 'posted' THEN 'external_link_attachment'
               ELSE 'finding_event'
           END
       )
       OR event_pass_result_finding IS DISTINCT FROM NEW.finding_id
       OR event_pass_result_run IS DISTINCT FROM NEW.finding_run_id
       OR event_pass_result_pass IS DISTINCT FROM (
           SELECT producing_pass_id
             FROM review_finding
            WHERE finding_id = NEW.finding_id
              AND run_id = NEW.finding_run_id
              AND target_id = NEW.target_id
       )
       OR event_pass_result_ordinal IS DISTINCT FROM NEW.event_ordinal
       OR event_pass_result_event_kind IS DISTINCT FROM NEW.event_kind
       OR event_pass_result_reason IS DISTINCT FROM NEW.reason
       OR event_pass_result_referenced_finding
            IS DISTINCT FROM NEW.referenced_finding_id
       OR event_pass_result_referenced_run
            IS DISTINCT FROM NEW.referenced_finding_run_id
       OR event_pass_result_referenced_target
            IS DISTINCT FROM NEW.referenced_finding_target_id
       OR event_pass_result_referenced_pass
            IS DISTINCT FROM NEW.referenced_finding_pass_id
       OR event_pass_result_referenced_status
            IS DISTINCT FROM NEW.referenced_finding_status
       OR event_pass_result_external_link
            IS DISTINCT FROM NEW.external_link_id
    THEN
        RAISE EXCEPTION
            'finding event is not the exact result committed by its pass'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.referenced_finding_id IS NOT NULL THEN
        IF EXISTS (
            WITH RECURSIVE referenced_ancestry(
                finding_id,
                run_id,
                target_id,
                pass_id
            ) AS (
                SELECT NEW.referenced_finding_id,
                       NEW.referenced_finding_run_id,
                       NEW.referenced_finding_target_id,
                       NEW.referenced_finding_pass_id
                UNION
                SELECT latest.referenced_finding_id,
                       latest.referenced_finding_run_id,
                       latest.referenced_finding_target_id,
                       latest.referenced_finding_pass_id
                  FROM referenced_ancestry AS ancestry
                  JOIN LATERAL (
                      SELECT referenced_finding_id,
                             referenced_finding_run_id,
                             referenced_finding_target_id,
                             referenced_finding_pass_id
                        FROM review_finding_event
                       WHERE finding_id = ancestry.finding_id
                         AND finding_run_id = ancestry.run_id
                         AND target_id = ancestry.target_id
                         AND event_kind IN (
                             'duplicate',
                             'superseded'
                         )
                       ORDER BY event_ordinal DESC
                       LIMIT 1
                  ) AS latest
                    ON latest.referenced_finding_id IS NOT NULL
            )
            SELECT 1
              FROM referenced_ancestry
             WHERE finding_id = NEW.finding_id
               AND run_id = NEW.finding_run_id
               AND target_id = NEW.target_id
               AND pass_id = finding_producing_pass
        )
        THEN
            RAISE EXCEPTION
                'finding reference would create a cycle'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.event_kind = 'blocked_with_reason'
       AND NEW.external_link_id IS NOT NULL
       AND EXISTS (
           SELECT 1
             FROM review_external_link_attachment
            WHERE external_link_id = NEW.external_link_id
              AND target_id = NEW.target_id
       )
    THEN
        RAISE EXCEPTION
            'publication block requires a pending reservation'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.event_kind = 'posted'
       AND EXISTS (
           SELECT 1
             FROM review_finding_event
            WHERE finding_id = NEW.finding_id
              AND event_kind = 'posted'
              AND external_link_id = NEW.external_link_id
       )
    THEN
        RAISE EXCEPTION
            'posted event reused consumed attachment evidence'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.event_kind = 'posted'
       AND NOT EXISTS (
           SELECT 1
             FROM review_external_link_attachment AS attachment
             JOIN review_external_link AS link
               ON link.external_link_id = attachment.external_link_id
              AND link.target_id = attachment.target_id
            WHERE attachment.external_link_id = NEW.external_link_id
              AND attachment.target_id = NEW.target_id
              AND attachment.pass_run_id = NEW.event_pass_run_id
              AND attachment.pass_id = NEW.event_pass_id
              AND link.object_kind IN (
                  'review',
                  'review_thread',
                  'review_comment',
                  'change_request_comment'
              )
       )
    THEN
        RAISE EXCEPTION
            'posted event pass did not produce its attachment'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_review_pass_external_result(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_pass_external_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.result_kind = 'finding_event'
       AND NOT EXISTS (
           SELECT 1
             FROM review_finding_event AS event
             JOIN review_finding AS finding
               ON finding.finding_id = event.finding_id
              AND finding.run_id = event.finding_run_id
              AND finding.target_id = event.target_id
            WHERE event.finding_id = NEW.result_finding_id
              AND event.finding_run_id = NEW.result_finding_run_id
              AND finding.producing_pass_id =
                    NEW.result_finding_pass_id
              AND event.target_id = NEW.target_id
              AND event.event_pass_id = NEW.pass_id
              AND event.event_pass_run_id = NEW.run_id
              AND event.event_ordinal = NEW.result_event_ordinal
              AND event.event_kind = NEW.result_event_kind
              AND event.reason IS NOT DISTINCT FROM NEW.result_reason
              AND event.referenced_finding_id IS NOT DISTINCT FROM
                    NEW.result_referenced_finding_id
              AND event.referenced_finding_run_id IS NOT DISTINCT FROM
                    NEW.result_referenced_finding_run_id
              AND event.referenced_finding_target_id IS NOT DISTINCT FROM
                    NEW.result_referenced_finding_target_id
              AND event.referenced_finding_pass_id IS NOT DISTINCT FROM
                    NEW.result_referenced_finding_pass_id
              AND event.referenced_finding_status IS NOT DISTINCT FROM
                    NEW.result_referenced_finding_status
              AND event.external_link_id IS NOT DISTINCT FROM
                    NEW.result_external_link_id
              AND event.external_link_association_kind IS NOT DISTINCT FROM
                    CASE
                        WHEN NEW.result_external_link_id IS NULL THEN NULL
                        ELSE 'finding'
                    END
       )
    THEN
        RAISE EXCEPTION
            'finding-event result omitted its exact child row'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.result_kind = 'external_link_attachment'
       AND NOT EXISTS (
           SELECT 1
             FROM review_external_link_attachment
            WHERE external_link_id = NEW.result_external_link_id
              AND target_id = NEW.target_id
              AND pass_run_id = NEW.run_id
              AND pass_id = NEW.pass_id
              AND external_object_key =
                    NEW.result_external_object_key
       )
    THEN
        RAISE EXCEPTION
            'external attachment result omitted its exact child row'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.result_kind = 'external_link_observation'
       AND NOT EXISTS (
           SELECT 1
             FROM review_external_link_observation
            WHERE external_link_id = NEW.result_external_link_id
              AND observation_ordinal = NEW.result_event_ordinal
              AND target_id = NEW.target_id
              AND pass_run_id = NEW.run_id
              AND pass_id = NEW.pass_id
              AND object_state =
                    NEW.result_observation_state
       )
    THEN
        RAISE EXCEPTION
            'external observation result omitted its exact child row'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.result_kind = 'external_link_no_change'
       AND (
           NOT EXISTS (
               SELECT 1
                 FROM review_external_link_attachment
                WHERE external_link_id = NEW.result_external_link_id
                  AND target_id = NEW.target_id
           )
           OR NEW.result_observation_state IS DISTINCT FROM (
               SELECT object_state
                 FROM review_external_link_observation
                WHERE external_link_id = NEW.result_external_link_id
                ORDER BY observation_ordinal DESC
                LIMIT 1
           )
           OR NEW.result_event_ordinal IS DISTINCT FROM (
               SELECT observation_ordinal
                 FROM review_external_link_observation
                WHERE external_link_id = NEW.result_external_link_id
                ORDER BY observation_ordinal DESC
                LIMIT 1
           )
       )
    THEN
        RAISE EXCEPTION
            'unchanged external result differs from latest durable state'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.result_kind = 'external_link_publication_blocked' THEN
        PERFORM 1
          FROM review_external_link
         WHERE external_link_id = NEW.result_external_link_id
         FOR NO KEY UPDATE;
    END IF;
    IF NEW.result_kind = 'external_link_publication_blocked'
       AND EXISTS (
           SELECT 1
             FROM review_external_link_attachment
            WHERE external_link_id = NEW.result_external_link_id
              AND target_id = NEW.target_id
       )
    THEN
        RAISE EXCEPTION
            'blocked publication result requires a pending reservation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_review_pass_finding_inventory(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_pass_finding_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_pass uuid;
    canonical_kind text;
    sealed_count integer;
BEGIN
    checked_pass := COALESCE(
        (to_jsonb(NEW) ->> 'pass_id')::uuid,
        (to_jsonb(NEW) ->> 'producing_pass_id')::uuid
    );

    SELECT result_kind
      INTO canonical_kind
      FROM review_pass
     WHERE pass_id = checked_pass;
    SELECT finding_count
      INTO sealed_count
      FROM review_pass_finding_inventory_seal
     WHERE pass_id = checked_pass;

    IF canonical_kind IS DISTINCT FROM 'produced_findings'
       AND (
           EXISTS (
               SELECT 1
                 FROM review_finding
                WHERE producing_pass_id = checked_pass
           )
           OR EXISTS (
               SELECT 1
                 FROM review_pass_produced_finding
                WHERE pass_id = checked_pass
           )
           OR sealed_count IS NOT NULL
       )
    THEN
        RAISE EXCEPTION
            'review finding producer has no produced-findings result'
            USING ERRCODE = '23514';
    END IF;

    IF canonical_kind = 'produced_findings'
       AND (
           sealed_count IS NULL
           OR sealed_count IS DISTINCT FROM (
               SELECT count(*)
                 FROM review_finding
                WHERE producing_pass_id = checked_pass
           )
           OR sealed_count IS DISTINCT FROM (
               SELECT count(*)
                 FROM review_pass_produced_finding
                WHERE pass_id = checked_pass
           )
           OR
           EXISTS (
               SELECT finding_id, run_id, target_id, producing_pass_id
                 FROM review_finding
                WHERE producing_pass_id = checked_pass
               EXCEPT
               SELECT finding_id, finding_run_id, target_id, finding_pass_id
                 FROM review_pass_produced_finding
                WHERE pass_id = checked_pass
           )
           OR EXISTS (
               SELECT finding_id, finding_run_id, target_id, finding_pass_id
                 FROM review_pass_produced_finding
                WHERE pass_id = checked_pass
               EXCEPT
               SELECT finding_id, run_id, target_id, producing_pass_id
                 FROM review_finding
                WHERE producing_pass_id = checked_pass
           )
           OR EXISTS (
               SELECT 1
                 FROM (
                     SELECT result_ordinal,
                            row_number() OVER (
                                ORDER BY
                                    target_id,
                                    finding_run_id,
                                    finding_pass_id,
                                    finding_id
                            ) AS canonical_ordinal
                       FROM review_pass_produced_finding
                      WHERE pass_id = checked_pass
                 ) AS inventory
                WHERE result_ordinal <> canonical_ordinal
           )
       )
    THEN
        RAISE EXCEPTION
            'review pass finding inventory differs from canonical findings'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_review_pass_run_projection(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_pass_run_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    canonical_run_state text;
    canonical_run_pass uuid;
BEGIN
    SELECT state_kind, state_pass_id
      INTO canonical_run_state, canonical_run_pass
      FROM review_run
     WHERE run_id = NEW.run_id
       AND target_id = NEW.target_id;

    IF NEW.state_kind = 'queued' THEN
        IF canonical_run_state IS DISTINCT FROM 'queued'
           OR canonical_run_pass IS NOT NULL
        THEN
            RAISE EXCEPTION 'queued pass is not under a queued run'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.state_kind = 'cancelled' AND NEW.turn_id IS NULL THEN
        IF canonical_run_state IS DISTINCT FROM 'cancelled'
           OR canonical_run_pass IS DISTINCT FROM NEW.pass_id
        THEN
            RAISE EXCEPTION
                'pre-start cancelled pass contradicts its run projection'
                USING ERRCODE = '23514';
        END IF;
    ELSIF canonical_run_pass IS DISTINCT FROM NEW.pass_id
          OR canonical_run_state IS DISTINCT FROM NEW.state_kind
    THEN
        RAISE EXCEPTION
            'review pass state contradicts its run projection'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_review_run_pass_projection(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_review_run_pass_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    canonical_pass_id uuid;
    canonical_pass_state text;
    canonical_pass_turn uuid;
BEGIN
    SELECT pass_id, state_kind, turn_id
      INTO canonical_pass_id, canonical_pass_state, canonical_pass_turn
      FROM review_pass
     WHERE run_id = NEW.run_id
       AND target_id = NEW.target_id;

    IF NEW.state_kind = 'queued' THEN
        IF canonical_pass_id IS NOT NULL
           AND canonical_pass_state IS DISTINCT FROM 'queued'
        THEN
            RAISE EXCEPTION 'queued run has a non-queued pass'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.state_kind = 'cancelled' AND NEW.state_pass_id IS NULL THEN
        IF canonical_pass_id IS NOT NULL THEN
            RAISE EXCEPTION
                'cancelled run without pass projection has a recorded pass'
                USING ERRCODE = '23514';
        END IF;
    ELSIF canonical_pass_id IS DISTINCT FROM NEW.state_pass_id
          OR canonical_pass_state IS DISTINCT FROM NEW.state_kind
    THEN
        RAISE EXCEPTION
            'review run state contradicts its pass projection'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$;


