--
-- Name: require_runner_profileless_grant_tombstone(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_profileless_grant_tombstone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    prior_grant_origin numeric;
    prior_grant_runner uuid;
    prior_grant_revision numeric;
BEGIN
    IF NEW.state_kind IN ('pinned', 'runner_lost')
       AND NEW.pinned_credential_profile_name IS NULL
       AND NEW.credential_grant_revision IS NOT NULL
    THEN
        IF NOT EXISTS (
            SELECT 1
              FROM runner_credential_grant AS grant_record
              JOIN runner_credential_grant_audit AS audit
                ON audit.session_id = grant_record.session_id
               AND audit.lineage_origin_event_ordinal =
                    grant_record.lineage_origin_event_ordinal
               AND audit.runner_id = grant_record.runner_id
               AND audit.grant_revision = grant_record.grant_revision
               AND audit.event_kind = 'revoked'
             WHERE grant_record.session_id = NEW.session_id
               AND grant_record.lineage_origin_event_ordinal =
                    NEW.credential_grant_lineage_origin_ordinal
               AND grant_record.runner_id = NEW.credential_grant_runner_id
               AND grant_record.grant_revision = NEW.credential_grant_revision
        ) THEN
            RAISE EXCEPTION 'profileless grant authority must be a revoked tombstone'
                USING ERRCODE = '23514';
        END IF;
        IF NEW.event_kind = 'runner_replaced' THEN
            SELECT credential_grant_lineage_origin_ordinal,
                   credential_grant_runner_id, credential_grant_revision
              INTO prior_grant_origin, prior_grant_runner, prior_grant_revision
              FROM runner_session_placement_record
             WHERE session_id = NEW.session_id
               AND event_ordinal = NEW.event_ordinal - 1;
            IF NOT FOUND
               OR NEW.credential_grant_lineage_origin_ordinal IS DISTINCT FROM
                    prior_grant_origin
               OR NEW.credential_grant_runner_id IS DISTINCT FROM
                    prior_grant_runner
               OR NEW.credential_grant_revision IS DISTINCT FROM
                    prior_grant_revision + 1
            THEN
                RAISE EXCEPTION 'profileless grant tombstone does not succeed the immediate prior grant'
                    USING ERRCODE = '23514';
            END IF;
        ELSIF NEW.event_kind <> 'runner_lost' THEN
            RAISE EXCEPTION 'profileless grant tombstone lacks a canonical transition'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.event_kind = 'runner_lost' THEN
        SELECT credential_grant_lineage_origin_ordinal,
               credential_grant_runner_id, credential_grant_revision
          INTO prior_grant_origin, prior_grant_runner, prior_grant_revision
          FROM runner_session_placement_record
         WHERE session_id = NEW.session_id
           AND event_ordinal = NEW.event_ordinal - 1;
        IF NEW.credential_grant_lineage_origin_ordinal IS DISTINCT FROM
                prior_grant_origin
           OR NEW.credential_grant_runner_id IS DISTINCT FROM prior_grant_runner
           OR NEW.credential_grant_revision IS DISTINCT FROM
                prior_grant_revision
        THEN
            RAISE EXCEPTION 'runner loss changed grant authority'
                USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_runner_registration_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_registration_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_runner_registration_complete(
        COALESCE(NEW.enrollment_id, OLD.enrollment_id),
        COALESCE(NEW.registration_revision, OLD.registration_revision)
    );

    RETURN NULL;
END;
$$;


--
-- Name: require_runner_retry_attempt_authority(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_retry_attempt_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM tool_attempt AS prior
         WHERE prior.request_id = NEW.request_id
    )
       AND NOT EXISTS (
            SELECT 1
              FROM runner_claimed_retry_attempt_authority AS authority
             WHERE authority.replacement_attempt_id = NEW.attempt_id
               AND authority.replacement_session_id = NEW.session_id
               AND authority.replacement_turn_id = NEW.turn_id
               AND authority.replacement_issuing_turn_attempt_id =
                    NEW.issuing_turn_attempt_id
               AND authority.replacement_request_id = NEW.request_id
               AND authority.replacement_dispatch_generation =
                    NEW.dispatch_generation
       )
    THEN
        RAISE EXCEPTION 'extra tool attempt lacks durable runner retry authority'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: require_runner_retry_replacement_successor_lease(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_retry_replacement_successor_lease() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    authority runner_claimed_retry_attempt_authority%ROWTYPE;
BEGIN
    SELECT * INTO authority
      FROM runner_claimed_retry_attempt_authority
     WHERE replacement_attempt_id = NEW.attempt_id;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM runner_lease_generation AS generation
         WHERE generation.lease_id = authority.source_lease_id
           AND generation.predecessor_generation = authority.source_generation
           AND generation.attempt_id = NEW.attempt_id
    )
    THEN
        RAISE EXCEPTION
            'replacement attempt lacks its atomic successor lease generation'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_runner_retryable_loss_live_attempt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_retryable_loss_live_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    lease runner_lease_generation%ROWTYPE;
    attempt_state text;
    attempt_effect text;
BEGIN
    IF NEW.state_kind NOT IN
        ('lost_unclaimed', 'lost_execution_possible', 'lost_claimed')
    THEN
        RETURN NULL;
    END IF;
    SELECT * INTO lease
     FROM runner_lease_generation
     WHERE lease_id = NEW.lease_id
       AND generation = NEW.generation;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'runner claimed loss lacks its lease generation'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.state_kind <> 'lost_unclaimed'
       AND lease.effect_class = 'side_effecting'
    THEN
        RETURN NULL;
    END IF;
    SELECT state_kind, effect_class
      INTO attempt_state, attempt_effect
      FROM tool_attempt
     WHERE attempt_id = lease.attempt_id
       AND session_id = lease.session_id
       FOR SHARE;
    IF attempt_state IS DISTINCT FROM 'in_flight'
       OR attempt_effect IS DISTINCT FROM (
            CASE lease.effect_class
                WHEN 'pure' THEN 'effect_free'
                ELSE 'external_effect'
            END
       )
    THEN
        RAISE EXCEPTION 'runner retryable loss lacks its live physical attempt'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_runner_tool_request_lease_binding_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_tool_request_lease_binding_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    binding runner_tool_request_lease_binding%ROWTYPE :=
        COALESCE(NEW, OLD);
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM runner_lease_generation AS generation
          JOIN tool_attempt AS attempt
            ON attempt.attempt_id = generation.attempt_id
         WHERE generation.lease_id = binding.lease_id
           AND attempt.request_id = binding.request_id
    )
    THEN
        RAISE EXCEPTION 'runner request binding lacks its lease lineage'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_runner_wire_placement_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_wire_placement_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_runner_wire_placement_complete(
        COALESCE(NEW.session_id, OLD.session_id),
        COALESCE(NEW.event_ordinal, OLD.event_ordinal)
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_runner_wire_registration_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_runner_wire_registration_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_runner_wire_registration_complete(
        COALESCE(NEW.enrollment_id, OLD.enrollment_id),
        COALESCE(NEW.registration_revision, OLD.registration_revision)
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_semantic_delegation_result_delivery_mode(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_semantic_delegation_result_delivery_mode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_child_result_delivery AS delivery
         WHERE delivery.awaiting_tool_request_id =
                NEW.delegation_result_awaiting_tool_request_id
           AND delivery.spawning_tool_request_id =
                NEW.delegation_result_spawning_tool_request_id
           AND delivery.parent_session_id = NEW.source_session_id
           AND (
                (
                    delivery.delivery_sequence IS NULL
                    AND NEW.tool_result_request_id =
                        NEW.delegation_result_awaiting_tool_request_id
                )
                OR (
                    delivery.delivery_sequence IS NOT NULL
                    AND NEW.tool_result_request_id IS NULL
                )
           )
    ) THEN
        RAISE EXCEPTION 'delegation result correlation contradicts its delivery mode'
            USING ERRCODE = '23514',
                CONSTRAINT = 'semantic_delegation_result_delivery_mode';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_semantic_entry_turn_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_semantic_entry_turn_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    entry semantic_transcript_entry%ROWTYPE;
    checked_turn_id uuid;
    checked_producing_call_id uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        entry := OLD;
    ELSE
        entry := NEW;
    END IF;
    checked_producing_call_id := entry.producing_model_call_id;

    IF entry.payload_kind = 'imported_entry' THEN
        RETURN NULL;
    END IF;

    IF entry.payload_kind = 'context_summary' THEN
        SELECT model_call_id
          INTO checked_producing_call_id
          FROM context_compaction_model_call
         WHERE model_call_id = entry.context_summary_producing_call_id
           AND session_id = entry.source_session_id
           AND state_kind = 'terminal'
           AND terminal_disposition_kind = 'completed';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'context summary lacks its completed dedicated call'
                USING ERRCODE = '23514';
        END IF;
        RETURN NULL;
    END IF;

    CASE entry.payload_kind
        WHEN 'model_identity_changed' THEN
            SELECT origin.turn_id
              INTO checked_turn_id
              FROM queued_input_origin AS origin
              JOIN LATERAL turn_origin_effective_model_configuration(
                   origin.turn_id,
                   origin.session_id
              ) AS effective
                ON true
             WHERE origin.turn_id = entry.model_identity_turn_id
               AND origin.session_id = entry.source_session_id
               AND effective.defaults_version =
                   entry.model_identity_defaults_version
               AND effective.direct_selection_id =
                   entry.model_identity_direct_selection_id;
        WHEN 'origin_accepted_input' THEN
            SELECT origin_turn_id
              INTO checked_turn_id
              FROM accepted_input
             WHERE accepted_input_id = entry.origin_accepted_input_id
               AND session_id = entry.source_session_id
               AND disposition_kind IN (
                    'origin_of',
                    'reclassified_as_turn_origin'
               )
               AND origin_turn_id IS NOT NULL;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'semantic origin input is not a turn origin'
                    USING
                        ERRCODE = '23514',
                        CONSTRAINT =
                            'semantic_transcript_entry_origin_disposition';
            END IF;
        WHEN 'steering_accepted_input' THEN
            SELECT expected_active_turn_id, consuming_model_call_id
              INTO checked_turn_id, checked_producing_call_id
              FROM accepted_input
             WHERE accepted_input_id = entry.origin_accepted_input_id
               AND session_id = entry.source_session_id
               AND disposition_kind = 'consumed_as_steering'
               AND expected_active_turn_id =
                   entry.steering_source_turn_id
               AND consuming_model_call_id IS NOT NULL;
            IF NOT FOUND THEN
                RAISE EXCEPTION
                    'semantic steering input lacks consuming call'
                    USING ERRCODE = '23514';
            END IF;
        WHEN 'turn_failed' THEN
            checked_turn_id := entry.failed_turn_id;
        WHEN 'turn_completed' THEN
            checked_turn_id := entry.completed_turn_id;
        WHEN 'turn_cancelled' THEN
            checked_turn_id := entry.cancelled_turn_id;
        WHEN 'assistant_text' THEN
            SELECT turn_id
              INTO checked_turn_id
              FROM model_call
             WHERE model_call_id = entry.producing_model_call_id
               AND state_kind = 'terminal'
               AND terminal_disposition_kind = 'completed';
        WHEN 'assistant_tool_use' THEN
            SELECT request.turn_id
              INTO checked_turn_id
              FROM tool_request AS request
             WHERE request.request_id = entry.assistant_tool_request_id
               AND request.producing_model_call_id =
                   entry.producing_model_call_id
               AND request.session_id = entry.source_session_id;
        WHEN 'tool_execution_result' THEN
            SELECT turn_id
              INTO checked_turn_id
              FROM tool_attempt
             WHERE attempt_id = entry.tool_result_attempt_id
               AND session_id = entry.source_session_id
               AND state_kind = 'terminal'
               AND terminal_disposition_kind IN ('completed', 'known_failed');
        WHEN 'tool_denied' THEN
            SELECT request.turn_id
              INTO checked_turn_id
              FROM tool_request AS request
              JOIN tool_approval_decision AS approval
                ON approval.request_id = request.request_id
               AND approval.decision_kind = 'deny'
             WHERE request.request_id = entry.tool_result_request_id
               AND request.session_id = entry.source_session_id;
        WHEN 'tool_closed_by_turn_end' THEN
            SELECT request.turn_id
              INTO checked_turn_id
              FROM tool_request AS request
              JOIN turn_lifecycle AS lifecycle
                ON lifecycle.turn_id = request.turn_id
               AND lifecycle.session_id = request.session_id
               AND lifecycle.state_kind = 'terminal'
             WHERE request.request_id = entry.tool_result_request_id
               AND request.session_id = entry.source_session_id;
        ELSE
            RAISE EXCEPTION
                'semantic payload kind % lacks construction authority',
                entry.payload_kind
                USING ERRCODE = '23514';
    END CASE;

    IF checked_turn_id IS NULL THEN
        RAISE EXCEPTION 'semantic entry lacks authoritative turn'
            USING ERRCODE = '23514';
    END IF;
    PERFORM assert_turn_lifecycle_final_state(checked_turn_id);
    IF checked_producing_call_id IS NOT NULL THEN
        PERFORM assert_model_call_final_state(checked_producing_call_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_semantic_steering_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_semantic_steering_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_kind text;
    checked_accepted_input uuid;
BEGIN
    checked_kind := CASE WHEN TG_OP = 'DELETE' THEN OLD.payload_kind ELSE NEW.payload_kind END;
    checked_accepted_input := CASE
        WHEN TG_OP = 'DELETE' THEN OLD.origin_accepted_input_id
        ELSE NEW.origin_accepted_input_id
    END;
    IF checked_kind = 'steering_accepted_input' THEN
        PERFORM assert_steering_accepted_input_final_state(checked_accepted_input);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_blanket_approval_provenance(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_blanket_approval_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_turn uuid;
    checked_session uuid;
    blanket_root_count bigint;
BEGIN
    IF NEW.decision_source <> 'session_blanket' THEN
        RETURN NULL;
    END IF;

    SELECT turn_id, session_id
      INTO checked_turn, checked_session
      FROM tool_request
     WHERE request_id = NEW.request_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'session blanket approval lacks its tool request'
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'tool_approval_session_blanket_requires_frozen_approve_all';
    END IF;

    WITH RECURSIVE configuration_origin AS (
        SELECT stored.*
          FROM queued_input_origin AS stored
         WHERE stored.turn_id = checked_turn
           AND stored.session_id = checked_session
        UNION
        SELECT source.*
          FROM configuration_origin AS current
          JOIN queued_input_origin AS source
            ON source.turn_id = current.source_configuration_turn_id
           AND source.session_id = current.session_id
    )
    SELECT count(*)
      INTO blanket_root_count
      FROM configuration_origin
     WHERE source_configuration_turn_id IS NULL
       AND dangerous_tool_auto_approval = 'approve_all';

    IF blanket_root_count <> 1 THEN
        RAISE EXCEPTION
            'session blanket approval requires frozen approve-all authority'
            USING
                ERRCODE = '23514',
                CONSTRAINT =
                    'tool_approval_session_blanket_requires_frozen_approve_all';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_child_result_delivery_mode(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_child_result_delivery_mode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM session_delegation_wait AS wait
         WHERE wait.awaiting_tool_request_id = NEW.awaiting_tool_request_id
           AND wait.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND wait.parent_session_id = NEW.parent_session_id
           AND (wait.wait_mode = 'foreground') = (NEW.delivery_sequence IS NULL)
    ) THEN
        RAISE EXCEPTION 'result delivery position contradicts its wait mode'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_child_result_delivery_mode';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_child_result_wait_deliveries(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_child_result_wait_deliveries() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_request uuid := COALESCE(
        NEW.spawning_tool_request_id,
        OLD.spawning_tool_request_id
    );
    wait_count bigint;
    delivery_count bigint;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM session_child_result
         WHERE spawning_tool_request_id = checked_request
    ) THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO wait_count
      FROM session_delegation_wait
     WHERE spawning_tool_request_id = checked_request;
    SELECT count(*) INTO delivery_count
      FROM session_child_result_delivery
     WHERE spawning_tool_request_id = checked_request;
    IF delivery_count <> wait_count THEN
        RAISE EXCEPTION 'child result requires one delivery for every registered wait'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_child_result_wait_deliveries';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_creation_command(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_creation_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE native_count bigint; imported_count bigint; delegated_count bigint;
BEGIN
    SELECT count(*) INTO native_count FROM create_session_command
     WHERE created_session_id = NEW.session_id;
    SELECT count(*) INTO imported_count FROM create_session_from_imported_frontier_command
     WHERE created_session_id = NEW.session_id;
    SELECT count(*) INTO delegated_count FROM session_delegation
     WHERE child_session_id = NEW.session_id;
    IF (NEW.creation_cause = 'user_initiated' AND NEW.ancestry_kind = 'none'
            AND (native_count, imported_count, delegated_count) <> (1, 0, 0))
        OR (NEW.creation_cause = 'user_initiated' AND NEW.ancestry_kind = 'imported_conversation'
            AND (native_count, imported_count, delegated_count) <> (0, 1, 0))
        OR (NEW.creation_cause = 'delegated'
            AND (native_count, imported_count, delegated_count) <> (0, 0, 1)) THEN
        RAISE EXCEPTION 'session % requires exactly one matching creation family', NEW.session_id
            USING ERRCODE = '23503', CONSTRAINT = 'session_requires_creation_command';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_delegation_event_payload(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_delegation_event_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    payload_count bigint;
    stored_direction text;
    stored_content text;
    relation_parent uuid;
    relation_child uuid;
    relation_policy text;
    stopped_action text;
    cancelled_action text;
    expected_outcome text;
BEGIN
    SELECT parent_session_id, child_session_id, policy_kind,
           on_parent_stopped, on_parent_cancelled
      INTO relation_parent, relation_child, relation_policy,
           stopped_action, cancelled_action
      FROM session_delegation
     WHERE spawning_tool_request_id = NEW.spawning_tool_request_id;
    SELECT CASE NEW.event_kind
        WHEN 'message_delivered' THEN (SELECT count(*) FROM session_message
            WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
              AND event_ordinal = NEW.event_ordinal)
        WHEN 'outcome_recorded' THEN CASE WHEN NEW.outcome_kind IN (
                'continue_running', 'already_terminal'
            ) THEN 0
            ELSE (SELECT count(*) FROM session_child_result
                WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
                  AND event_ordinal = NEW.event_ordinal
                  AND outcome_kind = NEW.outcome_kind) END
        ELSE 0 END INTO payload_count;
    IF (NEW.event_kind = 'message_delivered' AND payload_count <> 1)
        OR (NEW.event_kind = 'outcome_recorded'
            AND NEW.outcome_kind NOT IN ('continue_running', 'already_terminal')
            AND payload_count <> 1) THEN
        RAISE EXCEPTION 'delegation event requires its exact payload row'
            USING ERRCODE = '23503', CONSTRAINT = 'session_delegation_event_requires_payload';
    END IF;
    IF NEW.event_kind = 'spawned' AND NOT (
        NEW.provenance_kind = 'tool_request'
        AND NEW.provenance_session_id = relation_parent
        AND NEW.provenance_tool_request_id = NEW.spawning_tool_request_id
        AND EXISTS (SELECT 1 FROM tool_request
            WHERE request_id = NEW.spawning_tool_request_id
              AND tool_name = 'spawn_session'
              AND arguments_kind = 'json')
    ) THEN
        RAISE EXCEPTION 'spawn provenance does not match delegation parent'
            USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
    ELSIF NEW.event_kind = 'message_delivered' THEN
        SELECT direction, content_text INTO stored_direction, stored_content
          FROM session_message
         WHERE spawning_tool_request_id = NEW.spawning_tool_request_id
           AND event_ordinal = NEW.event_ordinal;
        IF NEW.provenance_kind <> 'tool_request'
            OR NOT EXISTS (
                SELECT 1
                  FROM tool_request AS request
                  JOIN tool_attempt AS attempt
                    ON attempt.request_id = request.request_id
                   AND attempt.turn_id = request.turn_id
                   AND attempt.session_id = request.session_id
                  JOIN session_message AS message
                    ON message.spawning_tool_request_id =
                        NEW.spawning_tool_request_id
                   AND message.event_ordinal = NEW.event_ordinal
                  JOIN session_message_delivery AS delivery
                    ON delivery.message_id = message.message_id
                   AND delivery.spawning_tool_request_id =
                        message.spawning_tool_request_id
                 WHERE request.request_id = NEW.provenance_tool_request_id
                   AND request.session_id = NEW.provenance_session_id
                   AND request.tool_name = 'send_session_message'
                   AND request.arguments_kind = 'json'
                   AND request.arguments_text::jsonb = jsonb_build_object(
                        'content', stored_content,
                        'peer_session_id', CASE stored_direction
                            WHEN 'parent_to_child' THEN relation_child::text
                            WHEN 'child_to_parent' THEN relation_parent::text
                        END
                   )
                   AND attempt.state_kind = 'terminal'
                   AND attempt.terminal_disposition_kind = 'completed'
                   AND attempt.effect_class = 'external_effect'
                   AND attempt.result_content_kind = 'text'
                   AND attempt.result_text::jsonb = jsonb_build_object(
                        'result', 'session_message_sent',
                        'tool_request_id', request.request_id::text,
                        'message_id', message.message_id::text,
                        'direction', message.direction,
                        'ordinal', message.event_ordinal,
                        'delivery_sequence', delivery.delivery_sequence
                   )
            )
            OR (stored_direction = 'parent_to_child'
                AND NEW.provenance_session_id <> relation_parent)
            OR (stored_direction = 'child_to_parent'
                AND NEW.provenance_session_id <> relation_child) THEN
            RAISE EXCEPTION 'message direction does not match delegation provenance'
                USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
        END IF;
    ELSIF NEW.event_kind = 'outcome_recorded' THEN
        IF NEW.provenance_kind = 'child_turn' AND NOT EXISTS (
            SELECT 1 FROM session_delegation_initial_task AS task
             WHERE task.spawning_tool_request_id = NEW.spawning_tool_request_id
               AND task.child_session_id = relation_child
               AND task.turn_id = NEW.provenance_turn_id
        ) THEN
            RAISE EXCEPTION 'child outcome does not name the delegated initial task turn'
                USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
        END IF;
        IF NEW.reason_kind = 'child_completed' THEN
            IF NEW.outcome_kind <> 'result_returned'
                OR NEW.provenance_kind <> 'child_turn'
                OR NEW.provenance_session_id <> relation_child
                OR NOT EXISTS (
                    SELECT 1 FROM turn_lifecycle AS lifecycle
                     WHERE lifecycle.turn_id = NEW.provenance_turn_id
                       AND lifecycle.session_id = relation_child
                       AND lifecycle.state_kind = 'terminal'
                       AND lifecycle.terminal_disposition_kind = 'completed'
                )
                OR NOT EXISTS (
                    SELECT 1 FROM session_child_result AS result
                     WHERE result.spawning_tool_request_id = NEW.spawning_tool_request_id
                       AND result.event_ordinal = NEW.event_ordinal
                       AND result.outcome_kind = 'result_returned'
                       AND result.content_text = (
                            SELECT string_agg(
                                entry.assistant_text_value, ''
                                ORDER BY member.member_position
                            )
                              FROM turn_lifecycle AS lifecycle
                              JOIN context_frontier_member AS member
                                ON member.owning_session_id = lifecycle.session_id
                               AND member.context_frontier_id = lifecycle.terminal_frontier_id
                              JOIN semantic_transcript_entry AS entry
                                ON entry.source_session_id = member.source_session_id
                               AND entry.semantic_entry_id = member.semantic_entry_id
                             WHERE lifecycle.turn_id = NEW.provenance_turn_id
                               AND lifecycle.session_id = relation_child
                               AND entry.payload_kind = 'assistant_text'
                               AND entry.producing_model_call_id =
                                   lifecycle.terminal_model_call_id
                       )
                ) THEN
                RAISE EXCEPTION 'child completion has invalid provenance or outcome'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
        ELSIF NEW.reason_kind = 'child_execution_failed' THEN
            IF NEW.outcome_kind <> 'child_failed'
                OR NEW.provenance_kind <> 'child_turn'
                OR NEW.provenance_session_id <> relation_child
                OR NOT EXISTS (
                    SELECT 1 FROM turn_lifecycle
                     WHERE turn_id = NEW.provenance_turn_id
                       AND session_id = relation_child
                       AND state_kind = 'terminal'
                       AND terminal_disposition_kind IN ('failed', 'refused')
                ) THEN
                RAISE EXCEPTION 'child failure has invalid provenance or outcome'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
        ELSIF NEW.reason_kind = 'child_result_unavailable' THEN
            IF NEW.outcome_kind <> 'child_failed'
                OR NEW.provenance_kind <> 'child_turn'
                OR NEW.provenance_session_id <> relation_child
                OR NOT EXISTS (
                    SELECT 1 FROM turn_lifecycle AS lifecycle
                     WHERE lifecycle.turn_id = NEW.provenance_turn_id
                       AND lifecycle.session_id = relation_child
                       AND lifecycle.state_kind = 'terminal'
                       AND (
                            (
                            lifecycle.terminal_disposition_kind = 'reconciliation_required'
                            AND EXISTS (
                                SELECT 1
                                  FROM automatic_reconciliation AS recovery
                                 WHERE recovery.turn_id = lifecycle.turn_id
                                   AND recovery.session_id = lifecycle.session_id
                                   AND recovery.model_call_id = lifecycle.terminal_model_call_id
                                   AND recovery.state_kind = 'reconciled'
                            )
                            )
                            OR (
                                lifecycle.terminal_disposition_kind = 'completed'
                                AND ((
                            SELECT octet_length(string_agg(
                                entry.assistant_text_value, ''
                                ORDER BY member.member_position
                            ))
                              FROM context_frontier_member AS member
                              JOIN semantic_transcript_entry AS entry
                                ON entry.source_session_id = member.source_session_id
                               AND entry.semantic_entry_id = member.semantic_entry_id
                             WHERE member.owning_session_id = lifecycle.session_id
                               AND member.context_frontier_id = lifecycle.terminal_frontier_id
                               AND entry.payload_kind = 'assistant_text'
                               AND entry.producing_model_call_id =
                                   lifecycle.terminal_model_call_id
                       ) IS NULL OR (
                            SELECT octet_length(string_agg(
                                entry.assistant_text_value, ''
                                ORDER BY member.member_position
                            ))
                              FROM context_frontier_member AS member
                              JOIN semantic_transcript_entry AS entry
                                ON entry.source_session_id = member.source_session_id
                               AND entry.semantic_entry_id = member.semantic_entry_id
                             WHERE member.owning_session_id = lifecycle.session_id
                               AND member.context_frontier_id = lifecycle.terminal_frontier_id
                               AND entry.payload_kind = 'assistant_text'
                               AND entry.producing_model_call_id =
                                   lifecycle.terminal_model_call_id
                       ) > 1048576)
                            )
                       )
                ) THEN
                RAISE EXCEPTION 'unavailable child result has invalid terminal evidence'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
        ELSIF NEW.reason_kind = 'child_cancelled' THEN
            IF NEW.outcome_kind <> 'child_cancelled'
                OR NEW.provenance_kind <> 'child_turn'
                OR NEW.provenance_session_id <> relation_child
                OR NOT EXISTS (
                    SELECT 1 FROM turn_lifecycle
                     WHERE turn_id = NEW.provenance_turn_id
                       AND session_id = relation_child
                       AND state_kind = 'terminal'
                       AND terminal_disposition_kind = 'cancelled'
                ) THEN
                RAISE EXCEPTION 'child cancellation has invalid terminal evidence'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
        ELSIF NEW.reason_kind IN (
            'parent_stopped_parent_and_descendants',
            'parent_cancelled_parent_and_descendants'
        ) THEN
            IF NEW.provenance_kind NOT IN (
                    'parent_turn_command', 'parent_goal_command'
                )
                OR NEW.provenance_session_id <> relation_parent
                OR NOT EXISTS (
                    SELECT 1 FROM session_delegation_parent_termination AS authority
                     WHERE authority.spawning_tool_request_id =
                            NEW.spawning_tool_request_id
                       AND authority.root_command_id = NEW.provenance_command_id
                       AND authority.parent_session_id = relation_parent
                       AND authority.command_source_kind = CASE NEW.provenance_kind
                            WHEN 'parent_turn_command' THEN 'turn_command'
                            WHEN 'parent_goal_command' THEN 'goal_command'
                       END
                       AND authority.parent_turn_id IS NOT DISTINCT FROM
                            NEW.provenance_turn_id
                       AND authority.parent_goal_generation IS NOT DISTINCT FROM
                            NEW.provenance_goal_generation
                       AND authority.termination_kind = CASE NEW.reason_kind
                            WHEN 'parent_stopped_parent_and_descendants' THEN 'stopped'
                            WHEN 'parent_cancelled_parent_and_descendants' THEN 'cancelled'
                       END
                ) THEN
                RAISE EXCEPTION 'parent disposition has invalid provenance'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
            IF NEW.outcome_kind = 'already_terminal' AND NOT EXISTS (
                SELECT 1 FROM session_child_result AS prior
                 WHERE prior.spawning_tool_request_id = NEW.spawning_tool_request_id
                   AND prior.event_ordinal < NEW.event_ordinal
            ) THEN
                RAISE EXCEPTION 'already-terminal disposition lacks its prior child result'
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'session_delegation_event_semantics';
            ELSIF NEW.outcome_kind = 'already_terminal' THEN
                NULL;
            ELSIF relation_policy = 'background' THEN
                expected_outcome := 'continue_running';
            ELSIF NEW.reason_kind = 'parent_stopped_parent_and_descendants' THEN
                expected_outcome := CASE stopped_action
                    WHEN 'keep_running' THEN 'continue_running'
                    WHEN 'stop' THEN 'child_stopped'
                    WHEN 'cancel' THEN 'child_cancelled' END;
            ELSE
                expected_outcome := CASE cancelled_action
                    WHEN 'keep_running' THEN 'continue_running'
                    WHEN 'stop' THEN 'child_stopped'
                    WHEN 'cancel' THEN 'child_cancelled' END;
            END IF;
            IF NEW.outcome_kind <> 'already_terminal'
                AND NEW.outcome_kind <> expected_outcome THEN
                RAISE EXCEPTION 'parent disposition contradicts relationship policy'
                    USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
            IF NEW.outcome_kind IN ('child_stopped', 'child_cancelled')
                AND NOT EXISTS (
                    SELECT 1
                      FROM session_delegation_initial_task AS task
                      JOIN turn_lifecycle AS lifecycle
                        ON lifecycle.turn_id = task.turn_id
                       AND lifecycle.session_id = task.child_session_id
                       AND lifecycle.state_kind = 'terminal'
                       AND lifecycle.terminal_disposition_kind = 'cancelled'
                      JOIN semantic_transcript_entry AS marker
                        ON marker.source_session_id = lifecycle.session_id
                       AND marker.payload_kind = 'turn_cancelled'
                       AND marker.cancelled_turn_id = lifecycle.turn_id
                      JOIN context_frontier AS frontier
                        ON frontier.owning_session_id = lifecycle.session_id
                       AND frontier.context_frontier_id =
                            lifecycle.terminal_frontier_id
                      JOIN context_frontier_member AS terminal_member
                        ON terminal_member.owning_session_id =
                            frontier.owning_session_id
                       AND terminal_member.context_frontier_id =
                            frontier.context_frontier_id
                       AND terminal_member.member_position = frontier.member_count
                       AND terminal_member.source_session_id =
                            marker.source_session_id
                       AND terminal_member.semantic_entry_id =
                            marker.semantic_entry_id
                      JOIN turn_cancelled_outbox_event AS cancellation
                        ON cancellation.session_id = lifecycle.session_id
                       AND cancellation.turn_id = lifecycle.turn_id
                       AND cancellation.cancellation_entry_id =
                            marker.semantic_entry_id
                       AND cancellation.terminal_frontier_id =
                            lifecycle.terminal_frontier_id
                     WHERE task.spawning_tool_request_id =
                            NEW.spawning_tool_request_id
                       AND task.child_session_id = relation_child
                )
                AND NOT EXISTS (
                    SELECT 1
                      FROM session_delegation_logical_terminal AS terminal
                     WHERE terminal.spawning_tool_request_id =
                            NEW.spawning_tool_request_id
                       AND terminal.child_session_id = relation_child
                       AND terminal.root_command_id = NEW.provenance_command_id
                       AND terminal.disposition_kind = CASE NEW.outcome_kind
                            WHEN 'child_stopped' THEN 'stopped'
                            WHEN 'child_cancelled' THEN 'cancelled'
                       END
                ) THEN
                RAISE EXCEPTION 'parent disposition lacks exact child terminal evidence'
                    USING ERRCODE = '23514',
                        CONSTRAINT = 'session_delegation_event_semantics';
            END IF;
        ELSE
            RAISE EXCEPTION 'outcome reason is not a delegation descendant event'
                USING ERRCODE = '23514', CONSTRAINT = 'session_delegation_event_semantics';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_message_delivery(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_message_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (SELECT count(*) FROM session_message_delivery
         WHERE message_id = NEW.message_id
           AND spawning_tool_request_id = NEW.spawning_tool_request_id) <> 1 THEN
        RAISE EXCEPTION 'session message requires exactly one pending delivery'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_message_delivery_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_message_delivery_recipient(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_message_delivery_recipient() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_message AS message
          JOIN session_delegation AS relation
            ON relation.spawning_tool_request_id = message.spawning_tool_request_id
         WHERE message.message_id = NEW.message_id
           AND message.spawning_tool_request_id = NEW.spawning_tool_request_id
           AND NEW.recipient_session_id = CASE message.direction
                WHEN 'parent_to_child' THEN relation.child_session_id
                WHEN 'child_to_parent' THEN relation.parent_session_id
           END
    ) THEN
        RAISE EXCEPTION 'message delivery names the wrong recipient'
            USING ERRCODE = '23514',
                CONSTRAINT = 'session_message_delivery_recipient';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_metadata_installation_is_current(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_metadata_installation_is_current() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_metadata
         WHERE session_id = NEW.session_id
           AND source_command_id = NEW.source_command_id
    ) THEN
        RAISE EXCEPTION
            'session metadata installation is not current for session %',
            NEW.session_id
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_session_metadata_matches_receipt(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_metadata_matches_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_session_id uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        checked_session_id := OLD.session_id;
    ELSE
        checked_session_id := NEW.session_id;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM session_metadata AS current
          LEFT JOIN replace_session_metadata_command AS receipt
            ON receipt.command_id = current.source_command_id
           AND receipt.result_applied_session_id = current.session_id
         WHERE current.session_id = checked_session_id
           AND (
                receipt.command_id IS NULL
                OR receipt.result_kind <> 'applied'
                OR current.title IS DISTINCT FROM receipt.replacement_title
                OR current.archived IS DISTINCT FROM receipt.replacement_archived
                OR current.updated_at IS DISTINCT FROM receipt.result_updated_at
                OR current.actor_kind IS DISTINCT FROM receipt.result_actor_kind
                OR current.actor_turn_id
                    IS DISTINCT FROM receipt.result_actor_turn_id
                OR current.actor_tool_request_id
                    IS DISTINCT FROM receipt.result_actor_tool_request_id
                OR EXISTS (
                    SELECT current_tag.tag
                      FROM session_metadata_tag AS current_tag
                     WHERE current_tag.session_id = current.session_id
                    EXCEPT
                    SELECT receipt_tag.tag
                      FROM replace_session_metadata_command_tag AS receipt_tag
                     WHERE receipt_tag.command_id = receipt.command_id
                )
                OR EXISTS (
                    SELECT receipt_tag.tag
                      FROM replace_session_metadata_command_tag AS receipt_tag
                     WHERE receipt_tag.command_id = receipt.command_id
                    EXCEPT
                    SELECT current_tag.tag
                      FROM session_metadata_tag AS current_tag
                     WHERE current_tag.session_id = current.session_id
                )
                OR EXISTS (
                    SELECT
                        current_attribute.attribute_key,
                        current_attribute.attribute_value
                      FROM session_metadata_attribute AS current_attribute
                     WHERE current_attribute.session_id = current.session_id
                    EXCEPT
                    SELECT
                        receipt_attribute.attribute_key,
                        receipt_attribute.attribute_value
                      FROM replace_session_metadata_command_attribute
                        AS receipt_attribute
                     WHERE receipt_attribute.command_id = receipt.command_id
                )
                OR EXISTS (
                    SELECT
                        receipt_attribute.attribute_key,
                        receipt_attribute.attribute_value
                      FROM replace_session_metadata_command_attribute
                        AS receipt_attribute
                     WHERE receipt_attribute.command_id = receipt.command_id
                    EXCEPT
                    SELECT
                        current_attribute.attribute_key,
                        current_attribute.attribute_value
                      FROM session_metadata_attribute AS current_attribute
                     WHERE current_attribute.session_id = current.session_id
                )
           )
    ) THEN
        RAISE EXCEPTION
            'current session metadata does not match its source receipt'
            USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: require_session_pending_delivery_satellite(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_pending_delivery_satellite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE satellite_count bigint;
BEGIN
    SELECT CASE NEW.delivery_kind
        WHEN 'message' THEN (SELECT count(*) FROM session_message_delivery
            WHERE recipient_session_id = NEW.recipient_session_id
              AND delivery_sequence = NEW.delivery_sequence)
        WHEN 'background_result' THEN (SELECT count(*) FROM session_child_result_delivery
            WHERE parent_session_id = NEW.recipient_session_id
              AND delivery_sequence = NEW.delivery_sequence)
    END INTO satellite_count;
    IF satellite_count <> 1 THEN
        RAISE EXCEPTION 'pending delivery requires exactly one typed satellite'
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_pending_delivery_satellite';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_session_placement(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_session_placement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM session_current_placement AS placement_head
          JOIN session_placement_event AS placement_event
            ON placement_event.session_id = placement_head.session_id
           AND placement_event.version = placement_head.current_version
         WHERE placement_head.session_id = NEW.session_id
    ) THEN
        RAISE EXCEPTION 'session % requires a complete current placement', NEW.session_id
            USING ERRCODE = '23503',
                CONSTRAINT = 'session_requires_placement';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_single_tool_result(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_single_tool_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_request_id uuid;
    new_request_id uuid;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        old_request_id := OLD.tool_result_request_id;
        IF old_request_id IS NULL AND OLD.tool_result_attempt_id IS NOT NULL THEN
            SELECT request_id
              INTO old_request_id
              FROM tool_attempt
             WHERE attempt_id = OLD.tool_result_attempt_id;
        END IF;
        PERFORM assert_tool_request_single_result(old_request_id);
    END IF;
    IF TG_OP <> 'DELETE' THEN
        new_request_id := NEW.tool_result_request_id;
        IF new_request_id IS NULL AND NEW.tool_result_attempt_id IS NOT NULL THEN
            SELECT request_id
              INTO new_request_id
              FROM tool_attempt
             WHERE attempt_id = NEW.tool_result_attempt_id;
        END IF;
        IF new_request_id IS DISTINCT FROM old_request_id THEN
            PERFORM assert_tool_request_single_result(new_request_id);
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_submit_input_command_parts(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_submit_input_command_parts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE checked_command uuid;
BEGIN
    checked_command := CASE WHEN TG_TABLE_NAME = 'submit_input_command'
        THEN NEW.command_id ELSE COALESCE(NEW.command_id, OLD.command_id) END;
    IF NOT submit_input_command_parts_are_valid(checked_command) THEN
        RAISE EXCEPTION 'submit-input command has invalid ordered content parts'
            USING ERRCODE = '23514',
                CONSTRAINT = 'submit_input_command_content_parts_valid';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_submit_input_legacy_effect_correlation(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_submit_input_legacy_effect_correlation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matching_records bigint;
BEGIN
    IF NEW.result_kind = 'applied' AND NEW.result_turn_id IS NOT NULL THEN
        SELECT count(*)
          INTO matching_records
          FROM accepted_input AS accepted
          JOIN queued_input_origin AS queued
            ON queued.accepted_input_id = accepted.accepted_input_id
           AND queued.session_id = accepted.session_id
           AND queued.acceptance_position = accepted.acceptance_position
           AND queued.turn_id = accepted.origin_turn_id
          JOIN session_defaults_version AS defaults
            ON defaults.session_id = queued.session_id
           AND defaults.version = queued.defaults_version
         WHERE accepted.accepting_command_id = NEW.command_id
           AND accepted.accepted_input_id = NEW.result_accepted_input_id
           AND accepted.session_id = NEW.result_session_id
           AND accepted_input_parts_match_command(accepted.accepted_input_id)
           AND accepted.delivery_kind = NEW.delivery_kind
           AND accepted.expected_active_turn_id
               IS NOT DISTINCT FROM NEW.expected_active_turn_id
           AND accepted.expected_defaults_version = NEW.expected_defaults_version
           AND accepted.model_override_kind = NEW.model_override_kind
           AND accepted.replacement_model_kind
               IS NOT DISTINCT FROM NEW.replacement_model_kind
           AND accepted.replacement_direct_model_selection_id
               IS NOT DISTINCT FROM NEW.replacement_direct_model_selection_id
           AND accepted.replacement_model_alias_id
               IS NOT DISTINCT FROM NEW.replacement_model_alias_id
           AND accepted.disposition_kind = 'origin_of'
           AND accepted.origin_turn_id = NEW.result_turn_id
           AND queued.priority_kind = 'ordinary'
           AND queued.defaults_version = NEW.expected_defaults_version
           AND (
               (
                   NEW.model_override_kind = 'use_session_default'
                   AND queued.requested_model_kind = defaults.model_selection_kind
                   AND queued.requested_direct_model_selection_id
                       IS NOT DISTINCT FROM defaults.direct_model_selection_id
                   AND queued.requested_model_alias_id
                       IS NOT DISTINCT FROM defaults.model_alias_id
               )
               OR
               (
                   NEW.model_override_kind = 'replace_with'
                   AND queued.requested_model_kind = NEW.replacement_model_kind
                   AND queued.requested_direct_model_selection_id
                       IS NOT DISTINCT FROM
                           NEW.replacement_direct_model_selection_id
                   AND queued.requested_model_alias_id
                       IS NOT DISTINCT FROM NEW.replacement_model_alias_id
               )
           )
           AND (
               (
                   queued.requested_model_kind = 'direct'
                   AND queued.frozen_model_kind = 'direct'
                   AND queued.frozen_direct_model_selection_id
                       = queued.requested_direct_model_selection_id
               )
               OR
               (
                   queued.requested_model_kind = 'alias'
                   AND queued.frozen_model_kind = 'frozen_alias'
                   AND queued.frozen_model_alias_id = queued.requested_model_alias_id
               )
           )
           AND queued.model_parameters = 'provider_defaults'
           AND queued.known_provider_failure_retry = 'disabled'
           AND queued.model_fallback = 'disabled';
    ELSIF NEW.result_kind = 'applied' THEN
        SELECT count(*)
          INTO matching_records
          FROM accepted_input AS accepted
         WHERE accepted.accepting_command_id = NEW.command_id
           AND accepted.accepted_input_id = NEW.result_accepted_input_id
           AND accepted.session_id = NEW.result_session_id
           AND accepted_input_parts_match_command(accepted.accepted_input_id)
           AND accepted.delivery_kind = 'next_safe_point'
           AND accepted.delivery_kind = NEW.delivery_kind
           AND accepted.expected_active_turn_id = NEW.expected_active_turn_id
           AND accepted.expected_defaults_version IS NULL
           AND accepted.model_override_kind IS NULL
           AND accepted.replacement_model_kind IS NULL
           AND accepted.replacement_direct_model_selection_id IS NULL
           AND accepted.replacement_model_alias_id IS NULL
           AND accepted.disposition_kind = 'pending_steering'
           AND accepted.origin_turn_id IS NULL
           AND accepted.expected_active_turn_id = NEW.result_actual_active_turn_id
           AND NOT EXISTS (
               SELECT 1
                 FROM queued_input_origin
                WHERE accepted_input_id = accepted.accepted_input_id
           );
    ELSE
        SELECT count(*)
          INTO matching_records
          FROM accepted_input
         WHERE accepting_command_id = NEW.command_id;

        IF matching_records = 0
           AND NEW.rejection_kind = 'unknown_model_alias'
        THEN
            SELECT count(*)
              INTO matching_records
              FROM session_defaults_version AS defaults
             WHERE defaults.session_id = NEW.result_session_id
               AND defaults.version = NEW.result_selected_defaults_version
               AND (
                   (
                       NEW.model_override_kind = 'use_session_default'
                       AND defaults.model_selection_kind = 'alias'
                       AND defaults.model_alias_id = NEW.result_unknown_alias_id
                   )
                   OR
                   (
                       NEW.model_override_kind = 'replace_with'
                       AND NEW.replacement_model_kind = 'alias'
                       AND NEW.replacement_model_alias_id = NEW.result_unknown_alias_id
                   )
               );

            IF matching_records <> 1 THEN
                RAISE EXCEPTION
                    'submit-input command % has cross-wired unknown-alias evidence',
                    NEW.command_id
                    USING ERRCODE = '23503';
            END IF;
            matching_records := 0;
        END IF;

        IF matching_records = 0
           AND NEW.rejection_kind IN (
               'session_defaults_version_mismatch',
               'unknown_model_alias',
               'acceptance_position_exhausted'
           )
           AND NEW.delivery_kind IN ('after_current_turn', 'next_safe_point')
        THEN
            SELECT count(*)
              INTO matching_records
              FROM turn_lifecycle AS turn
              JOIN queued_input_origin AS queued
                ON queued.turn_id = turn.turn_id
               AND queued.session_id = turn.session_id
               AND queued.accepted_input_id = turn.origin_accepted_input_id
              JOIN accepted_input AS accepted
                ON accepted.accepted_input_id = queued.accepted_input_id
               AND accepted.session_id = turn.session_id
               AND accepted.origin_turn_id = turn.turn_id
               AND accepted.disposition_kind = 'origin_of'
             WHERE turn.turn_id = NEW.expected_active_turn_id
               AND turn.session_id = NEW.result_session_id;

            IF matching_records <> 1 THEN
                RAISE EXCEPTION
                    'submit-input rejection % has cross-wired source-turn evidence',
                    NEW.command_id
                    USING ERRCODE = '23503',
                        CONSTRAINT =
                            'submit_input_command_rejected_source_origin';
            END IF;
            matching_records := 0;
        END IF;
    END IF;

    IF matching_records <> (
        CASE WHEN NEW.result_kind = 'applied' THEN 1 ELSE 0 END
    ) THEN
        RAISE EXCEPTION
            'submit-input command % has an incomplete or cross-wired terminal effect',
            NEW.command_id
            USING ERRCODE = '23503';
    END IF;

    RETURN NULL;
END;
$$;


--
-- Name: require_terminal_delegated_turn_result(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_terminal_delegated_turn_result() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_turn uuid;
    checked_session uuid;
    spawning_request uuid;
    result_count bigint;
    correlated_result_count bigint;
    automatic_closure boolean;
BEGIN
    checked_turn := COALESCE(NEW.turn_id, OLD.turn_id);
    IF TG_TABLE_NAME = 'turn_lifecycle' THEN
        checked_session := COALESCE(NEW.session_id, OLD.session_id);
    ELSE
        checked_session := COALESCE(
            NEW.child_session_id,
            OLD.child_session_id
        );
    END IF;
    SELECT task.spawning_tool_request_id
      INTO spawning_request
      FROM session_delegation_initial_task AS task
     WHERE task.turn_id = checked_turn
       AND task.child_session_id = checked_session;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT count(*)
      INTO result_count
      FROM session_child_result AS result
     WHERE result.spawning_tool_request_id = spawning_request;
    SELECT count(*)
      INTO correlated_result_count
      FROM session_child_result AS result
      JOIN session_delegation_event AS event
        ON event.spawning_tool_request_id = result.spawning_tool_request_id
       AND event.event_ordinal = result.event_ordinal
     WHERE result.spawning_tool_request_id = spawning_request
       AND result.outcome_kind = 'child_failed'
       AND result.content_text IS NULL
       AND event.event_kind = 'outcome_recorded'
       AND event.outcome_kind = 'child_failed'
       AND event.reason_kind = 'child_result_unavailable'
       AND event.provenance_kind = 'child_turn'
       AND event.provenance_session_id = checked_session
       AND event.provenance_turn_id = checked_turn;
    SELECT EXISTS (
        SELECT 1
          FROM automatic_reconciliation AS recovery
          JOIN turn_lifecycle AS lifecycle
            ON lifecycle.turn_id = recovery.turn_id
           AND lifecycle.session_id = recovery.session_id
         WHERE recovery.turn_id = checked_turn
           AND recovery.session_id = checked_session
           AND recovery.state_kind = 'reconciled'
           AND recovery.model_call_id = lifecycle.terminal_model_call_id
           AND lifecycle.state_kind = 'terminal'
           AND lifecycle.terminal_disposition_kind =
                'reconciliation_required'
    ) INTO automatic_closure;
    IF EXISTS (
        SELECT 1 FROM turn_lifecycle AS lifecycle
         WHERE lifecycle.turn_id = checked_turn
           AND lifecycle.session_id = checked_session
           AND lifecycle.state_kind = 'terminal'
           AND lifecycle.terminal_disposition_kind = 'reconciliation_required'
    ) AND (
        result_count <> (CASE WHEN automatic_closure THEN 1 ELSE 0 END)
        OR correlated_result_count <>
            (CASE WHEN automatic_closure THEN 1 ELSE 0 END)
    ) THEN
        RAISE EXCEPTION
            'reconciliation-required delegated child result cardinality changed'
            USING ERRCODE = '23503',
                CONSTRAINT = 'reconciling_delegated_turn_result_cardinality';
    ELSIF EXISTS (
        SELECT 1 FROM turn_lifecycle AS lifecycle
         WHERE lifecycle.turn_id = checked_turn
           AND lifecycle.session_id = checked_session
           AND lifecycle.state_kind = 'terminal'
           AND lifecycle.terminal_disposition_kind <> 'reconciliation_required'
    ) AND result_count <> 1 THEN
        RAISE EXCEPTION
            'deliverably terminal delegated child turn requires exactly one typed result'
            USING ERRCODE = '23503',
                CONSTRAINT = 'terminal_delegated_turn_result_required';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_tool_approval_decision_authority(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_tool_approval_decision_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matched bigint;
BEGIN
    PERFORM 1
       FROM tool_request
      WHERE request_id = NEW.request_id
        FOR UPDATE;
    IF EXISTS (
        SELECT 1
          FROM tool_approval_judge_model_call AS judge
         WHERE judge.request_id = NEW.request_id
           AND judge.state_kind <> 'terminal'
    ) THEN
        RAISE EXCEPTION 'approval decision races an unfinished judge call'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'tool_approval_decision_requires_terminal_judge';
    END IF;
    IF NEW.decision_source = 'runtime_safety' THEN
        SELECT count(*) INTO matched
          FROM tool_request
         WHERE request_id = NEW.request_id
           AND approval_posture = 'auto'
           AND arguments_kind = 'json'
           AND arguments_text = '{"redacted":"[redacted]"}';
        IF matched <> 1 THEN
            RAISE EXCEPTION 'runtime safety denial lacks suppressed arguments'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'tool_approval_runtime_safety_requires_suppressed_arguments';
        END IF;
        RETURN NULL;
    END IF;
    IF NEW.decision_source IN ('policy_auto', 'session_blanket') THEN
        SELECT count(*) INTO matched
          FROM tool_request
         WHERE request_id = NEW.request_id
           AND approval_posture = 'auto';
        IF matched <> 1 THEN
            RAISE EXCEPTION 'automatic decision exceeds frozen posture'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'tool_approval_automatic_requires_auto_posture';
        END IF;
        RETURN NULL;
    END IF;
    IF NEW.decision_source = 'user_override' THEN
        SELECT count(*) INTO matched
          FROM tool_request AS request
          JOIN tool_approval_user_override AS recorded
            ON recorded.denied_request_id = NEW.override_denied_request_id
          JOIN model_call_user_override AS frozen
            ON frozen.model_call_id = request.producing_model_call_id
           AND frozen.denied_request_id = recorded.denied_request_id
          JOIN tool_request AS denied_request
            ON denied_request.request_id = recorded.denied_request_id
         WHERE request.request_id = NEW.request_id
           AND request.approval_posture = 'delegated'
           AND recorded.session_id = request.session_id
           AND denied_request.tool_name = request.tool_name
           AND denied_request.arguments_kind = request.arguments_kind
           AND denied_request.arguments_text = request.arguments_text;
        IF matched <> 1 THEN
            RAISE EXCEPTION
                'user override consumption lacks a recorded override for a delegated request'
                USING ERRCODE = '23514',
                      CONSTRAINT =
                          'tool_approval_user_override_requires_recorded_override';
        END IF;
        RETURN NULL;
    END IF;
    IF NEW.decision_source = 'user_command' THEN
        SELECT count(*) INTO matched
          FROM tool_request AS request
         WHERE request.request_id = NEW.request_id
           AND (
                request.approval_posture = 'human'
                OR (
                    request.approval_posture = 'delegated'
                    AND EXISTS (
                        SELECT 1
                          FROM tool_approval_judge_model_call AS judge
                         WHERE judge.request_id = request.request_id
                           AND judge.state_kind = 'terminal'
                           AND (
                                (
                                    judge.terminal_disposition_kind = 'completed'
                                    AND judge.recommendation_kind =
                                        'escalate_to_human'
                                )
                                OR judge.terminal_disposition_kind IN (
                                    'known_failed', 'refused', 'cancelled',
                                    'ambiguous'
                                )
                           )
                    )
                )
           );
        IF matched <> 1 THEN
            RAISE EXCEPTION 'user decision lacks human approval authority'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'tool_approval_user_requires_human_authority';
        END IF;
        RETURN NULL;
    END IF;
    IF NEW.decision_source <> 'delegate' THEN
        RETURN NULL;
    END IF;
    SELECT count(*) INTO matched
      FROM tool_request AS request
      JOIN tool_approval_judge_model_call AS judge
        ON judge.request_id = request.request_id
     WHERE request.request_id = NEW.request_id
       AND request.approval_posture = 'delegated'
       AND judge.model_call_id = NEW.delegate_model_call_id
       AND judge.direct_model_selection_id = NEW.delegate_model_selection_id
       AND judge.state_kind = 'terminal'
       AND judge.terminal_disposition_kind = 'completed'
       AND judge.recommendation_kind = NEW.decision_kind
       AND judge.rationale = NEW.rationale
       AND NOT EXISTS (
            SELECT 1 FROM tool_request AS earlier
            LEFT JOIN tool_approval_decision AS earlier_decision
              ON earlier_decision.request_id = earlier.request_id
           WHERE earlier.producing_model_call_id = request.producing_model_call_id
             AND earlier.request_ordinal < request.request_ordinal
             AND earlier_decision.request_id IS NULL
       );
    IF matched <> 1 THEN
        RAISE EXCEPTION 'delegate decision lacks matching delegated authority'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'tool_approval_delegate_requires_checked_judge';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_tool_attempt_authorized(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_tool_attempt_authorized() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_tool_attempt_authorized(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.attempt_id ELSE NEW.attempt_id END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_tool_continuation_context_headroom_terminal(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_tool_continuation_context_headroom_terminal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM turn_lifecycle AS lifecycle
          JOIN turn_attempt AS attempt
            ON attempt.turn_attempt_id = NEW.terminal_attempt_id
           AND attempt.turn_id = NEW.turn_id
           AND attempt.session_id = NEW.session_id
         WHERE lifecycle.turn_id = NEW.turn_id
           AND lifecycle.session_id = NEW.session_id
           AND lifecycle.state_kind = 'terminal'
           AND lifecycle.terminal_disposition_kind = 'failed'
           AND lifecycle.terminal_attempt_id = NEW.terminal_attempt_id
           AND lifecycle.terminal_model_call_id IS NULL
           AND attempt.state_kind = 'ended'
           AND attempt.end_variant = 'without_stop'
           AND attempt.end_disposition = 'known_failure'
    ) THEN
        RAISE EXCEPTION 'context-headroom marker requires its exact failed turn'
            USING
                ERRCODE = '23514',
                CONSTRAINT = 'tool_continuation_context_headroom_exact_terminal';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_tool_decision_command_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_tool_decision_command_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'decide_tool_request_command' THEN
        PERFORM assert_tool_decision_command_final_state(NEW.command_id);
    ELSE
        PERFORM assert_tool_decision_command_final_state(NEW.user_command_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_tool_loop_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_tool_loop_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_turn uuid;
    checked_call uuid;
BEGIN
    IF TG_TABLE_NAME = 'tool_round' THEN
        checked_turn := NEW.turn_id;
        checked_call := NEW.producing_model_call_id;
    ELSIF TG_TABLE_NAME = 'tool_request' THEN
        checked_turn := NEW.turn_id;
        checked_call := NEW.producing_model_call_id;
    ELSIF TG_TABLE_NAME = 'tool_attempt' THEN
        checked_turn := CASE WHEN TG_OP = 'DELETE' THEN OLD.turn_id ELSE NEW.turn_id END;
    ELSIF TG_TABLE_NAME = 'tool_approval_decision' THEN
        SELECT turn_id, producing_model_call_id
          INTO checked_turn, checked_call
          FROM tool_request
         WHERE request_id = NEW.request_id;
    END IF;

    IF checked_call IS NOT NULL THEN
        PERFORM assert_tool_round_final_state(checked_call);
    END IF;
    IF checked_turn IS NOT NULL THEN
        PERFORM assert_turn_lifecycle_final_state(checked_turn);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_turn_attempt_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_turn_attempt_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    checked_attempt_id uuid;
    checked_turn_id uuid;
BEGIN
    checked_attempt_id :=
        CASE WHEN TG_OP = 'DELETE' THEN OLD.turn_attempt_id ELSE NEW.turn_attempt_id END;
    checked_turn_id :=
        CASE WHEN TG_OP = 'DELETE' THEN OLD.turn_id ELSE NEW.turn_id END;

    PERFORM assert_turn_attempt_final_state(checked_attempt_id);
    PERFORM assert_turn_lifecycle_final_state(checked_turn_id);
    RETURN NULL;
END;
$$;


--
-- Name: require_turn_child_wait_mode(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_turn_child_wait_mode() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.active_phase_kind = 'awaiting_child' AND NOT EXISTS (
        SELECT 1 FROM session_delegation_wait
         WHERE awaiting_tool_request_id = NEW.child_wait_request_id
           AND parent_turn_id = NEW.turn_id
           AND parent_session_id = NEW.session_id
           AND wait_mode = 'foreground'
    ) THEN
        RAISE EXCEPTION 'child-wait turn phase requires an exact foreground wait'
            USING ERRCODE = '23514',
                CONSTRAINT = 'turn_lifecycle_child_wait_mode';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_turn_delegation_runtime_terminal_proof(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_turn_delegation_runtime_terminal_proof() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.delegation_runtime_terminal AND NOT EXISTS (
        SELECT 1 FROM session_delegation_logical_terminal AS terminal
         WHERE terminal.child_session_id = NEW.session_id
           AND terminal.child_turn_id = NEW.turn_id
    ) THEN
        RAISE EXCEPTION 'released delegation runtime slot lacks terminal proof'
            USING ERRCODE = '23503',
                CONSTRAINT = 'turn_lifecycle_delegation_runtime_terminal_proof';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_turn_lifecycle_final_state(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_turn_lifecycle_final_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM assert_turn_lifecycle_final_state(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.turn_id ELSE NEW.turn_id END
    );
    RETURN NULL;
END;
$$;


--
-- Name: require_turn_runner_recovery_complete(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_turn_runner_recovery_complete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP <> 'DELETE' THEN
        PERFORM assert_turn_runner_recovery_complete(NEW.session_id, NEW.turn_id);
    END IF;
    IF TG_OP <> 'INSERT'
       AND (TG_OP = 'DELETE'
            OR ROW(OLD.session_id, OLD.turn_id) IS DISTINCT FROM
               ROW(NEW.session_id, NEW.turn_id))
    THEN
        PERFORM assert_turn_runner_recovery_complete(OLD.session_id, OLD.turn_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_user_override_authority(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_user_override_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    matched bigint;
BEGIN
    SELECT count(*) INTO matched
      FROM tool_approval_decision AS denial
      JOIN semantic_transcript_entry AS denied_result
        ON denied_result.payload_kind = 'tool_denied'
       AND denied_result.tool_result_request_id = NEW.denied_request_id
     WHERE denial.request_id = NEW.denied_request_id
       AND denial.decision_kind = 'deny'
       AND denial.decision_source = 'delegate'
       AND denial.delegate_model_call_id = NEW.judge_model_call_id;
    IF matched <> 1 THEN
        RAISE EXCEPTION 'user override lacks a terminal delegate denial'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'tool_approval_user_override_requires_terminal_denial';
    END IF;
    SELECT count(*) INTO matched
      FROM override_denied_tool_request_command AS command
     WHERE command.command_id = NEW.command_id
       AND command.result_kind = 'applied'
       AND command.request_id = NEW.denied_request_id
       AND command.session_id = NEW.session_id;
    IF matched <> 1 THEN
        RAISE EXCEPTION 'user override lacks its applied override command'
            USING ERRCODE = '23514',
                  CONSTRAINT =
                      'tool_approval_user_override_requires_applied_command';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: require_web_usage_source_correlation(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION require_web_usage_source_correlation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    identity_kind text;
    projected_identity_kind text;
    source record;
BEGIN
    SELECT call_kind INTO identity_kind
      FROM model_call_identity
     WHERE model_call_id = NEW.model_call_id;
    projected_identity_kind := identity_kind;
    IF projected_identity_kind = 'ordinary' THEN
        projected_identity_kind := 'model_call';
    END IF;
    IF NEW.call_kind IS DISTINCT FROM projected_identity_kind THEN
        RAISE EXCEPTION
            'usage projection call kind % contradicts identity kind %',
            NEW.call_kind, identity_kind
            USING ERRCODE = '23514';
    END IF;
    IF identity_kind = 'ordinary' THEN
        SELECT session_id, turn_id, resolved_provider_model_identity_id,
               bounded_web_usage_profile(credential_reference)
                   AS credential_profile_label,
               usage_provenance_kind, usage_input_includes_cache_tokens,
               usage_input_tokens AS input_tokens,
               usage_output_tokens AS output_tokens,
               usage_cache_creation_input_tokens
                   AS cache_creation_input_tokens,
               usage_cache_read_input_tokens AS cache_read_input_tokens
          INTO source
          FROM model_call
         WHERE model_call_id = NEW.model_call_id
           AND state_kind = 'terminal';
    ELSIF identity_kind = 'approval_judge' THEN
        SELECT session_id, turn_id, resolved_provider_model_identity_id,
               bounded_web_usage_profile(credential_reference)
                   AS credential_profile_label,
               usage_provenance_kind, usage_input_includes_cache_tokens,
               input_tokens, output_tokens,
               cache_creation_input_tokens, cache_read_input_tokens
          INTO source
          FROM tool_approval_judge_model_call
         WHERE model_call_id = NEW.model_call_id
           AND state_kind = 'terminal';
    ELSE
        SELECT session_id, NULL::uuid AS turn_id,
               resolved_provider_model_identity_id,
               bounded_web_usage_profile(credential_reference)
                   AS credential_profile_label,
               'reported' AS usage_provenance_kind,
               usage_input_includes_cache_tokens,
               input_tokens, output_tokens,
               cache_creation_input_tokens, cache_read_input_tokens
          INTO source
          FROM context_compaction_model_call
         WHERE model_call_id = NEW.model_call_id
           AND state_kind = 'terminal';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'usage projection call % has no terminal source record',
            NEW.model_call_id
            USING ERRCODE = '23514';
    END IF;
    IF NEW.session_id IS DISTINCT FROM source.session_id THEN
        RAISE EXCEPTION
            'usage projection session % contradicts source session %',
            NEW.session_id, source.session_id
            USING ERRCODE = '23514';
    END IF;
    IF NEW.turn_id IS DISTINCT FROM source.turn_id THEN
        RAISE EXCEPTION
            'usage projection turn % contradicts source turn %',
            NEW.turn_id, source.turn_id
            USING ERRCODE = '23514';
    END IF;
    IF NEW.resolved_provider_model_identity_id
           IS DISTINCT FROM source.resolved_provider_model_identity_id
       OR NEW.credential_profile_label
           IS DISTINCT FROM source.credential_profile_label
       OR NEW.usage_provenance_kind
           IS DISTINCT FROM source.usage_provenance_kind
       OR NEW.usage_input_includes_cache_tokens
           IS DISTINCT FROM source.usage_input_includes_cache_tokens
       OR NEW.input_tokens IS DISTINCT FROM source.input_tokens
       OR NEW.output_tokens IS DISTINCT FROM source.output_tokens
       OR NEW.cache_creation_input_tokens
           IS DISTINCT FROM source.cache_creation_input_tokens
       OR NEW.cache_read_input_tokens
           IS DISTINCT FROM source.cache_read_input_tokens
    THEN
        RAISE EXCEPTION
            'usage projection evidence for call % contradicts its terminal source record',
            NEW.model_call_id
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reserve_model_call_identity(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION reserve_model_call_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO model_call_identity (model_call_id, call_kind)
    VALUES (NEW.model_call_id, TG_ARGV[0]);
    RETURN NEW;
END;
$$;


--
-- Name: resolve_context_frontier_members(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION resolve_context_frontier_members(requested_owning_session_id uuid, requested_context_frontier_id uuid) RETURNS TABLE(owning_session_id uuid, context_frontier_id uuid, member_position numeric, source_session_id uuid, semantic_entry_id uuid)
    LANGUAGE sql STABLE
    AS $$
    WITH RECURSIVE ancestry (
        owning_session_id,
        context_frontier_id,
        prefix_context_frontier_id
    ) AS (
        SELECT
            frontier.owning_session_id,
            frontier.context_frontier_id,
            frontier.prefix_context_frontier_id
          FROM context_frontier AS frontier
         WHERE frontier.owning_session_id =
                   requested_owning_session_id
           AND frontier.context_frontier_id =
                   requested_context_frontier_id
        UNION
        SELECT
            prefix.owning_session_id,
            prefix.context_frontier_id,
            prefix.prefix_context_frontier_id
          FROM ancestry
          JOIN context_frontier AS prefix
            ON prefix.owning_session_id = ancestry.owning_session_id
           AND prefix.context_frontier_id =
                   ancestry.prefix_context_frontier_id
    )
    SELECT
        requested_owning_session_id,
        requested_context_frontier_id,
        delta.member_position,
        delta.source_session_id,
        delta.semantic_entry_id
      FROM ancestry
      JOIN context_frontier_delta AS delta
        ON delta.owning_session_id = ancestry.owning_session_id
       AND delta.context_frontier_id = ancestry.context_frontier_id
     ORDER BY delta.member_position
$$;


--
-- Name: retain_repo_watch_webhook_payload_until_expired(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION retain_repo_watch_webhook_payload_until_expired() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'repo_watch_webhook_payload is append-only'
            USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM repo_watch_webhook_delivery AS delivery
          JOIN repo_watch_webhook_disposition AS disposition
            ON disposition.hook_id = delivery.hook_id
           AND disposition.delivery_id = delivery.delivery_id
         WHERE delivery.hook_id = OLD.hook_id
           AND delivery.delivery_id = OLD.delivery_id
           AND disposition.recorded_at <= statement_timestamp() - interval '7 days'
    ) THEN
        RAISE EXCEPTION
            'repo-watch webhook payload is not terminal and seven days old'
            USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: retire_configured_git_remote_from_live(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION retire_configured_git_remote_from_live() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM configured_git_remote_live WHERE mint_id = NEW.mint_id;
    RETURN NULL;
END;
$$;


--
-- Name: retire_repo_watch_webhook_pending(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION retire_repo_watch_webhook_pending() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM repo_watch_webhook_pending
     WHERE hook_id = NEW.hook_id
       AND delivery_id = NEW.delivery_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'repo-watch webhook disposition requires its pending row'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: runner_lease_placement_reaches_loss_revision(uuid, numeric, numeric, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION runner_lease_placement_reaches_loss_revision(checked_session_id uuid, leased_event_ordinal numeric, checked_loss_revision numeric, checked_runner_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM runner_session_placement_record AS leased_placement
          JOIN runner_session_placement_record AS loss_placement
            ON loss_placement.session_id = leased_placement.session_id
           AND loss_placement.event_kind = 'runner_lost'
           AND loss_placement.state_kind = 'runner_lost'
           AND loss_placement.lost_runner_id = checked_runner_id
           AND loss_placement.placement_revision = checked_loss_revision
           AND loss_placement.event_ordinal > leased_placement.event_ordinal
         WHERE leased_placement.session_id = checked_session_id
           AND leased_placement.event_ordinal = leased_event_ordinal
           AND leased_placement.state_kind = 'pinned'
           AND leased_placement.pinned_runner_id = checked_runner_id
           AND (
                leased_placement.placement_revision = checked_loss_revision
                OR (
                    leased_placement.placement_revision < checked_loss_revision
                    AND EXISTS (
                        SELECT 1
                          FROM runner_session_placement_record AS successor
                         WHERE successor.session_id = checked_session_id
                           AND successor.event_ordinal > leased_event_ordinal
                           AND successor.event_ordinal < loss_placement.event_ordinal
                    )
                    AND NOT EXISTS (
                        SELECT 1
                          FROM runner_session_placement_record AS successor
                         WHERE successor.session_id = checked_session_id
                           AND successor.event_ordinal > leased_event_ordinal
                           AND successor.event_ordinal < loss_placement.event_ordinal
                           AND successor.event_kind <> 'profile_replaced'
                    )
                )
           )
    );
$$;


--
-- Name: serialize_runner_enrollment_loss_identity(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION serialize_runner_enrollment_loss_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM lock_runner_loss_identity(NEW.runner_id);
    RETURN NEW;
END;
$$;


--
-- Name: serialize_runner_placement_loss_identity(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION serialize_runner_placement_loss_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selected_runner uuid;
BEGIN
    -- This trigger runs immediately before the baseline trigger. It extends
    -- that trigger's existing total order with the absence fence without
    -- duplicating its baseline predicate.
    PERFORM 1
      FROM session_scheduler
     WHERE session_id = NEW.session_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'runner placement lacks its session scheduler'
            USING ERRCODE = '23514';
    END IF;

    selected_runner := COALESCE(
        NEW.pinned_runner_id,
        NEW.selector_runner_id,
        NEW.lost_runner_id
    );
    IF selected_runner IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM lock_runner_loss_identity(selected_runner);
    RETURN NEW;
END;
$$;


--
-- Name: session_plan_event; Type: TABLE; Schema: public
--

CREATE TABLE session_plan_event (
    session_id uuid NOT NULL,
    event_ordinal numeric(20,0) NOT NULL,
    prior_event_ordinal numeric(20,0),
    event_kind text NOT NULL,
    entry_ordinal numeric(20,0) NOT NULL,
    dependency_ordinal numeric(20,0),
    entry_text text,
    entry_status text,
    provenance_turn_id uuid NOT NULL,
    provenance_issuing_turn_attempt_id uuid NOT NULL,
    provenance_request_id uuid NOT NULL,
    provenance_attempt_id uuid NOT NULL,
    provenance_dispatch_generation numeric(20,0) NOT NULL,
    CONSTRAINT session_plan_event_dependency_ordinal_check CHECK (((dependency_ordinal IS NULL) OR ((dependency_ordinal >= (1)::numeric) AND (dependency_ordinal <= '18446744073709551615'::numeric)))),
    CONSTRAINT session_plan_event_entry_ordinal_check CHECK (((entry_ordinal >= (1)::numeric) AND (entry_ordinal <= '18446744073709551615'::numeric))),
    CONSTRAINT session_plan_event_event_ordinal_check CHECK (((event_ordinal >= (1)::numeric) AND (event_ordinal <= '18446744073709551615'::numeric))),
    CONSTRAINT session_plan_event_kind_closed CHECK ((event_kind = ANY (ARRAY['created'::text, 'text_revised'::text, 'status_changed'::text, 'depends_on'::text]))),
    CONSTRAINT session_plan_event_predecessor_shape CHECK ((((event_ordinal = (1)::numeric) AND (prior_event_ordinal IS NULL)) OR ((event_ordinal > (1)::numeric) AND (prior_event_ordinal = (event_ordinal - (1)::numeric))))),
    CONSTRAINT session_plan_event_prior_event_ordinal_check CHECK (((prior_event_ordinal IS NULL) OR ((prior_event_ordinal >= (1)::numeric) AND (prior_event_ordinal <= '18446744073709551615'::numeric)))),
    CONSTRAINT session_plan_event_provenance_dispatch_generation_check CHECK (((provenance_dispatch_generation >= (1)::numeric) AND (provenance_dispatch_generation <= '18446744073709551615'::numeric))),
    CONSTRAINT session_plan_event_shape CHECK ((((event_kind = 'created'::text) AND (entry_ordinal = event_ordinal) AND (dependency_ordinal IS NULL) AND (entry_text IS NOT NULL) AND ((char_length(entry_text) >= 1) AND (char_length(entry_text) <= 4096)) AND (entry_status IS NULL)) OR ((event_kind = 'text_revised'::text) AND (entry_ordinal < event_ordinal) AND (dependency_ordinal IS NULL) AND (entry_text IS NOT NULL) AND ((char_length(entry_text) >= 1) AND (char_length(entry_text) <= 4096)) AND (entry_status IS NULL)) OR ((event_kind = 'status_changed'::text) AND (entry_ordinal < event_ordinal) AND (dependency_ordinal IS NULL) AND (entry_text IS NULL) AND (entry_status IS NOT NULL)) OR ((event_kind = 'depends_on'::text) AND (entry_ordinal < event_ordinal) AND (dependency_ordinal IS NOT NULL) AND (dependency_ordinal < event_ordinal) AND (dependency_ordinal <> entry_ordinal) AND (entry_text IS NULL) AND (entry_status IS NULL)))),
    CONSTRAINT session_plan_event_status_closed CHECK (((entry_status IS NULL) OR (entry_status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'completed'::text, 'abandoned'::text]))))
);


--
-- Name: session_plan_creation_has_valid_shape(session_plan_event); Type: FUNCTION; Schema: public
--

CREATE FUNCTION session_plan_creation_has_valid_shape(candidate session_plan_event) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT candidate.event_kind = 'created'
       AND candidate.entry_ordinal = candidate.event_ordinal
       AND candidate.dependency_ordinal IS NULL
       AND candidate.entry_text IS NOT NULL
       AND char_length(candidate.entry_text) BETWEEN 1 AND 4096
       AND candidate.entry_status IS NULL;
$$;


--
-- Name: session_plan_event_has_authority(session_plan_event); Type: FUNCTION; Schema: public
--

CREATE FUNCTION session_plan_event_has_authority(candidate session_plan_event) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM tool_attempt AS attempt
          JOIN tool_request AS request
            ON request.request_id = attempt.request_id
         WHERE attempt.attempt_id = candidate.provenance_attempt_id
           AND attempt.request_id = candidate.provenance_request_id
           AND attempt.issuing_turn_attempt_id =
                candidate.provenance_issuing_turn_attempt_id
           AND attempt.dispatch_generation =
                candidate.provenance_dispatch_generation
           AND attempt.turn_id = candidate.provenance_turn_id
           AND attempt.session_id = candidate.session_id
           AND attempt.effect_class = 'external_effect'
           AND (
                attempt.state_kind = 'in_flight'
                OR (
                    attempt.state_kind = 'terminal'
                    AND (
                        attempt.terminal_disposition_kind IN (
                            'completed', 'ambiguous'
                        )
                        OR (
                            attempt.terminal_disposition_kind = 'known_failed'
                            AND attempt.error_kind IN (
                                'execution_failed', 'result_too_large'
                            )
                        )
                    )
                )
           )
           AND request.request_id = candidate.provenance_request_id
           AND request.session_id = candidate.session_id
           AND request.turn_id = candidate.provenance_turn_id
           AND request.tool_name = 'plan_write'
           AND request.arguments_kind = 'json'
           AND session_plan_request_arguments_json(
                   request.arguments_kind, request.arguments_text
               ) =
                CASE candidate.event_kind
                    WHEN 'created' THEN jsonb_build_object(
                        'kind', 'create',
                        'text', candidate.entry_text
                    )
                    WHEN 'text_revised' THEN jsonb_build_object(
                        'kind', 'revise',
                        'entry_id', candidate.entry_ordinal,
                        'text', candidate.entry_text
                    )
                    WHEN 'status_changed' THEN jsonb_build_object(
                        'kind', 'set_status',
                        'entry_id', candidate.entry_ordinal,
                        'status', candidate.entry_status
                    )
                    WHEN 'depends_on' THEN jsonb_build_object(
                        'kind', 'depends_on',
                        'entry_id', candidate.entry_ordinal,
                        'dependency_id', candidate.dependency_ordinal
                    )
                END
    );
$$;


--
-- Name: session_plan_event_has_valid_shape(session_plan_event); Type: FUNCTION; Schema: public
--

CREATE FUNCTION session_plan_event_has_valid_shape(candidate session_plan_event) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT coalesce(
        (
            (
                candidate.event_ordinal = 1
                AND candidate.prior_event_ordinal IS NULL
            )
            OR (
                candidate.event_ordinal > 1
                AND candidate.prior_event_ordinal =
                    candidate.event_ordinal - 1
            )
        )
        AND CASE candidate.event_kind
            WHEN 'created' THEN
                candidate.entry_ordinal = candidate.event_ordinal
                AND candidate.dependency_ordinal IS NULL
                AND candidate.entry_text IS NOT NULL
                AND char_length(candidate.entry_text) BETWEEN 1 AND 4096
                AND candidate.entry_status IS NULL
            WHEN 'text_revised' THEN
                candidate.entry_ordinal < candidate.event_ordinal
                AND candidate.dependency_ordinal IS NULL
                AND candidate.entry_text IS NOT NULL
                AND char_length(candidate.entry_text) BETWEEN 1 AND 4096
                AND candidate.entry_status IS NULL
            WHEN 'status_changed' THEN
                candidate.entry_ordinal < candidate.event_ordinal
                AND candidate.dependency_ordinal IS NULL
                AND candidate.entry_text IS NULL
                AND candidate.entry_status IN (
                    'pending', 'in_progress', 'completed', 'abandoned'
                )
            WHEN 'depends_on' THEN
                candidate.entry_ordinal < candidate.event_ordinal
                AND candidate.dependency_ordinal IS NOT NULL
                AND candidate.dependency_ordinal < candidate.event_ordinal
                AND candidate.dependency_ordinal <>
                    candidate.entry_ordinal
                AND candidate.entry_text IS NULL
                AND candidate.entry_status IS NULL
            ELSE FALSE
        END,
        FALSE
    );
$$;


--
-- Name: session_plan_request_arguments_json(text, text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION session_plan_request_arguments_json(arguments_kind text, arguments_text text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    IF arguments_kind IS DISTINCT FROM 'json' OR arguments_text IS NULL THEN
        RETURN NULL;
    END IF;
    BEGIN
        RETURN arguments_text::jsonb;
    EXCEPTION
        -- Every JSONB conversion failure makes the request unsuitable as
        -- append authority, including escaped NUL and numeric overflow.
        WHEN data_exception THEN
            RETURN NULL;
    END;
END;
$$;


--
-- Name: session_system_prompt_digest(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION session_system_prompt_digest(prompt text) RETURNS bytea
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    RETURN COALESCE(sha256(convert_to(prompt, 'UTF8'::name)), '\x'::bytea);


--
-- Name: set_runner_placement_loss_baseline(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION set_runner_placement_loss_baseline() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    selected_runner uuid;
    selected_enrollment uuid;
    current_loss_epoch numeric;
    prior runner_session_placement_record%ROWTYPE;
BEGIN
    IF NEW.loss_fence_enrollment_id IS NOT NULL
       OR NEW.observed_runner_loss_epoch IS NOT NULL
    THEN
        RAISE EXCEPTION 'runner placement loss baseline is adapter-derived'
            USING ERRCODE = '23514';
    END IF;

    -- Placement mutation shares the runner total order with loss propagation:
    -- scheduler, enrollment, connection/loss, then the placement insert.
    PERFORM 1
      FROM session_scheduler
     WHERE session_id = NEW.session_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'runner placement lacks its session scheduler'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.event_ordinal > 1 THEN
        SELECT * INTO prior
          FROM runner_session_placement_record
         WHERE session_id = NEW.session_id
           AND event_ordinal = NEW.event_ordinal - 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'runner placement loss baseline lacks its predecessor'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    selected_runner := COALESCE(
        NEW.pinned_runner_id,
        NEW.selector_runner_id,
        NEW.lost_runner_id
    );
    IF selected_runner IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT enrollment_id
      INTO selected_enrollment
      FROM runner_enrollment
     WHERE runner_id = selected_runner
     FOR SHARE;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    PERFORM 1
      FROM runner_connection_authority_head
     WHERE enrollment_id = selected_enrollment
     FOR SHARE;
    SELECT loss_epoch
      INTO current_loss_epoch
      FROM runner_current_connection_loss
     WHERE enrollment_id = selected_enrollment
     FOR SHARE;

    IF NEW.event_kind IN (
        'runner_lost_before_pin', 'runner_lost', 'abandoned'
    ) THEN
        IF prior.loss_fence_enrollment_id IS NOT NULL
           AND prior.loss_fence_enrollment_id IS DISTINCT FROM
                selected_enrollment
        THEN
            RAISE EXCEPTION
                'runner placement loss changed its enrollment baseline'
                USING ERRCODE = '23514';
        END IF;
        NEW.loss_fence_enrollment_id := prior.loss_fence_enrollment_id;
        NEW.observed_runner_loss_epoch := prior.observed_runner_loss_epoch;
    ELSIF NEW.event_kind = 'pinned'
          AND prior.selector_kind = 'identity'
          AND prior.loss_fence_enrollment_id IS NULL
    THEN
        IF current_loss_epoch IS NOT NULL THEN
            RAISE EXCEPTION
                'runner placement predecessor is fenced by connection loss'
                USING ERRCODE = '23514';
        END IF;
        NEW.loss_fence_enrollment_id := selected_enrollment;
        NEW.observed_runner_loss_epoch := NULL;
    ELSIF NEW.event_kind = 'profile_replaced' OR (
        NEW.event_kind = 'pinned'
        AND prior.selector_kind = 'identity'
    ) THEN
        IF prior.loss_fence_enrollment_id IS DISTINCT FROM selected_enrollment
           OR prior.observed_runner_loss_epoch IS DISTINCT FROM
                current_loss_epoch
        THEN
            RAISE EXCEPTION
                'runner placement predecessor is fenced by connection loss'
                USING ERRCODE = '23514';
        END IF;
        NEW.loss_fence_enrollment_id := prior.loss_fence_enrollment_id;
        NEW.observed_runner_loss_epoch := prior.observed_runner_loss_epoch;
    ELSE
        NEW.loss_fence_enrollment_id := selected_enrollment;
        NEW.observed_runner_loss_epoch := current_loss_epoch;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: stamp_eval_run_recording_transaction(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_eval_run_recording_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.recording_transaction_id := pg_catalog.pg_current_xact_id();
    RETURN NEW;
END;
$$;


--
-- Name: stamp_imported_session_seed_transaction(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_imported_session_seed_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- pg_current_xact_id() deliberately returns the top-level transaction ID
    -- even when this INSERT runs inside a savepoint. Persisting it avoids
    -- confusing the tuple's subtransaction xmin with a previously committed
    -- seed while the rest of the prefix is assembled.
    NEW.creation_transaction_id := pg_current_xact_id();
    RETURN NEW;
END;
$$;


--
-- Name: stamp_repo_watch_cursor_transaction(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_repo_watch_cursor_transaction() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.recording_transaction_id := pg_current_xact_id();
    RETURN NEW;
END;
$$;


--
-- Name: stamp_repo_watch_dispatch_action_target(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_repo_watch_dispatch_action_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT batch.repository, batch.pull_request_number
      INTO NEW.repository, NEW.pull_request_number
      FROM repo_watch_dispatch_batch AS batch
     WHERE batch.dispatch_id = NEW.dispatch_id;
    RETURN NEW;
END;
$$;


--
-- Name: stamp_repo_watch_dispatch_batch_target(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_repo_watch_dispatch_batch_target() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT event.repository, event.pull_request_number
      INTO NEW.repository, NEW.pull_request_number
      FROM repo_watch_event AS event
     WHERE event.event_id = NEW.event_id;
    RETURN NEW;
END;
$$;


--
-- Name: stamp_repo_watch_webhook_projection_delivery(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION stamp_repo_watch_webhook_projection_delivery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT delivery.repository, delivery.received_at
      INTO NEW.repository, NEW.received_at
      FROM repo_watch_webhook_delivery AS delivery
     WHERE delivery.hook_id = NEW.hook_id
       AND delivery.delivery_id = NEW.delivery_id;
    RETURN NEW;
END;
$$;


--
-- Name: submit_input_command_content_parts_json(uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION submit_input_command_content_parts_json(checked_command uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'position', position,
                'part_kind', part_kind,
                'text_value', text_value,
                'blob_digest', CASE
                    WHEN blob_digest IS NULL THEN NULL
                    ELSE 'sha256:' || encode(blob_digest, 'hex')
                END,
                'attachment_kind', attachment_kind,
                'declared_media_type', declared_media_type,
                'display_filename', display_filename
            ) ORDER BY position
        ),
        '[]'::jsonb
    )
      FROM submit_input_command_content_part
     WHERE command_id = checked_command;
$$;


--
-- Name: submit_input_command_parts_are_valid(uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION submit_input_command_parts_are_valid(checked_command uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT count(*) BETWEEN 1 AND 256
       AND min(position) = 0
       AND max(position) = count(*) - 1
       AND COALESCE(sum(octet_length(convert_to(text_value, 'UTF8')))
            FILTER (WHERE part_kind = 'text'), 0) <= 1048576
       AND NOT EXISTS (
            SELECT 1
              FROM submit_input_command_content_part AS current
              JOIN submit_input_command_content_part AS prior
                ON prior.command_id = current.command_id
               AND prior.position + 1 = current.position
             WHERE current.command_id = checked_command
               AND current.part_kind = 'text'
               AND prior.part_kind = 'text')
      FROM submit_input_command_content_part
     WHERE command_id = checked_command;
$$;


--
-- Name: turn_lifecycle_effective_terminal_frontier(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_lifecycle_effective_terminal_frontier(checked_session_id uuid, checked_turn_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
    SELECT CASE lifecycle.state_kind
        WHEN 'terminal' THEN lifecycle.terminal_frontier_id
        ELSE logical_terminal.terminal_frontier_id
    END
      FROM turn_lifecycle AS lifecycle
      LEFT JOIN session_delegation_logical_terminal AS logical_terminal
        ON logical_terminal.child_session_id = lifecycle.session_id
       AND logical_terminal.child_turn_id = lifecycle.turn_id
     WHERE lifecycle.session_id = checked_session_id
       AND lifecycle.turn_id = checked_turn_id
       AND (
            lifecycle.state_kind = 'terminal'
            OR lifecycle.delegation_runtime_terminal
       )
$$;


--
-- Name: turn_lifecycle_origin_member_span(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_lifecycle_origin_member_span(checked_turn_id uuid, checked_session_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        (
            SELECT wake.through_delivery_sequence
                   - wake.first_delivery_sequence + 1
              FROM session_delegation_wake_turn_origin AS wake
             WHERE wake.turn_id = checked_turn_id
               AND wake.recipient_session_id = checked_session_id
        ),
        1
    )
$$;


--
-- Name: turn_lifecycle_origin_semantic_entry(uuid, uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_lifecycle_origin_semantic_entry(checked_turn_id uuid, checked_session_id uuid, checked_origin_input_id uuid) RETURNS TABLE(semantic_entry_id uuid)
    LANGUAGE sql STABLE
    AS $$
    SELECT entry.semantic_entry_id
      FROM turn_lifecycle AS lifecycle
      JOIN semantic_transcript_entry AS entry
        ON entry.source_session_id = lifecycle.session_id
      LEFT JOIN session_delegation_initial_task AS task
        ON task.turn_id = lifecycle.turn_id
       AND task.child_session_id = lifecycle.session_id
       AND task.semantic_entry_id = entry.semantic_entry_id
      LEFT JOIN session_delegation_wake_turn_origin AS wake
        ON wake.turn_id = lifecycle.turn_id
       AND wake.recipient_session_id = lifecycle.session_id
       AND delegation_delivery_semantic_entry(
            wake.recipient_session_id,
            wake.through_delivery_sequence
       ) = entry.semantic_entry_id
     WHERE lifecycle.turn_id = checked_turn_id
       AND lifecycle.session_id = checked_session_id
       AND (
            (lifecycle.origin_kind = 'accepted_input'
                AND entry.payload_kind = 'origin_accepted_input'
                AND entry.origin_accepted_input_id = checked_origin_input_id)
            OR (lifecycle.origin_kind = 'delegation'
                AND lifecycle.state_kind <> 'queued'
                AND (
                    (entry.payload_kind = 'delegated_task'
                        AND task.spawning_tool_request_id =
                            entry.delegated_task_spawning_tool_request_id)
                    OR wake.turn_id IS NOT NULL
                ))
       )
$$;


--
-- Name: turn_origin_effective_model_configuration(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_origin_effective_model_configuration(checked_turn_id uuid, checked_session_id uuid) RETURNS TABLE(defaults_version numeric, direct_selection_id uuid)
    LANGUAGE sql STABLE
    AS $$
    WITH RECURSIVE configuration_chain AS (
        (
            SELECT
                origin.turn_id,
                origin.source_configuration_turn_id,
                origin.defaults_version,
                COALESCE(
                    origin.frozen_direct_model_selection_id,
                    origin.frozen_alias_selected_direct_id
                ) AS direct_selection_id,
                ARRAY[origin.turn_id]::uuid[] AS visited_turn_ids
              FROM queued_input_origin AS origin
             WHERE origin.turn_id = checked_turn_id
               AND origin.session_id = checked_session_id

            UNION ALL

            SELECT
                task.turn_id,
                NULL::uuid AS source_configuration_turn_id,
                task.defaults_version,
                COALESCE(
                    task.frozen_direct_model_selection_id,
                    task.frozen_alias_selected_direct_id
                ),
                ARRAY[task.turn_id]::uuid[] AS visited_turn_ids
              FROM session_delegation_initial_task AS task
             WHERE task.turn_id = checked_turn_id
               AND task.child_session_id = checked_session_id

            UNION ALL

            SELECT
                wake.turn_id,
                NULL::uuid AS source_configuration_turn_id,
                wake.defaults_version,
                COALESCE(
                    wake.frozen_direct_model_selection_id,
                    wake.frozen_alias_selected_direct_id
                ),
                ARRAY[wake.turn_id]::uuid[] AS visited_turn_ids
              FROM session_delegation_wake_turn_origin AS wake
             WHERE wake.turn_id = checked_turn_id
               AND wake.recipient_session_id = checked_session_id
        )

        UNION ALL

        SELECT
            source.turn_id,
            source.source_configuration_turn_id,
            source.defaults_version,
            COALESCE(
                source.frozen_direct_model_selection_id,
                source.frozen_alias_selected_direct_id
            ),
            chain.visited_turn_ids || source.turn_id
          FROM configuration_chain AS chain
          JOIN queued_input_origin AS source
            ON source.turn_id = chain.source_configuration_turn_id
           AND source.session_id = checked_session_id
         WHERE NOT source.turn_id = ANY(chain.visited_turn_ids)
    )
    SELECT chain.defaults_version, chain.direct_selection_id
      FROM configuration_chain AS chain
     WHERE chain.defaults_version IS NOT NULL
       AND chain.direct_selection_id IS NOT NULL
     ORDER BY cardinality(chain.visited_turn_ids) DESC
     LIMIT 1
$$;


--
-- Name: turn_origin_exact_model_configuration(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_origin_exact_model_configuration(checked_turn_id uuid, checked_session_id uuid) RETURNS TABLE(defaults_version numeric, requested_model_kind text, requested_direct_model_selection_id uuid, requested_model_alias_id uuid, frozen_model_kind text, frozen_direct_model_selection_id uuid, frozen_model_alias_id uuid, frozen_alias_selected_direct_id uuid)
    LANGUAGE sql STABLE
    AS $$
    WITH RECURSIVE configuration_chain AS (
        (
            SELECT
                origin.turn_id,
                origin.source_configuration_turn_id,
                origin.defaults_version,
                origin.requested_model_kind,
                origin.requested_direct_model_selection_id,
                origin.requested_model_alias_id,
                origin.frozen_model_kind,
                origin.frozen_direct_model_selection_id,
                origin.frozen_model_alias_id,
                origin.frozen_alias_selected_direct_id,
                ARRAY[origin.turn_id]::uuid[] AS visited_turn_ids
              FROM queued_input_origin AS origin
             WHERE origin.turn_id = checked_turn_id
               AND origin.session_id = checked_session_id

            UNION ALL

            SELECT
                task.turn_id,
                NULL::uuid,
                task.defaults_version,
                task.requested_model_kind,
                task.requested_direct_model_selection_id,
                task.requested_model_alias_id,
                task.frozen_model_kind,
                task.frozen_direct_model_selection_id,
                task.frozen_model_alias_id,
                task.frozen_alias_selected_direct_id,
                ARRAY[task.turn_id]::uuid[]
              FROM session_delegation_initial_task AS task
             WHERE task.turn_id = checked_turn_id
               AND task.child_session_id = checked_session_id

            UNION ALL

            SELECT
                wake.turn_id,
                NULL::uuid,
                wake.defaults_version,
                wake.requested_model_kind,
                wake.requested_direct_model_selection_id,
                wake.requested_model_alias_id,
                wake.frozen_model_kind,
                wake.frozen_direct_model_selection_id,
                wake.frozen_model_alias_id,
                wake.frozen_alias_selected_direct_id,
                ARRAY[wake.turn_id]::uuid[]
              FROM session_delegation_wake_turn_origin AS wake
             WHERE wake.turn_id = checked_turn_id
               AND wake.recipient_session_id = checked_session_id
        )

        UNION ALL

        SELECT
            source.turn_id,
            source.source_configuration_turn_id,
            source.defaults_version,
            source.requested_model_kind,
            source.requested_direct_model_selection_id,
            source.requested_model_alias_id,
            source.frozen_model_kind,
            source.frozen_direct_model_selection_id,
            source.frozen_model_alias_id,
            source.frozen_alias_selected_direct_id,
            chain.visited_turn_ids || source.turn_id
          FROM configuration_chain AS chain
          JOIN queued_input_origin AS source
            ON source.turn_id = chain.source_configuration_turn_id
           AND source.session_id = checked_session_id
         WHERE NOT source.turn_id = ANY(chain.visited_turn_ids)
    )
    SELECT
        chain.defaults_version,
        chain.requested_model_kind,
        chain.requested_direct_model_selection_id,
        chain.requested_model_alias_id,
        chain.frozen_model_kind,
        chain.frozen_direct_model_selection_id,
        chain.frozen_model_alias_id,
        chain.frozen_alias_selected_direct_id
      FROM configuration_chain AS chain
     WHERE chain.defaults_version IS NOT NULL
       AND chain.requested_model_kind IS NOT NULL
       AND chain.frozen_model_kind IS NOT NULL
     ORDER BY cardinality(chain.visited_turn_ids) DESC
     LIMIT 1
$$;


--
-- Name: turn_start_effective_predecessor_frontier(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_start_effective_predecessor_frontier(checked_session uuid, checked_predecessor_frontier uuid) RETURNS TABLE(context_frontier_id uuid, member_count numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH leaf AS MATERIALIZED (
        SELECT candidate.result_frontier_id
          FROM context_compaction AS candidate
         WHERE candidate.session_id = checked_session
           AND NOT EXISTS (
                SELECT 1
                  FROM context_compaction AS successor
                 WHERE successor.session_id = candidate.session_id
                   AND successor.predecessor_compaction_id =
                           candidate.context_compaction_id
           )
    ),
    applicable_leaf AS (
        SELECT leaf.result_frontier_id
          FROM leaf
          JOIN context_frontier AS candidate
            ON candidate.owning_session_id = checked_session
           AND candidate.context_frontier_id = leaf.result_frontier_id
          JOIN context_frontier AS predecessor
            ON predecessor.owning_session_id = checked_session
           AND predecessor.context_frontier_id =
                   checked_predecessor_frontier
         WHERE CASE
                   WHEN candidate.member_count < predecessor.member_count
                   THEN false
                   ELSE context_frontier_preserves_prefix(
                        checked_session,
                        checked_predecessor_frontier,
                        leaf.result_frontier_id
                   )
               END
    )
    SELECT frontier.context_frontier_id, frontier.member_count
      FROM context_frontier AS frontier
     WHERE frontier.owning_session_id = checked_session
       AND frontier.context_frontier_id = COALESCE(
            (SELECT result_frontier_id FROM applicable_leaf),
            checked_predecessor_frontier
       )
$$;


--
-- Name: turn_start_model_identity_boundary_is_valid(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_start_model_identity_boundary_is_valid(checked_turn_id uuid, checked_frontier_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    checked_session uuid;
    checked_defaults_version numeric(20, 0);
    checked_selection uuid;
    boundary_required boolean;
    predecessor_turn uuid;
    predecessor_selection uuid;
    starting_member_count numeric(20, 0);
    boundary_entry_count bigint;
    boundary_member_count bigint;
    boundary_member_position numeric(20, 0);
BEGIN
    SELECT lifecycle.session_id, lifecycle.model_identity_boundary_required
      INTO checked_session, boundary_required
      FROM turn_lifecycle AS lifecycle
     WHERE lifecycle.turn_id = checked_turn_id
       AND (
            (
                lifecycle.origin_kind = 'accepted_input'
                AND EXISTS (
                    SELECT 1
                      FROM queued_input_origin AS origin
                     WHERE origin.turn_id = lifecycle.turn_id
                       AND origin.session_id = lifecycle.session_id
                )
            )
            OR (
                lifecycle.origin_kind = 'delegation'
                AND (
                    EXISTS (
                        SELECT 1
                          FROM session_delegation_initial_task AS task
                         WHERE task.turn_id = lifecycle.turn_id
                           AND task.child_session_id = lifecycle.session_id
                    )
                    OR EXISTS (
                        SELECT 1
                          FROM session_delegation_wake_turn_origin AS wake
                         WHERE wake.turn_id = lifecycle.turn_id
                           AND wake.recipient_session_id = lifecycle.session_id
                    )
                )
            )
       );

    IF NOT FOUND THEN
        RETURN false;
    END IF;

    SELECT
        effective.defaults_version,
        effective.direct_selection_id
      INTO checked_defaults_version, checked_selection
      FROM turn_origin_effective_model_configuration(
               checked_turn_id,
               checked_session
           ) AS effective;

    IF NOT FOUND THEN
        RETURN false;
    END IF;

    predecessor_turn := accepted_input_turn_queue_predecessor(
        checked_session,
        checked_turn_id
    );
    IF predecessor_turn IS NOT NULL THEN
        SELECT effective.direct_selection_id
          INTO predecessor_selection
          FROM turn_origin_effective_model_configuration(
                   predecessor_turn,
                   checked_session
               ) AS effective;
        IF NOT FOUND THEN
            RETURN false;
        END IF;
    END IF;

    SELECT count(*)
      INTO boundary_entry_count
      FROM semantic_transcript_entry AS entry
     WHERE entry.source_session_id = checked_session
       AND entry.payload_kind = 'model_identity_changed'
       AND entry.model_identity_turn_id = checked_turn_id
       AND entry.model_identity_defaults_version = checked_defaults_version
       AND entry.model_identity_direct_selection_id = checked_selection;

    IF NOT boundary_required THEN
        RETURN boundary_entry_count = 0;
    END IF;

    IF predecessor_turn IS NULL
       OR predecessor_selection IS NOT DISTINCT FROM checked_selection
    THEN
        RETURN boundary_entry_count = 0;
    END IF;

    SELECT member_count
      INTO starting_member_count
      FROM context_frontier
     WHERE owning_session_id = checked_session
       AND context_frontier_id = checked_frontier_id;

    SELECT count(*), max(member.member_position)
      INTO boundary_member_count, boundary_member_position
      FROM semantic_transcript_entry AS entry
      JOIN context_frontier_member AS member
        ON member.source_session_id = entry.source_session_id
       AND member.semantic_entry_id = entry.semantic_entry_id
     WHERE entry.source_session_id = checked_session
       AND entry.payload_kind = 'model_identity_changed'
       AND entry.model_identity_turn_id = checked_turn_id
       AND member.owning_session_id = checked_session
       AND member.context_frontier_id = checked_frontier_id;

    RETURN boundary_entry_count = 1
       AND boundary_member_count = 1
       AND boundary_member_position IS NOT DISTINCT FROM
           starting_member_count - 1;
END;
$$;


--
-- Name: turn_start_model_identity_entry_count(uuid, uuid); Type: FUNCTION; Schema: public
--

CREATE FUNCTION turn_start_model_identity_entry_count(checked_turn_id uuid, checked_frontier_id uuid) RETURNS bigint
    LANGUAGE sql STABLE
    AS $$
    SELECT count(*)
      FROM semantic_transcript_entry AS entry
      JOIN context_frontier_member AS member
        ON member.source_session_id = entry.source_session_id
       AND member.semantic_entry_id = entry.semantic_entry_id
     WHERE entry.model_identity_turn_id = checked_turn_id
       AND member.context_frontier_id = checked_frontier_id
       AND member.owning_session_id = entry.source_session_id
$$;


--
-- Name: update_operator_attention_judge_facts(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION update_operator_attention_judge_facts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    old_actionable bigint := 0;
    old_completed bigint := 0;
    old_escalated bigint := 0;
    old_failed bigint := 0;
    new_actionable bigint;
    new_completed bigint;
    new_escalated bigint;
    new_failed bigint;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        old_actionable := (OLD.state_kind <> 'terminal')::integer;
        old_completed := COALESCE((OLD.terminal_disposition_kind = 'completed'
            AND OLD.recommendation_kind <> 'escalate_to_human')::integer, 0);
        old_escalated := COALESCE((OLD.terminal_disposition_kind = 'completed'
            AND OLD.recommendation_kind = 'escalate_to_human')::integer, 0);
        old_failed := COALESCE((OLD.state_kind = 'terminal'
            AND OLD.terminal_disposition_kind <> 'completed')::integer, 0);
    END IF;
    new_actionable := (NEW.state_kind <> 'terminal')::integer;
    new_completed := COALESCE((NEW.terminal_disposition_kind = 'completed'
        AND NEW.recommendation_kind <> 'escalate_to_human')::integer, 0);
    new_escalated := COALESCE((NEW.terminal_disposition_kind = 'completed'
        AND NEW.recommendation_kind = 'escalate_to_human')::integer, 0);
    new_failed := COALESCE((NEW.state_kind = 'terminal'
        AND NEW.terminal_disposition_kind <> 'completed')::integer, 0);

    -- Seed the counter row before applying the deltas, then add them with an
    -- UPDATE. Carrying a delta through the INSERT of an upsert cannot work
    -- here: PostgreSQL validates CHECK constraints against the proposed insert
    -- tuple before the ON CONFLICT arbiter runs, so a transition that retires
    -- an actionable call (delta -1) is rejected by `actionable >= 0` even when
    -- the conflicting row makes the resulting sum non-negative. The seed tuple
    -- is all zeros and so always satisfies the constraints, and the UPDATE
    -- still checks the summed row -- which is the invariant worth holding.
    INSERT INTO operator_attention_judge_facts
        (session_id, actionable, completed, escalated, failed)
    VALUES (NEW.session_id, 0, 0, 0, 0)
    ON CONFLICT (session_id) DO NOTHING;

    UPDATE operator_attention_judge_facts
       SET actionable = actionable + (new_actionable - old_actionable),
           completed = completed + (new_completed - old_completed),
           escalated = escalated + (new_escalated - old_escalated),
           failed = failed + (new_failed - old_failed)
     WHERE session_id = NEW.session_id;
    RETURN NULL;
END;
$$;


--
-- Name: update_session_timeline_work_fact(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION update_session_timeline_work_fact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    pursued boolean;
    turn_generation numeric(20, 0);
    generation_delta integer;
BEGIN
    -- Outbox appends acquire the allocator before this session fact. Taking the
    -- same locks in the same order prevents lifecycle updates from inverting it.
    PERFORM 1 FROM outbox_sequence_state WHERE singleton FOR UPDATE;
    -- The generation this turn belongs to is a primary-key read of `goal_turn`,
    -- and a turn with no goal turn belongs to no generation: it is credited
    -- unconditionally and no goal transition ever moves it, so it contributes
    -- to no per-generation row. `goal_turn` is append-only, so the generation
    -- this reads cannot change under a later transition of the same turn.
    SELECT goal.goal_generation INTO turn_generation
      FROM goal_turn AS goal
     WHERE goal.session_id = NEW.session_id
       AND goal.turn_id = NEW.turn_id;
    IF turn_generation IS NOT NULL THEN
        generation_delta :=
            (NEW.state_kind = 'queued'
             AND NOT NEW.delegation_runtime_terminal)::integer
            - CASE
                WHEN TG_OP = 'UPDATE'
                    THEN (OLD.state_kind = 'queued'
                          AND NOT OLD.delegation_runtime_terminal)::integer
                ELSE 0
              END;
        IF generation_delta <> 0 THEN
            PERFORM apply_goal_generation_queued_delta(
                NEW.session_id, turn_generation, generation_delta
            );
        END IF;
    END IF;
    -- A queued turn is credited only while its goal generation is still
    -- pursued, so the subtraction has to carry the same guard the credit did.
    -- Without it a turn already retired by a goal event -- whose credit the
    -- reconciliation below has removed -- is subtracted a second time when it
    -- later leaves the queue or releases its delegated runtime slot, driving
    -- the count negative and aborting the writing transaction on the fact
    -- table's nonnegative check.
    --
    -- This trigger fires only on `state_kind` and `delegation_runtime_terminal`
    -- and neither changes which generation the session pursues, so a single
    -- evaluation is correct for the old and the new state alike. It has to
    -- happen under the allocator lock: that lock is what serialises this
    -- against a goal event retiring the same generation concurrently, and a
    -- read taken before it could credit a generation the committed goal event
    -- has already retired.
    pursued := goal_turn_generation_is_pursued(NEW.session_id, NEW.turn_id);
    IF TG_OP = 'UPDATE' THEN
        UPDATE session_timeline_fact
           SET active_turn_count = active_turn_count
                   - (OLD.state_kind = 'active' AND NOT OLD.delegation_runtime_terminal)::integer
                   + (NEW.state_kind = 'active' AND NOT NEW.delegation_runtime_terminal)::integer,
               queued_turn_count = queued_turn_count
                   - (OLD.state_kind = 'queued'
                      AND NOT OLD.delegation_runtime_terminal
                      AND pursued)::integer
                   + (NEW.state_kind = 'queued'
                      AND NOT NEW.delegation_runtime_terminal
                      AND pursued)::integer
         WHERE session_id = NEW.session_id;
    ELSE
        UPDATE session_timeline_fact
           SET active_turn_count = active_turn_count
                   + (NEW.state_kind = 'active' AND NOT NEW.delegation_runtime_terminal)::integer,
               queued_turn_count = queued_turn_count
                   + (NEW.state_kind = 'queued'
                      AND NOT NEW.delegation_runtime_terminal
                      AND pursued)::integer
         WHERE session_id = NEW.session_id;
    END IF;
    RETURN NULL;
END
$$;


--
-- Name: valid_tool_json(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION valid_tool_json(value_text text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
BEGIN
    PERFORM value_text::json;
    RETURN true;
EXCEPTION
    WHEN invalid_text_representation THEN
        RETURN false;
END;
$$;


--
-- Name: validate_instruction_discovery_seal(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION validate_instruction_discovery_seal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    root_count bigint;
    root_max_ordinal bigint;
    candidate_count bigint;
    candidate_max_ordinal bigint;
    candidate_source_byte_sum numeric;
    actual_finding_count bigint;
    finding_max_ordinal bigint;
    limit_finding_count bigint;
    limit_finding_max_ordinal bigint;
BEGIN
    SELECT count(*), coalesce(max(root_ordinal), 0)
      INTO root_count, root_max_ordinal
      FROM instruction_discovery_root
     WHERE instruction_discovery_id = NEW.instruction_discovery_id;
    IF root_count <> root_max_ordinal THEN
        RAISE EXCEPTION 'instruction discovery root inventory is not contiguous'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_root_inventory_exact';
    END IF;

    SELECT count(*), coalesce(max(candidate_ordinal), 0)
      INTO candidate_count, candidate_max_ordinal
      FROM instruction_discovery_candidate AS candidate
     WHERE candidate.instruction_discovery_id = NEW.instruction_discovery_id;
    IF candidate_count <> candidate_max_ordinal THEN
        RAISE EXCEPTION 'instruction discovery candidate inventory is not contiguous'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_candidate_inventory_exact';
    END IF;
    SELECT coalesce(sum(bundle.source_byte_length), 0)
      INTO candidate_source_byte_sum
      FROM instruction_discovery_candidate AS candidate
      JOIN registered_instruction_bundle AS bundle
        ON bundle.instruction_bundle_id = candidate.instruction_bundle_id
     WHERE candidate.instruction_discovery_id = NEW.instruction_discovery_id;
    IF candidate_count > NEW.classified_entry_count
        OR candidate_source_byte_sum > NEW.candidate_source_byte_count
    THEN
        RAISE EXCEPTION 'instruction discovery candidates exceed consumed resources'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_candidate_usage_within_consumed';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM instruction_discovery_candidate AS candidate
          JOIN registered_instruction_bundle AS bundle
            ON bundle.instruction_bundle_id = candidate.instruction_bundle_id
         WHERE candidate.instruction_discovery_id = NEW.instruction_discovery_id
           AND NOT EXISTS (
                SELECT 1
                  FROM instruction_discovery_root AS root
                 WHERE root.instruction_discovery_id = NEW.instruction_discovery_id
                   AND root.root_kind = bundle.root_kind
                   AND root.root_path = bundle.root_path
           )
    ) THEN
        RAISE EXCEPTION 'instruction discovery candidate root is absent from inventory'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_candidate_root_in_inventory';
    END IF;

    SELECT count(*), coalesce(max(finding_ordinal), 0)
      INTO actual_finding_count, finding_max_ordinal
      FROM instruction_discovery_finding
     WHERE instruction_discovery_id = NEW.instruction_discovery_id;
    IF actual_finding_count <> NEW.finding_count
        OR actual_finding_count <> finding_max_ordinal
    THEN
        RAISE EXCEPTION 'instruction discovery finding count disagrees with inventory'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_finding_inventory_exact';
    END IF;
    SELECT count(*), coalesce(max(finding_ordinal), 0)
      INTO limit_finding_count, limit_finding_max_ordinal
      FROM instruction_discovery_finding
     WHERE instruction_discovery_id = NEW.instruction_discovery_id
       AND finding_kind LIKE 'limit_%';
    IF (NEW.scan_complete AND limit_finding_count <> 0)
        OR (
            NOT NEW.scan_complete
            AND (
                limit_finding_count <> 1
                OR limit_finding_max_ordinal <> NEW.finding_count
            )
        )
    THEN
        RAISE EXCEPTION 'instruction discovery completeness disagrees with terminal finding'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'instruction_discovery_completeness_exact';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_turn_instruction_manifest_discovery(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION validate_turn_instruction_manifest_discovery() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM instruction_discovery AS discovery
         WHERE discovery.instruction_discovery_id = NEW.instruction_discovery_id
           AND discovery.session_id = NEW.session_id
           AND discovery.turn_id = NEW.turn_id
           AND discovery.scan_complete
    ) THEN
        RAISE EXCEPTION 'turn instruction manifest requires a complete discovery'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'turn_instruction_manifest_discovery_complete';
    END IF;
    IF NEW.eligibility_hash <> sha256(
        convert_to('signalbox-instruction-eligibility-v1', 'UTF8')
    ) OR NEW.admitted_set_hash <> sha256(
        convert_to('signalbox-instruction-admitted-set-v1', 'UTF8')
        || '\x0000000000000000'::bytea
    ) OR NEW.manifest_hash <> sha256(
        convert_to('signalbox-turn-instruction-manifest-v1', 'UTF8')
        || uuid_send(NEW.session_id)
        || uuid_send(NEW.turn_id)
        || NEW.eligibility_hash
        || NEW.admitted_set_hash
        || convert_to(NEW.boundary_kind, 'UTF8')
    ) THEN
        RAISE EXCEPTION 'turn instruction manifest hashes are not canonical'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'turn_instruction_manifest_hash_shape';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: web_search_projection_chunks(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION web_search_projection_chunks(source_text text) RETURNS TABLE(ordinal integer, content_text text)
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
    SELECT chunk.ordinal,
           substring(source_text FROM chunk.ordinal * 15872 + 1 FOR 16384)
      FROM generate_series(
               0, (char_length(source_text) - 1) / 15872
           ) AS chunk(ordinal)
$$;


--
-- Name: web_search_projection_requires_session_address(); Type: FUNCTION; Schema: public
--

CREATE FUNCTION web_search_projection_requires_session_address() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM outbox_event
         WHERE session_id = NEW.session_id
           AND event_sequence = NEW.event_sequence
        UNION ALL
        SELECT 1
          FROM delegation_outbox_event
         WHERE session_id = NEW.session_id
           AND event_sequence = NEW.event_sequence
    ) THEN
        RAISE EXCEPTION
            'web search projection address does not belong to its session';
    END IF;
    RETURN NULL;
END
$$;


--
-- Name: workspace_root_path_is_valid(text); Type: FUNCTION; Schema: public
--

CREATE FUNCTION workspace_root_path_is_valid(candidate text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$
    SELECT octet_length(candidate) BETWEEN 2 AND 1024
       AND candidate COLLATE "C" ~ '^(/[^/[:cntrl:]]+)+$'
       AND candidate COLLATE "C" !~ '(^|/)[.][.]?(/|$)'
$_$;


--
-- Name: accepted_input; Type: TABLE; Schema: public
--

CREATE TABLE accepted_input (
    accepted_input_id uuid NOT NULL,
    accepting_command_id uuid,
    session_id uuid NOT NULL,
    delivery_kind text NOT NULL,
    expected_active_turn_id uuid,
    expected_defaults_version numeric(20,0),
    model_override_kind text,
    replacement_model_kind text,
    replacement_direct_model_selection_id uuid,
    replacement_model_alias_id uuid,
    acceptance_position numeric(20,0) NOT NULL,
    disposition_kind text NOT NULL,
    origin_turn_id uuid,
    consuming_model_call_id uuid,
    descendant_scope text,
    model_settings_override jsonb DEFAULT '{"fast_mode": {"kind": "inherit"}, "service_tier": {"kind": "inherit"}, "reasoning_level": {"kind": "inherit"}}'::jsonb NOT NULL,
    content_parts_creation_xid xid8 DEFAULT pg_current_xact_id() NOT NULL,
    CONSTRAINT accepted_input_configuration_shape CHECK ((((model_override_kind = 'use_session_default'::text) AND (replacement_model_kind IS NULL) AND (replacement_direct_model_selection_id IS NULL) AND (replacement_model_alias_id IS NULL)) OR ((model_override_kind = 'replace_with'::text) AND (replacement_model_kind = 'direct'::text) AND (replacement_direct_model_selection_id IS NOT NULL) AND (replacement_model_alias_id IS NULL)) OR ((model_override_kind = 'replace_with'::text) AND (replacement_model_kind = 'alias'::text) AND (replacement_direct_model_selection_id IS NULL) AND (replacement_model_alias_id IS NOT NULL)))),
    CONSTRAINT accepted_input_delivery_shape CHECK ((((disposition_kind = 'origin_of'::text) AND (delivery_kind = ANY (ARRAY['start_when_no_active_turn'::text, 'after_current_turn'::text, 'interrupt'::text])) AND (((delivery_kind = 'start_when_no_active_turn'::text) AND (expected_active_turn_id IS NULL)) OR ((delivery_kind = ANY (ARRAY['after_current_turn'::text, 'interrupt'::text])) AND (expected_active_turn_id IS NOT NULL))) AND (expected_defaults_version IS NOT NULL) AND (model_override_kind IS NOT NULL) AND (origin_turn_id IS NOT NULL) AND (consuming_model_call_id IS NULL)) OR ((disposition_kind = ANY (ARRAY['pending_steering'::text, 'consumed_as_steering'::text])) AND (delivery_kind = 'next_safe_point'::text) AND (expected_active_turn_id IS NOT NULL) AND (expected_defaults_version IS NULL) AND (model_override_kind IS NULL) AND (replacement_model_kind IS NULL) AND (replacement_direct_model_selection_id IS NULL) AND (replacement_model_alias_id IS NULL) AND (origin_turn_id IS NULL) AND (((disposition_kind = 'pending_steering'::text) AND (consuming_model_call_id IS NULL)) OR ((disposition_kind = 'consumed_as_steering'::text) AND (consuming_model_call_id IS NOT NULL)))) OR ((disposition_kind = 'reclassified_as_turn_origin'::text) AND (delivery_kind = 'next_safe_point'::text) AND (expected_active_turn_id IS NOT NULL) AND (expected_defaults_version IS NULL) AND (model_override_kind IS NULL) AND (replacement_model_kind IS NULL) AND (replacement_direct_model_selection_id IS NULL) AND (replacement_model_alias_id IS NULL) AND (origin_turn_id IS NOT NULL) AND (consuming_model_call_id IS NULL)))),
    CONSTRAINT accepted_input_descendant_scope_shape CHECK ((((delivery_kind = 'interrupt'::text) AND (descendant_scope IS NOT NULL) AND (descendant_scope = ANY (ARRAY['parent_alone'::text, 'parent_and_descendants'::text]))) OR ((delivery_kind <> 'interrupt'::text) AND (descendant_scope IS NULL)))),
    CONSTRAINT accepted_input_disposition_closed CHECK ((disposition_kind = ANY (ARRAY['origin_of'::text, 'pending_steering'::text, 'consumed_as_steering'::text, 'reclassified_as_turn_origin'::text]))),
    CONSTRAINT accepted_input_expected_defaults_positive_u64 CHECK (((expected_defaults_version >= (1)::numeric) AND (expected_defaults_version <= '18446744073709551615'::numeric))),
    CONSTRAINT accepted_input_model_settings_override_object CHECK ((jsonb_typeof(model_settings_override) = 'object'::text)),
    CONSTRAINT accepted_input_position_positive_u64 CHECK (((acceptance_position >= (1)::numeric) AND (acceptance_position <= '18446744073709551615'::numeric)))
);


--
-- Name: accepted_input_content_part; Type: TABLE; Schema: public
--

CREATE TABLE accepted_input_content_part (
    accepted_input_id uuid NOT NULL,
    "position" smallint NOT NULL,
    part_kind text NOT NULL,
    text_value text,
    blob_digest bytea,
    attachment_kind text,
    declared_media_type text,
    display_filename text,
    CONSTRAINT accepted_input_content_part_position CHECK ((("position" >= 0) AND ("position" <= 255))),
    CONSTRAINT accepted_input_content_part_shape CHECK ((((part_kind = 'text'::text) AND (text_value IS NOT NULL) AND (char_length(text_value) > 0) AND (blob_digest IS NULL) AND (attachment_kind IS NULL) AND (declared_media_type IS NULL) AND (display_filename IS NULL)) OR ((part_kind = 'attachment'::text) AND (text_value IS NULL) AND (blob_digest IS NOT NULL) AND (octet_length(blob_digest) = 32) AND (attachment_kind IS NOT NULL) AND (attachment_kind = ANY (ARRAY['image'::text, 'document'::text, 'file'::text])) AND (declared_media_type IS NOT NULL) AND (octet_length(declared_media_type) BETWEEN 1 AND 255) AND ((declared_media_type COLLATE "C") ~ '^[!-~]+$'::text) AND ((display_filename IS NULL) OR ((octet_length(convert_to(display_filename, 'UTF8'::name)) BETWEEN 1 AND 255) AND (display_filename <> ALL (ARRAY['.'::text, '..'::text])) AND (POSITION(('/'::text) IN (display_filename)) = 0) AND (POSITION((chr(92)) IN (display_filename)) = 0))))))
);


--
-- Name: approval_judge_eval_call; Type: TABLE; Schema: public
--

CREATE TABLE approval_judge_eval_call (
    eval_run_id uuid NOT NULL,
    case_name text NOT NULL,
    repeat_ordinal numeric(10,0) NOT NULL,
    recommendation_kind text NOT NULL,
    rationale text NOT NULL,
    input_tokens numeric,
    output_tokens numeric,
    cache_creation_input_tokens numeric,
    cache_read_input_tokens numeric,
    CONSTRAINT approval_judge_eval_call_case_name_nonempty CHECK ((char_length(case_name) > 0)),
    CONSTRAINT approval_judge_eval_call_rationale_bounded CHECK (((octet_length(rationale) >= 1) AND (octet_length(rationale) <= 4096))),
    CONSTRAINT approval_judge_eval_call_recommendation_closed CHECK ((recommendation_kind = ANY (ARRAY['approve'::text, 'deny'::text, 'escalate_to_human'::text]))),
    CONSTRAINT approval_judge_eval_call_repeat_ordinal_u32 CHECK (((repeat_ordinal >= (1)::numeric) AND (repeat_ordinal <= ('4294967295'::bigint)::numeric))),
    CONSTRAINT approval_judge_eval_call_usage_u64_range CHECK ((((input_tokens IS NULL) OR ((input_tokens = trunc(input_tokens)) AND ((input_tokens >= (0)::numeric) AND (input_tokens <= '18446744073709551615'::numeric)))) AND ((output_tokens IS NULL) OR ((output_tokens = trunc(output_tokens)) AND ((output_tokens >= (0)::numeric) AND (output_tokens <= '18446744073709551615'::numeric)))) AND ((cache_creation_input_tokens IS NULL) OR ((cache_creation_input_tokens = trunc(cache_creation_input_tokens)) AND ((cache_creation_input_tokens >= (0)::numeric) AND (cache_creation_input_tokens <= '18446744073709551615'::numeric)))) AND ((cache_read_input_tokens IS NULL) OR ((cache_read_input_tokens = trunc(cache_read_input_tokens)) AND ((cache_read_input_tokens >= (0)::numeric) AND (cache_read_input_tokens <= '18446744073709551615'::numeric))))))
);


--
-- Name: approval_judge_eval_run; Type: TABLE; Schema: public
--

CREATE TABLE approval_judge_eval_run (
    eval_run_id uuid NOT NULL,
    direct_model_selection_id uuid NOT NULL,
    resolved_provider_model_identity_id uuid CONSTRAINT approval_judge_eval_run_resolved_provider_model_identi_not_null NOT NULL,
    provider_model text NOT NULL,
    credential_reference text NOT NULL,
    recording_transaction_id xid8 DEFAULT pg_current_xact_id() NOT NULL,
    usage_input_includes_cache_tokens boolean CONSTRAINT approval_judge_eval_run_usage_input_includes_cache_tok_not_null NOT NULL,
    corpus_digest text NOT NULL,
    contract_digest text NOT NULL,
    rendered_digest text NOT NULL,
    repeats numeric(10,0) NOT NULL,
    scorecard jsonb NOT NULL,
    CONSTRAINT approval_judge_eval_run_credential_nonempty CHECK ((char_length(credential_reference) > 0)),
    CONSTRAINT approval_judge_eval_run_digests_nonempty CHECK (((char_length(corpus_digest) > 0) AND (char_length(contract_digest) > 0) AND (char_length(rendered_digest) > 0))),
    CONSTRAINT approval_judge_eval_run_provider_model_nonempty CHECK ((char_length(provider_model) > 0)),
    CONSTRAINT approval_judge_eval_run_repeats_u32 CHECK (((repeats >= (1)::numeric) AND (repeats <= ('4294967295'::bigint)::numeric))),
    CONSTRAINT approval_judge_eval_run_scorecard_shape CHECK ((jsonb_typeof(scorecard) = 'object'::text))
);


--
-- Name: automatic_reconciliation; Type: TABLE; Schema: public
--

CREATE TABLE automatic_reconciliation (
    turn_id uuid CONSTRAINT automatic_model_call_reconciliation_turn_id_not_null NOT NULL,
    session_id uuid CONSTRAINT automatic_model_call_reconciliation_session_id_not_null NOT NULL,
    model_call_id uuid,
    state_kind text DEFAULT 'scheduled'::text CONSTRAINT automatic_model_call_reconciliation_state_kind_not_null NOT NULL,
    attempt_count integer DEFAULT 0 CONSTRAINT automatic_model_call_reconciliation_attempt_count_not_null NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT statement_timestamp() CONSTRAINT automatic_model_call_reconciliation_next_attempt_at_not_null NOT NULL,
    exhausted_at timestamp with time zone,
    tool_attempt_id uuid,
    CONSTRAINT automatic_model_call_reconciliation_attempt_count CHECK (((attempt_count >= 0) AND (attempt_count <= 5))),
    CONSTRAINT automatic_model_call_reconciliation_exhaustion CHECK (((state_kind = 'exhausted'::text) = (exhausted_at IS NOT NULL))),
    CONSTRAINT automatic_model_call_reconciliation_state_kind CHECK ((state_kind = ANY (ARRAY['scheduled'::text, 'attempting'::text, 'reconciled'::text, 'superseded'::text, 'exhausted'::text]))),
    CONSTRAINT automatic_reconciliation_operation CHECK ((num_nonnulls(model_call_id, tool_attempt_id) = 1))
);


--
-- Name: automatic_reconciliation_attempt; Type: TABLE; Schema: public
--

CREATE TABLE automatic_reconciliation_attempt (
    turn_id uuid CONSTRAINT automatic_model_call_reconciliation_attempt_turn_id_not_null NOT NULL,
    attempt_ordinal integer CONSTRAINT automatic_model_call_reconciliation_at_attempt_ordinal_not_null NOT NULL,
    outcome_kind text DEFAULT 'attempting'::text CONSTRAINT automatic_model_call_reconciliation_attem_outcome_kind_not_null NOT NULL,
    started_at timestamp with time zone DEFAULT statement_timestamp() CONSTRAINT automatic_model_call_reconciliation_attempt_started_at_not_null NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT automatic_model_call_reconciliation_attempt_finished CHECK (((outcome_kind = 'attempting'::text) = (finished_at IS NULL))),
    CONSTRAINT automatic_model_call_reconciliation_attempt_ordinal CHECK (((attempt_ordinal >= 1) AND (attempt_ordinal <= 5))),
    CONSTRAINT automatic_model_call_reconciliation_attempt_outcome CHECK ((outcome_kind = ANY (ARRAY['attempting'::text, 'reconciled'::text, 'superseded'::text, 'infrastructure_failure'::text, 'integrity_failure'::text])))
);


--
-- Name: automatic_reconciliation_discovery_state; Type: TABLE; Schema: public
--

CREATE TABLE automatic_reconciliation_discovery_state (
    singleton boolean DEFAULT true NOT NULL,
    after_turn_id uuid,
    high_turn_id uuid,
    CONSTRAINT automatic_reconciliation_discovery_state_singleton_check CHECK (singleton)
);


--
-- Name: automatic_reconciliation_supersession_state; Type: TABLE; Schema: public
--

CREATE TABLE automatic_reconciliation_supersession_state (
    singleton boolean DEFAULT true NOT NULL,
    after_turn_id uuid,
    high_turn_id uuid,
    CONSTRAINT automatic_reconciliation_supersession_state_singleton_check CHECK (singleton)
);


--
-- Name: blob; Type: TABLE; Schema: public
--

CREATE TABLE blob (
    digest bytea NOT NULL,
    byte_length numeric(20,0) NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT blob_byte_length_positive_u64 CHECK (((byte_length >= (1)::numeric) AND (byte_length <= '18446744073709551615'::numeric))),
    CONSTRAINT blob_digest_size CHECK ((octet_length(digest) = 32))
);


--
-- Name: blob_derivation; Type: TABLE; Schema: public
--

CREATE TABLE blob_derivation (
    derivation_id uuid NOT NULL,
    deterministic_key bytea,
    transformation_name text NOT NULL COLLATE pg_catalog."C",
    transformation_version bigint NOT NULL,
    parameters_canonical text NOT NULL COLLATE pg_catalog."C",
    producer_class text NOT NULL COLLATE pg_catalog."C",
    implementation_digest bytea,
    execution_id uuid,
    model_call_id uuid,
    input_count smallint NOT NULL,
    output_count smallint NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT blob_derivation_counts CHECK (((input_count BETWEEN 1 AND 16) AND (output_count BETWEEN 1 AND 16))),
    CONSTRAINT blob_derivation_key_shape CHECK (((deterministic_key IS NULL) OR (octet_length(deterministic_key) = 32))),
    CONSTRAINT blob_derivation_name_shape CHECK (((octet_length(transformation_name) BETWEEN 1 AND 64) AND (transformation_name ~ '^[a-z][a-z0-9_.-]*$'::text))),
    CONSTRAINT blob_derivation_parameter_bound CHECK ((octet_length(parameters_canonical) <= 4096)),
    CONSTRAINT blob_derivation_producer_shape CHECK ((((producer_class = 'deterministic'::text) AND (deterministic_key IS NOT NULL) AND (implementation_digest IS NOT NULL) AND (octet_length(implementation_digest) = 32) AND (execution_id IS NULL) AND (model_call_id IS NULL)) OR ((producer_class = 'executed'::text) AND (deterministic_key IS NULL) AND (implementation_digest IS NOT NULL) AND (octet_length(implementation_digest) = 32) AND (execution_id IS NOT NULL) AND (model_call_id IS NULL)) OR ((producer_class = 'model_derived'::text) AND (deterministic_key IS NULL) AND (implementation_digest IS NULL) AND (execution_id IS NULL) AND (model_call_id IS NOT NULL)))),
    CONSTRAINT blob_derivation_version_shape CHECK (((transformation_version >= 1) AND (transformation_version <= '4294967295'::bigint)))
);


--
-- Name: blob_derivation_input; Type: TABLE; Schema: public
--

CREATE TABLE blob_derivation_input (
    derivation_id uuid NOT NULL,
    input_ordinal smallint NOT NULL,
    digest bytea NOT NULL,
    CONSTRAINT blob_derivation_input_digest CHECK ((octet_length(digest) = 32)),
    CONSTRAINT blob_derivation_input_ordinal CHECK (((input_ordinal >= 0) AND (input_ordinal <= 15)))
);


--
-- Name: blob_derivation_output; Type: TABLE; Schema: public
--

CREATE TABLE blob_derivation_output (
    derivation_id uuid NOT NULL,
    output_ordinal smallint NOT NULL,
    digest bytea NOT NULL,
    CONSTRAINT blob_derivation_output_digest CHECK ((octet_length(digest) = 32)),
    CONSTRAINT blob_derivation_output_ordinal CHECK (((output_ordinal >= 0) AND (output_ordinal <= 15)))
);


--
-- Name: blob_read_tool_charge; Type: TABLE; Schema: public
--

CREATE TABLE blob_read_tool_charge (
    request_id uuid NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    blob_digest bytea NOT NULL,
    decoded_byte_count numeric(20,0) NOT NULL,
    admitted boolean NOT NULL,
    rejection_reason text,
    CONSTRAINT blob_read_tool_charge_bytes_positive_u64 CHECK (((decoded_byte_count >= (1)::numeric) AND (decoded_byte_count <= '18446744073709551615'::numeric))),
    CONSTRAINT blob_read_tool_charge_rejection_shape CHECK (((admitted AND (rejection_reason IS NULL)) OR ((NOT admitted) AND (rejection_reason = ANY (ARRAY['blob_turn_byte_budget_exceeded'::text, 'blob_turn_read_count_exceeded'::text])))))
);


--
-- Name: blob_replica; Type: TABLE; Schema: public
--

CREATE TABLE blob_replica (
    digest bytea NOT NULL,
    store_name text NOT NULL COLLATE pg_catalog."C",
    object_key text NOT NULL COLLATE pg_catalog."C",
    verified_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT blob_replica_digest_size CHECK ((octet_length(digest) = 32)),
    CONSTRAINT blob_replica_object_key_bounded CHECK (((octet_length(object_key) >= 1) AND (octet_length(object_key) <= 1024))),
    CONSTRAINT blob_replica_store_name_bounded CHECK (((octet_length(store_name) BETWEEN 1 AND 64) AND (store_name ~ '^[a-z][a-z0-9_-]{0,63}$'::text)))
);


--
-- Name: blob_store_binding; Type: TABLE; Schema: public
--

CREATE TABLE blob_store_binding (
    store_name text NOT NULL COLLATE pg_catalog."C",
    namespace_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT blob_store_binding_name_canonical CHECK (((octet_length(store_name) BETWEEN 1 AND 64) AND (store_name ~ '^[a-z][a-z0-9_-]{0,63}$'::text)))
);


--
-- Name: commissioned_dispatch; Type: TABLE; Schema: public
--

CREATE TABLE commissioned_dispatch (
    dispatch_id uuid NOT NULL,
    session_id uuid NOT NULL,
    create_command_id uuid NOT NULL,
    template_name text NOT NULL,
    template_content_digest bytea NOT NULL,
    initial_content_digest bytea NOT NULL,
    target_kind text NOT NULL,
    repository text NOT NULL,
    pull_request_number numeric(20,0),
    head_sha text,
    head_repository text,
    head_branch text,
    base_branch text,
    branch text,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT commissioned_dispatch_base_branch_check CHECK (((base_branch IS NULL) OR repo_watch_branch_is_valid(base_branch))),
    CONSTRAINT commissioned_dispatch_branch_check CHECK (((branch IS NULL) OR repo_watch_branch_is_valid(branch))),
    CONSTRAINT commissioned_dispatch_check CHECK ((((target_kind = 'pull_request'::text) AND (pull_request_number IS NOT NULL) AND (head_sha IS NOT NULL) AND (head_repository IS NOT NULL) AND (head_branch IS NOT NULL) AND (base_branch IS NOT NULL) AND (branch IS NULL)) OR ((target_kind = 'branch'::text) AND (pull_request_number IS NULL) AND (head_sha IS NULL) AND (head_repository IS NULL) AND (head_branch IS NULL) AND (base_branch IS NULL) AND (branch IS NOT NULL)))),
    CONSTRAINT commissioned_dispatch_head_branch_check CHECK (((head_branch IS NULL) OR repo_watch_branch_is_valid(head_branch))),
    CONSTRAINT commissioned_dispatch_head_repository_check CHECK (((head_repository IS NULL) OR repo_watch_repository_is_valid(head_repository))),
    CONSTRAINT commissioned_dispatch_head_sha_check CHECK (((head_sha IS NULL) OR ((head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT commissioned_dispatch_initial_content_digest_check CHECK ((octet_length(initial_content_digest) = 32)),
    CONSTRAINT commissioned_dispatch_pull_request_number_check CHECK (((pull_request_number IS NULL) OR ((pull_request_number > (0)::numeric) AND (pull_request_number <= '18446744073709551615'::numeric)))),
    CONSTRAINT commissioned_dispatch_repository_check CHECK (repo_watch_repository_is_valid(repository)),
    CONSTRAINT commissioned_dispatch_target_kind_check CHECK ((target_kind = ANY (ARRAY['pull_request'::text, 'branch'::text]))),
    CONSTRAINT commissioned_dispatch_template_content_digest_check CHECK ((octet_length(template_content_digest) = 32)),
    CONSTRAINT commissioned_dispatch_template_name_check CHECK (((octet_length(template_name) >= 1) AND (octet_length(template_name) <= 128)))
);


--
-- Name: commissioned_dispatch_headless_approval_escalation; Type: TABLE; Schema: public
--

CREATE TABLE commissioned_dispatch_headless_approval_escalation (
    model_call_id uuid CONSTRAINT commissioned_dispatch_headless_approval__model_call_id_not_null NOT NULL,
    request_id uuid CONSTRAINT commissioned_dispatch_headless_approval_esc_request_id_not_null NOT NULL,
    dispatch_id uuid CONSTRAINT commissioned_dispatch_headless_approval_es_dispatch_id_not_null NOT NULL,
    session_id uuid CONSTRAINT commissioned_dispatch_headless_approval_esc_session_id_not_null NOT NULL,
    turn_id uuid CONSTRAINT commissioned_dispatch_headless_approval_escala_turn_id_not_null NOT NULL,
    terminal_attempt_id uuid CONSTRAINT commissioned_dispatch_headless_app_terminal_attempt_id_not_null NOT NULL,
    failure_entry_id uuid CONSTRAINT commissioned_dispatch_headless_approv_failure_entry_id_not_null NOT NULL,
    terminal_frontier_id uuid CONSTRAINT commissioned_dispatch_headless_ap_terminal_frontier_id_not_null NOT NULL,
    escalated_at timestamp with time zone DEFAULT transaction_timestamp() CONSTRAINT commissioned_dispatch_headless_approval_e_escalated_at_not_null NOT NULL
);


--
-- Name: tool_approval_judge_model_call; Type: TABLE; Schema: public
--

CREATE TABLE tool_approval_judge_model_call (
    model_call_id uuid NOT NULL,
    request_id uuid NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid NOT NULL,
    direct_model_selection_id uuid CONSTRAINT tool_approval_judge_model_ca_direct_model_selection_id_not_null NOT NULL,
    resolved_provider_model_identity_id uuid CONSTRAINT tool_approval_judge_model_c_resolved_provider_model_id_not_null NOT NULL,
    credential_reference text NOT NULL,
    usage_input_includes_cache_tokens boolean DEFAULT false CONSTRAINT tool_approval_judge_model_c_usage_input_includes_cache_not_null NOT NULL,
    usage_provenance_kind text DEFAULT 'reported'::text NOT NULL,
    state_kind text NOT NULL,
    terminal_disposition_kind text,
    recommendation_kind text,
    rationale text,
    input_tokens numeric,
    output_tokens numeric,
    cache_read_input_tokens numeric,
    cache_creation_input_tokens numeric,
    CONSTRAINT tool_approval_judge_call_cancelled_usage_is_unreported CHECK (((terminal_disposition_kind IS DISTINCT FROM 'cancelled'::text) OR ((input_tokens IS NULL) AND (output_tokens IS NULL) AND (cache_read_input_tokens IS NULL) AND (cache_creation_input_tokens IS NULL)))),
    CONSTRAINT tool_approval_judge_call_credential_nonempty CHECK ((char_length(credential_reference) > 0)),
    CONSTRAINT tool_approval_judge_call_disposition_closed CHECK (((terminal_disposition_kind IS NULL) OR (terminal_disposition_kind = ANY (ARRAY['completed'::text, 'known_failed'::text, 'refused'::text, 'cancelled'::text, 'ambiguous'::text])))),
    CONSTRAINT tool_approval_judge_call_recommendation_closed CHECK (((recommendation_kind IS NULL) OR (recommendation_kind = ANY (ARRAY['approve'::text, 'deny'::text, 'escalate_to_human'::text])))),
    CONSTRAINT tool_approval_judge_call_state_closed CHECK ((state_kind = ANY (ARRAY['prepared'::text, 'in_flight'::text, 'terminal'::text]))),
    CONSTRAINT tool_approval_judge_call_state_shape CHECK ((((state_kind <> 'terminal'::text) AND (terminal_disposition_kind IS NULL) AND (recommendation_kind IS NULL) AND (rationale IS NULL)) OR ((state_kind = 'terminal'::text) AND (terminal_disposition_kind = 'completed'::text) AND (recommendation_kind IS NOT NULL) AND (rationale IS NOT NULL) AND ((octet_length(rationale) >= 1) AND (octet_length(rationale) <= 4096))) OR ((state_kind = 'terminal'::text) AND (terminal_disposition_kind IS NOT NULL) AND (terminal_disposition_kind <> 'completed'::text) AND (recommendation_kind IS NULL) AND (rationale IS NULL)))),
    CONSTRAINT tool_approval_judge_call_usage_provenance_closed CHECK ((usage_provenance_kind = ANY (ARRAY['reported'::text, 'estimated'::text]))),
    CONSTRAINT tool_approval_judge_call_usage_u64_range CHECK ((((input_tokens IS NULL) OR ((input_tokens = trunc(input_tokens)) AND ((input_tokens >= (0)::numeric) AND (input_tokens <= '18446744073709551615'::numeric)))) AND ((output_tokens IS NULL) OR ((output_tokens = trunc(output_tokens)) AND ((output_tokens >= (0)::numeric) AND (output_tokens <= '18446744073709551615'::numeric)))) AND ((cache_read_input_tokens IS NULL) OR ((cache_read_input_tokens = trunc(cache_read_input_tokens)) AND ((cache_read_input_tokens >= (0)::numeric) AND (cache_read_input_tokens <= '18446744073709551615'::numeric)))) AND ((cache_creation_input_tokens IS NULL) OR ((cache_creation_input_tokens = trunc(cache_creation_input_tokens)) AND ((cache_creation_input_tokens >= (0)::numeric) AND (cache_creation_input_tokens <= '18446744073709551615'::numeric))))))
);


--
-- Name: commissioned_dispatch_headless_approval_escalation_audit; Type: VIEW; Schema: public
--

CREATE VIEW commissioned_dispatch_headless_approval_escalation_audit AS
 SELECT escalation.model_call_id,
    escalation.request_id,
    escalation.dispatch_id,
    escalation.session_id,
    escalation.turn_id,
    escalation.terminal_attempt_id,
    escalation.failure_entry_id,
    escalation.terminal_frontier_id,
    judge.rationale,
    escalation.escalated_at
   FROM (commissioned_dispatch_headless_approval_escalation escalation
     JOIN tool_approval_judge_model_call judge ON ((judge.model_call_id = escalation.model_call_id)));


--
-- Name: compact_session_command; Type: TABLE; Schema: public
--

CREATE TABLE compact_session_command (
    command_id uuid NOT NULL,
    command_kind text NOT NULL,
    storage_version smallint NOT NULL,
    session_id uuid NOT NULL,
    requested_through_position numeric(20,0),
    automatic_for_turn_id uuid,
    result_kind text NOT NULL,
    result_context_compaction_id uuid,
    model_call_id uuid NOT NULL,
    result_through_position numeric(20,0),
    result_summary_entry_id uuid,
    result_frontier_id uuid,
    CONSTRAINT compact_session_command_kind_closed CHECK ((command_kind = 'compact_session'::text)),
    CONSTRAINT compact_session_command_requested_position_u64 CHECK (((requested_through_position IS NULL) OR ((requested_through_position >= (1)::numeric) AND (requested_through_position <= '18446744073709551615'::numeric)))),
    CONSTRAINT compact_session_command_result_kind_closed CHECK ((result_kind = ANY (ARRAY['pending'::text, 'applied'::text, 'failed'::text]))),
    CONSTRAINT compact_session_command_result_position_u64 CHECK (((result_through_position IS NULL) OR ((result_through_position >= (1)::numeric) AND (result_through_position <= '18446744073709551615'::numeric)))),
    CONSTRAINT compact_session_command_result_shape CHECK ((((result_kind = ANY (ARRAY['pending'::text, 'failed'::text])) AND (result_context_compaction_id IS NULL) AND (result_through_position IS NULL) AND (result_summary_entry_id IS NULL) AND (result_frontier_id IS NULL)) OR ((result_kind = 'applied'::text) AND (result_context_compaction_id IS NOT NULL) AND (result_through_position IS NOT NULL) AND (result_summary_entry_id IS NOT NULL) AND (result_frontier_id IS NOT NULL)))),
    CONSTRAINT compact_session_command_storage_version_supported CHECK ((storage_version = 1))
);


