    direct_model_selection_id uuid CONSTRAINT context_compaction_model_cal_direct_model_selection_id_not_null NOT NULL,
    resolved_provider_model_identity_id uuid CONSTRAINT context_compaction_model_ca_resolved_provider_model_id_not_null NOT NULL,
    source_frontier_id uuid NOT NULL,
    credential_reference text NOT NULL,
    state_kind text NOT NULL,
    terminal_disposition_kind text,
    input_tokens numeric(20,0),
    output_tokens numeric(20,0),
    cache_read_input_tokens numeric(20,0),
    cache_creation_input_tokens numeric(20,0),
    usage_input_includes_cache_tokens boolean DEFAULT false,
    CONSTRAINT context_compaction_model_call_credential_reference_nonempty CHECK ((char_length(credential_reference) > 0)),
    CONSTRAINT context_compaction_model_call_disposition_closed CHECK (((terminal_disposition_kind IS NULL) OR (terminal_disposition_kind = ANY (ARRAY['completed'::text, 'known_failed'::text, 'refused'::text, 'cancelled'::text, 'ambiguous'::text])))),
    CONSTRAINT context_compaction_model_call_state_closed CHECK ((state_kind = ANY (ARRAY['prepared'::text, 'in_flight'::text, 'terminal'::text]))),
    CONSTRAINT context_compaction_model_call_state_shape CHECK ((((state_kind <> 'terminal'::text) AND (terminal_disposition_kind IS NULL)) OR ((state_kind = 'terminal'::text) AND (terminal_disposition_kind IS NOT NULL)))),
    CONSTRAINT context_compaction_model_call_usage_u64 CHECK ((((input_tokens IS NULL) OR ((input_tokens = trunc(input_tokens)) AND ((input_tokens >= (0)::numeric) AND (input_tokens <= '18446744073709551615'::numeric)))) AND ((output_tokens IS NULL) OR ((output_tokens = trunc(output_tokens)) AND ((output_tokens >= (0)::numeric) AND (output_tokens <= '18446744073709551615'::numeric)))) AND ((cache_read_input_tokens IS NULL) OR ((cache_read_input_tokens = trunc(cache_read_input_tokens)) AND ((cache_read_input_tokens >= (0)::numeric) AND (cache_read_input_tokens <= '18446744073709551615'::numeric)))) AND ((cache_creation_input_tokens IS NULL) OR ((cache_creation_input_tokens = trunc(cache_creation_input_tokens)) AND ((cache_creation_input_tokens >= (0)::numeric) AND (cache_creation_input_tokens <= '18446744073709551615'::numeric))))))
);


--
-- Name: context_frontier; Type: TABLE; Schema: public
--

CREATE TABLE context_frontier (
    owning_session_id uuid NOT NULL,
    context_frontier_id uuid NOT NULL,
    member_count numeric(20,0) NOT NULL,
    prefix_context_frontier_id uuid,
    CONSTRAINT context_frontier_member_count_u64 CHECK (((member_count >= (0)::numeric) AND (member_count <= '18446744073709551615'::numeric)))
);


--
-- Name: context_frontier_delta; Type: TABLE; Schema: public
--

CREATE TABLE context_frontier_delta (
    owning_session_id uuid CONSTRAINT context_frontier_member_owning_session_id_not_null NOT NULL,
    context_frontier_id uuid CONSTRAINT context_frontier_member_context_frontier_id_not_null NOT NULL,
    member_position numeric(20,0) CONSTRAINT context_frontier_member_member_position_not_null NOT NULL,
    source_session_id uuid CONSTRAINT context_frontier_member_source_session_id_not_null NOT NULL,
    semantic_entry_id uuid CONSTRAINT context_frontier_member_semantic_entry_id_not_null NOT NULL,
    CONSTRAINT context_frontier_member_position_positive_u64 CHECK (((member_position >= (1)::numeric) AND (member_position <= '18446744073709551615'::numeric)))
);


--
-- Name: context_frontier_member; Type: VIEW; Schema: public
--

CREATE VIEW context_frontier_member AS
 SELECT frontier.owning_session_id,
    frontier.context_frontier_id,
    member.member_position,
    member.source_session_id,
    member.semantic_entry_id
   FROM (context_frontier frontier
     CROSS JOIN LATERAL resolve_context_frontier_members(frontier.owning_session_id, frontier.context_frontier_id) member(owning_session_id, context_frontier_id, member_position, source_session_id, semantic_entry_id));


--
-- Name: convergence_sweep_event; Type: TABLE; Schema: public
--

CREATE TABLE convergence_sweep_event (
    event_id uuid NOT NULL,
    repository text NOT NULL,
    pull_request_number numeric(20,0) NOT NULL,
    outcome_kind text NOT NULL,
    failure_kind text,
    head_sha text,
    unresolved_threads numeric(20,0),
    dispatch_id uuid,
    session_id uuid,
    consecutive_failures smallint NOT NULL,
    retry_not_before timestamp with time zone,
    operator_need text,
    recorded_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,
    CONSTRAINT convergence_sweep_event_check CHECK (((dispatch_id IS NULL) = (session_id IS NULL))),
    CONSTRAINT convergence_sweep_event_check1 CHECK ((((outcome_kind = ANY (ARRAY['converged'::text, 'cooling_off'::text, 'live_session'::text, 'dispatched'::text])) AND (failure_kind IS NULL) AND (consecutive_failures = 0) AND (retry_not_before IS NULL) AND (operator_need IS NULL)) OR ((outcome_kind = 'facts_fetch_failed'::text) AND (failure_kind = 'facts_fetch'::text)) OR ((outcome_kind = 'commission_refused'::text) AND (failure_kind = 'commission_refused'::text)) OR ((outcome_kind = 'template_drift'::text) AND (failure_kind = 'template_drift'::text)) OR ((outcome_kind = 'no_model_activity'::text) AND (failure_kind = 'no_model_activity'::text)) OR ((outcome_kind = 'state_access_failed'::text) AND (failure_kind = 'state_access'::text)))),
    CONSTRAINT convergence_sweep_event_check2 CHECK (((failure_kind IS NULL) OR ((operator_need IS NULL) AND ((consecutive_failures >= 1) AND (consecutive_failures <= (convergence_sweep_retry_budget() - 1))) AND (retry_not_before IS NOT NULL)) OR ((operator_need IS NOT NULL) AND (consecutive_failures = convergence_sweep_retry_budget()) AND (retry_not_before IS NULL)))),
    CONSTRAINT convergence_sweep_event_consecutive_failures_check CHECK (((consecutive_failures >= 0) AND (consecutive_failures <= convergence_sweep_retry_budget()))),
    CONSTRAINT convergence_sweep_event_failure_kind_check CHECK (((failure_kind IS NULL) OR (failure_kind = ANY (ARRAY['facts_fetch'::text, 'commission_refused'::text, 'template_drift'::text, 'no_model_activity'::text, 'state_access'::text])))),
    CONSTRAINT convergence_sweep_event_head_sha_check CHECK (((head_sha IS NULL) OR ((head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT convergence_sweep_event_operator_need_check CHECK (((operator_need IS NULL) OR (operator_need = ANY (ARRAY['repair_facts_fetch'::text, 'repair_commission'::text, 'repair_template'::text, 'inspect_inactive_session'::text, 'repair_sweep_state'::text])))),
    CONSTRAINT convergence_sweep_event_outcome_kind_check CHECK ((outcome_kind = ANY (ARRAY['converged'::text, 'cooling_off'::text, 'live_session'::text, 'dispatched'::text, 'facts_fetch_failed'::text, 'commission_refused'::text, 'template_drift'::text, 'no_model_activity'::text, 'state_access_failed'::text]))),
    CONSTRAINT convergence_sweep_event_pull_request_number_check CHECK (((pull_request_number >= (1)::numeric) AND (pull_request_number <= '18446744073709551615'::numeric))),
    CONSTRAINT convergence_sweep_event_repository_check CHECK (repo_watch_repository_is_valid(repository)),
    CONSTRAINT convergence_sweep_event_unresolved_threads_check CHECK (((unresolved_threads IS NULL) OR (unresolved_threads >= (0)::numeric)))
);


--
-- Name: convergence_sweep_target; Type: TABLE; Schema: public
--

CREATE TABLE convergence_sweep_target (
    repository text NOT NULL,
    pull_request_number numeric(20,0) NOT NULL,
    enrolled boolean DEFAULT true NOT NULL,
    state_kind text DEFAULT 'observed'::text NOT NULL,
    failure_kind text,
    consecutive_failures smallint DEFAULT 0 NOT NULL,
    retry_not_before timestamp with time zone,
    parked_at timestamp with time zone,
    operator_need text,
    last_head_sha text,
    last_unresolved_threads numeric(20,0),
    last_observed_at timestamp with time zone,
    pending_command_id uuid,
    pending_head_sha text,
    pending_unresolved_threads numeric(20,0),
    pending_content_digest bytea,
    pending_started_at timestamp with time zone,
    last_dispatch_id uuid,
    last_session_id uuid,
    last_dispatched_at timestamp with time zone,
    last_dispatch_head_sha text,
    last_dispatch_unresolved_threads numeric(20,0),
    census_dispatch_id uuid,
    census_session_id uuid,
    census_dispatch_head_sha text,
    census_dispatch_unresolved_threads numeric(20,0),
    parked_dispatch_id uuid,
    parked_session_id uuid,
    parked_dispatched_at timestamp with time zone,
    CONSTRAINT convergence_sweep_inactivity_park_has_dispatch CHECK (((state_kind <> 'parked'::text) OR (failure_kind <> 'no_model_activity'::text) OR (parked_dispatch_id IS NOT NULL))),
    CONSTRAINT convergence_sweep_parked_dispatch_shape CHECK ((((parked_dispatch_id IS NULL) AND (parked_session_id IS NULL) AND (parked_dispatched_at IS NULL)) OR ((state_kind = 'parked'::text) AND (failure_kind = 'no_model_activity'::text) AND (parked_dispatch_id IS NOT NULL) AND (parked_session_id IS NOT NULL) AND (parked_dispatched_at IS NOT NULL)))),
    CONSTRAINT convergence_sweep_target_census_dispatch_head_sha_check CHECK (((census_dispatch_head_sha IS NULL) OR ((census_dispatch_head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT convergence_sweep_target_census_dispatch_unresolved_threa_check CHECK (((census_dispatch_unresolved_threads IS NULL) OR (census_dispatch_unresolved_threads >= (0)::numeric))),
    CONSTRAINT convergence_sweep_target_check CHECK ((((state_kind = 'observed'::text) AND (failure_kind IS NULL) AND (consecutive_failures = 0) AND (retry_not_before IS NULL) AND (parked_at IS NULL) AND (operator_need IS NULL)) OR ((state_kind = 'retry_wait'::text) AND (failure_kind IS NOT NULL) AND (failure_kind <> 'no_model_activity'::text) AND ((consecutive_failures >= 1) AND (consecutive_failures <= (convergence_sweep_retry_budget() - 1))) AND (retry_not_before IS NOT NULL) AND (parked_at IS NULL) AND (operator_need IS NULL)) OR ((state_kind = 'parked'::text) AND (failure_kind IS NOT NULL) AND (consecutive_failures = convergence_sweep_retry_budget()) AND (retry_not_before IS NULL) AND (parked_at IS NOT NULL) AND (operator_need IS NOT NULL)))),
    CONSTRAINT convergence_sweep_target_check1 CHECK ((((pending_command_id IS NULL) AND (pending_head_sha IS NULL) AND (pending_unresolved_threads IS NULL) AND (pending_content_digest IS NULL) AND (pending_started_at IS NULL)) OR ((pending_command_id IS NOT NULL) AND (pending_head_sha IS NOT NULL) AND (pending_unresolved_threads IS NOT NULL) AND (pending_content_digest IS NOT NULL) AND (octet_length(pending_content_digest) = 32) AND (pending_started_at IS NOT NULL)))),
    CONSTRAINT convergence_sweep_target_check2 CHECK ((((last_dispatch_id IS NULL) AND (last_session_id IS NULL) AND (last_dispatched_at IS NULL) AND (last_dispatch_head_sha IS NULL) AND (last_dispatch_unresolved_threads IS NULL)) OR ((last_dispatch_id IS NOT NULL) AND (last_session_id IS NOT NULL) AND (last_dispatched_at IS NOT NULL) AND (last_dispatch_head_sha IS NOT NULL) AND (last_dispatch_unresolved_threads IS NOT NULL)))),
    CONSTRAINT convergence_sweep_target_check3 CHECK ((((census_dispatch_id IS NULL) AND (census_session_id IS NULL) AND (census_dispatch_head_sha IS NULL) AND (census_dispatch_unresolved_threads IS NULL)) OR ((census_dispatch_id IS NOT NULL) AND (census_session_id IS NOT NULL) AND (census_dispatch_head_sha IS NOT NULL) AND (census_dispatch_unresolved_threads IS NOT NULL)))),
    CONSTRAINT convergence_sweep_target_consecutive_failures_check CHECK (((consecutive_failures >= 0) AND (consecutive_failures <= convergence_sweep_retry_budget()))),
    CONSTRAINT convergence_sweep_target_failure_kind_check CHECK (((failure_kind IS NULL) OR (failure_kind = ANY (ARRAY['facts_fetch'::text, 'commission_refused'::text, 'template_drift'::text, 'no_model_activity'::text, 'state_access'::text])))),
    CONSTRAINT convergence_sweep_target_last_dispatch_head_sha_check CHECK (((last_dispatch_head_sha IS NULL) OR ((last_dispatch_head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT convergence_sweep_target_last_dispatch_unresolved_threads_check CHECK (((last_dispatch_unresolved_threads IS NULL) OR (last_dispatch_unresolved_threads >= (0)::numeric))),
    CONSTRAINT convergence_sweep_target_last_head_sha_check CHECK (((last_head_sha IS NULL) OR ((last_head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT convergence_sweep_target_last_unresolved_threads_check CHECK (((last_unresolved_threads IS NULL) OR (last_unresolved_threads >= (0)::numeric))),
    CONSTRAINT convergence_sweep_target_operator_need_check CHECK (((operator_need IS NULL) OR (operator_need = ANY (ARRAY['repair_facts_fetch'::text, 'repair_commission'::text, 'repair_template'::text, 'inspect_inactive_session'::text, 'repair_sweep_state'::text])))),
    CONSTRAINT convergence_sweep_target_pending_head_sha_check CHECK (((pending_head_sha IS NULL) OR ((pending_head_sha COLLATE "C") ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT convergence_sweep_target_pending_unresolved_threads_check CHECK (((pending_unresolved_threads IS NULL) OR (pending_unresolved_threads >= (0)::numeric))),
    CONSTRAINT convergence_sweep_target_pull_request_number_check CHECK (((pull_request_number >= (1)::numeric) AND (pull_request_number <= '18446744073709551615'::numeric))),
    CONSTRAINT convergence_sweep_target_repository_check CHECK (repo_watch_repository_is_valid(repository)),
    CONSTRAINT convergence_sweep_target_state_kind_check CHECK ((state_kind = ANY (ARRAY['observed'::text, 'retry_wait'::text, 'parked'::text])))
);


--
-- Name: convergence_sweep_parked_target; Type: VIEW; Schema: public
--

CREATE VIEW convergence_sweep_parked_target AS
 SELECT repository,
    pull_request_number,
    failure_kind,
    consecutive_failures,
    parked_at,
    operator_need,
    last_head_sha,
    last_unresolved_threads,
        CASE
            WHEN (failure_kind = 'no_model_activity'::text) THEN parked_dispatch_id
            ELSE last_dispatch_id
        END AS last_dispatch_id,
        CASE
            WHEN (failure_kind = 'no_model_activity'::text) THEN parked_session_id
            ELSE last_session_id
        END AS last_session_id,
        CASE
            WHEN (failure_kind = 'no_model_activity'::text) THEN parked_dispatched_at
            ELSE last_dispatched_at
        END AS last_dispatched_at
   FROM convergence_sweep_target target
  WHERE (enrolled AND (state_kind = 'parked'::text));


--
-- Name: create_session_command; Type: TABLE; Schema: public
--

CREATE TABLE create_session_command (
    command_id uuid NOT NULL,
    command_kind text NOT NULL,
    storage_version smallint NOT NULL,
    creation_cause text NOT NULL,
    ancestry_kind text NOT NULL,
    initial_defaults_version numeric(20,0) NOT NULL,
    model_selection_kind text NOT NULL,
    direct_model_selection_id uuid,
    model_alias_id uuid,
    model_selection_reference uuid GENERATED ALWAYS AS (COALESCE(direct_model_selection_id, model_alias_id)) STORED,
    result_kind text NOT NULL,
    created_session_id uuid NOT NULL,
    dangerous_tool_auto_approval text DEFAULT 'disabled'::text NOT NULL,
    system_prompt text,
    system_prompt_digest bytea GENERATED ALWAYS AS (session_system_prompt_digest(system_prompt)) STORED NOT NULL,
    template_name text,
    template_content_digest bytea,
    placement_path text,
    root_global_read_intent boolean DEFAULT false NOT NULL,
    model_settings jsonb DEFAULT '{"effective": {"fast_mode": "disabled", "service_tier": null, "reasoning_level": null}, "precedence": {"profile": {"fast_mode": {"kind": "inherit"}, "service_tier": {"kind": "inherit"}, "reasoning_level": {"kind": "inherit"}}, "session": {"fast_mode": {"kind": "inherit"}, "service_tier": {"kind": "inherit"}, "reasoning_level": {"kind": "inherit"}}, "per_call": {"fast_mode": {"kind": "inherit"}, "service_tier": {"kind": "inherit"}, "reasoning_level": {"kind": "inherit"}}, "global_default": {"fast_mode": {"kind": "inherit"}, "service_tier": {"kind": "inherit"}, "reasoning_level": {"kind": "inherit"}}}, "fast_mode_source": null, "reasoning_source": null, "service_tier_source": null, "validated_for_selection_id": null}'::jsonb NOT NULL,
    CONSTRAINT create_session_command_ancestry_kind_closed CHECK ((ancestry_kind = 'none'::text)),
    CONSTRAINT create_session_command_creation_cause_closed CHECK ((creation_cause = 'user_initiated'::text)),
    CONSTRAINT create_session_command_initial_defaults_version CHECK ((initial_defaults_version = (1)::numeric)),
    CONSTRAINT create_session_command_kind_closed CHECK ((command_kind = 'create_session'::text)),
    CONSTRAINT create_session_command_model_selection_kind_closed CHECK ((model_selection_kind = ANY (ARRAY['direct'::text, 'alias'::text]))),
    CONSTRAINT create_session_command_model_selection_shape CHECK ((((model_selection_kind = 'direct'::text) AND (direct_model_selection_id IS NOT NULL) AND (model_alias_id IS NULL)) OR ((model_selection_kind = 'alias'::text) AND (direct_model_selection_id IS NULL) AND (model_alias_id IS NOT NULL)))),
    CONSTRAINT create_session_command_model_settings_object CHECK ((jsonb_typeof(model_settings) = 'object'::text)),
    CONSTRAINT create_session_command_placement_path_shape CHECK (((placement_path IS NULL) OR ((octet_length(placement_path) BETWEEN 1 AND 4159) AND (placement_path ~ '^[A-Za-z0-9_-]{1,64}(\.[A-Za-z0-9_-]{1,64}){0,63}$'::text)))),
    CONSTRAINT create_session_command_placement_versioned CHECK (((storage_version >= 6) OR ((placement_path IS NULL) AND (NOT root_global_read_intent)))),
    CONSTRAINT create_session_command_result_kind_closed CHECK ((result_kind = 'applied'::text)),
    CONSTRAINT create_session_command_root_intent_shape CHECK ((root_global_read_intent = ((placement_path IS NOT NULL) AND (POSITION(('.'::text) IN (placement_path)) = 0)))),
    CONSTRAINT create_session_command_storage_version_supported CHECK ((storage_version = ANY (ARRAY[1, 2, 3, 4, 5, 6, 7]))),
    CONSTRAINT create_session_command_system_prompt_bounded CHECK (((system_prompt IS NULL) OR ((octet_length(convert_to(system_prompt, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(system_prompt, 'UTF8'::name)) <= 1048576)))),
    CONSTRAINT create_session_command_system_prompt_versioned CHECK (((system_prompt IS NULL) OR (storage_version >= 3))),
    CONSTRAINT create_session_command_template_prompt_required CHECK (((template_name IS NULL) OR (system_prompt IS NOT NULL))),
    CONSTRAINT create_session_command_template_provenance_shape CHECK ((((template_name IS NULL) AND (template_content_digest IS NULL)) OR ((template_name IS NOT NULL) AND (template_content_digest IS NOT NULL) AND ((octet_length(convert_to(template_name, 'UTF8'::name)) >= 1) AND (octet_length(convert_to(template_name, 'UTF8'::name)) <= 128)) AND (template_name ~ '^[a-z0-9][a-z0-9._-]*$'::text) AND (octet_length(template_content_digest) = 32)))),
    CONSTRAINT create_session_command_template_provenance_versioned CHECK (((storage_version >= 4) OR ((template_name IS NULL) AND (template_content_digest IS NULL)))),
    CONSTRAINT create_session_command_tool_approval_closed CHECK ((dangerous_tool_auto_approval = ANY (ARRAY['disabled'::text, 'approve_all'::text])))
);


--
-- Name: create_session_from_imported_frontier_command; Type: TABLE; Schema: public
--

CREATE TABLE create_session_from_imported_frontier_command (
    command_id uuid CONSTRAINT create_session_from_imported_frontier_comma_command_id_not_null NOT NULL,
    command_kind text CONSTRAINT create_session_from_imported_frontier_com_command_kind_not_null NOT NULL,
    storage_version smallint CONSTRAINT create_session_from_imported_frontier__storage_version_not_null NOT NULL,
    imported_conversation_id uuid CONSTRAINT create_session_from_imported__imported_conversation_id_not_null NOT NULL,
    imported_frontier_entry_id uuid CONSTRAINT create_session_from_importe_imported_frontier_entry_id_not_null NOT NULL,
    imported_frontier_position numeric(20,0) CONSTRAINT create_session_from_importe_imported_frontier_position_not_null NOT NULL,
    imported_relationship_kind text CONSTRAINT create_session_from_importe_imported_relationship_kind_not_null NOT NULL,
    creation_cause text CONSTRAINT create_session_from_imported_frontier_c_creation_cause_not_null NOT NULL,
    ancestry_kind text CONSTRAINT create_session_from_imported_frontier_co_ancestry_kind_not_null NOT NULL,
    initial_defaults_version numeric(20,0) CONSTRAINT create_session_from_imported__initial_defaults_version_not_null NOT NULL,
    model_selection_kind text CONSTRAINT create_session_from_imported_fron_model_selection_kind_not_null NOT NULL,
    direct_model_selection_id uuid,
    model_alias_id uuid,
    model_selection_reference uuid GENERATED ALWAYS AS (COALESCE(direct_model_selection_id, model_alias_id)) STORED,
    result_kind text CONSTRAINT create_session_from_imported_frontier_comm_result_kind_not_null NOT NULL,
