    claimed_until timestamp with time zone NOT NULL
);


--
-- Name: repo_watch_stale_review_clearance_recovery_cursor; Type: TABLE; Schema: public
--

CREATE TABLE repo_watch_stale_review_clearance_recovery_cursor (
