    CONSTRAINT turn_model_settings_resolved_documents CHECK (((jsonb_typeof(per_call_model_settings) = 'object'::text) AND (jsonb_typeof(resolved_model_settings) = 'object'::text) AND (jsonb_typeof(adjustments) = 'array'::text)))
);


