ALTER TABLE ONLY web_usage_call_projection
    ADD CONSTRAINT web_usage_call_identity_fk FOREIGN KEY (model_call_id) REFERENCES model_call_identity(model_call_id) ON UPDATE RESTRICT ON DELETE RESTRICT;


