ALTER TABLE ONLY workspace
    ADD CONSTRAINT workspace_command_fk FOREIGN KEY (command_id, command_kind, storage_version) REFERENCES durable_command(command_id, command_kind, storage_version) MATCH FULL ON UPDATE RESTRICT ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED;

--
-- Function search-path pins.
--
-- Reachable-from-a-check-constraint functions must carry a pinned search
-- path or a logical restore fails while evaluating constraints during the
-- data copy. The pin has to name the schema the migration selected rather
-- than a literal, so it is applied here through current_schema instead of
-- inline in each CREATE FUNCTION, which is what pg_dump would have done.
-- crates/persistence/tests/search_path_postgres.rs is the guard.
--

DO $baseline_search_path$
DECLARE
    signature text;
BEGIN
    -- the server default captured at creation time by SET search_path FROM CURRENT
    FOREACH signature IN ARRAY ARRAY[
        'accepted_input_projected_text(uuid)',
        'adjust_repo_watch_latest_event_obligation_count(uuid, bigint)',
        'adjust_repo_watch_pull_request_work_count(text, numeric, bigint, bigint)',
        'append_session_timeline_event_fact()',
        'append_session_timeline_input_bytes()',
        'append_session_timeline_transcript_bytes()',
        'apply_goal_generation_queued_delta(uuid, numeric, integer)',
        'clear_repo_watch_current_held_dispatch()',
        'credit_goal_turn_generation_work_fact()',
        'decrement_repo_watch_repository_obligation_count(text)',
        'goal_event_pursued_generation(text, numeric)',
        'goal_turn_generation_is_pursued(uuid, uuid)',
        'increment_repo_watch_pull_request_session_count()',
        'increment_repo_watch_repository_obligation_count(text)',
        'initialize_session_timeline_fact()',
        'maintain_repo_watch_pull_request_held_count()',
        'maintain_repo_watch_pull_request_obligation_count()',
        'maintain_repo_watch_repository_held_count()',
        'maintain_repo_watch_repository_obligation_count()',
        'maintain_session_catalog_last_activity()',
        'project_repo_watch_current_held_dispatch()',
        'project_repo_watch_singleton_cooldown()',
        'project_web_search_accepted_input()',
        'project_web_search_assistant_text()',
        'project_web_search_context_summary()',
        'project_web_search_session_metadata()',
        'project_web_search_steering_input()',
        'project_web_search_tool_batch()',
        'reconcile_session_timeline_goal_work_fact()',
        'record_operator_attention_metadata_change()',
        'refresh_session_live_goal_queue()',
        'refresh_session_live_queued_turn(uuid, uuid)',
        'refresh_session_live_queued_turn_from_goal()',
        'refresh_session_live_queued_turn_from_lifecycle()',
        'remember_repo_watch_repository_key()',
        'stamp_repo_watch_dispatch_action_target()',
        'stamp_repo_watch_dispatch_batch_target()',
        'stamp_repo_watch_webhook_projection_delivery()',
        'update_session_timeline_work_fact()',
        'web_search_projection_chunks(text)',
        'web_search_projection_requires_session_address()'
    ] LOOP
        EXECUTE format('ALTER FUNCTION %s SET search_path TO "$user", %I',
                   signature, current_schema);
    END LOOP;
    -- a pin that names no user schema, so it needs no substitution
    FOREACH signature IN ARRAY ARRAY[
        'reject_eval_call_outside_run_recording()',
        'stamp_eval_run_recording_transaction()'
    ] LOOP
        EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog, pg_temp',
                   signature);
    END LOOP;
    -- the canonical restore-safe pin: the migration-selected schema, then pg_catalog, then pg_temp
    FOREACH signature IN ARRAY ARRAY[
        'advance_review_finding_event_head()',
        'assert_reconciliation_required_turn_final_state(uuid)',
        'assert_review_finding_event_head_complete(uuid)',
        'authenticate_review_finding_event_head()',
        'canonical_tool_json(text)',
        'canonical_tool_json_number(text)',
        'configured_git_remote_name_is_valid(text)',
        'configured_git_remote_url_is_valid(text)',
        'context_frontier_member_position(uuid, uuid, uuid, uuid)',
        'context_frontier_preserves_prefix(uuid, uuid, uuid)',
        'convergence_sweep_retry_budget()',
        'create_review_finding_event_head()',
        'evaluation_corpus_path_components_bounded(text)',
        'evaluation_corpus_text_is_nonblank_control_free(text)',
        'guard_review_finding_event_head_change()',
        'imported_content_encoding_kind(bytea)',
        'imported_encoding_length_at(bytea, integer)',
        'imported_encoding_skip_attestation(bytea, integer, text, integer)',
        'imported_encoding_skip_boolean(bytea, integer)',
        'imported_encoding_skip_media_source(bytea, integer)',
        'imported_encoding_skip_number(bytea, integer)',
        'imported_encoding_skip_structured(bytea, integer, integer)',
        'imported_encoding_skip_text(bytea, integer)',
        'imported_encoding_skip_tool_result(bytea, integer, integer)',
        'repo_watch_branch_is_valid(text)',
        'repo_watch_convergence_check_names_are_valid(text[])',
        'repo_watch_convergence_threads_are_valid(text[])',
        'repo_watch_labels_are_valid(text[])',
        'repo_watch_login_is_valid(text)',
        'repo_watch_repository_is_valid(text)',
        'repo_watch_rule_id_is_valid(text)',
        'require_context_compaction_exact_evidence()',
        'require_review_finding_event_head_complete()',
        'require_review_finding_event_sequence()',
        'require_session_delegation_event_payload()',
        'require_terminal_delegated_turn_result()',
        'valid_tool_json(text)',
        'workspace_root_path_is_valid(text)'
    ] LOOP
        EXECUTE format('ALTER FUNCTION %s SET search_path TO %I, pg_catalog, pg_temp',
                   signature, current_schema);
    END LOOP;
END
$baseline_search_path$;

--
-- Singleton bootstrap rows.
--
-- A schema-only dump carries no rows, but five singleton tables are seeded by
-- the migration that creates them and are read before anything can write them:
-- the hub-fence generation the daemon advances at startup, the outbox sequence
-- and delivery cursors every append allocates through, and the two automatic
-- reconciliation cursors. Without these rows a fresh database boots into
-- "outbox event sequence exhausted" on its first append. The values are the
-- ones the chain leaves on a database with no other data in it.
--

INSERT INTO automatic_reconciliation_discovery_state (singleton, after_turn_id, high_turn_id) VALUES (true, NULL, NULL);
INSERT INTO automatic_reconciliation_supersession_state (singleton, after_turn_id, high_turn_id) VALUES (true, NULL, NULL);
INSERT INTO hub_fence_state (singleton, generation) VALUES (true, 1);
INSERT INTO outbox_delivery_state (singleton, delivered_through, last_delivery_xid) VALUES (true, 0, NULL);
INSERT INTO outbox_sequence_state (singleton, last_sequence, last_allocation_xid) VALUES (true, 0, NULL);

--
-- Restore body validation for anything applied after this migration.
--

RESET check_function_bodies;
